void	G_error_clear_m13(void)
{
	ERROR_m13	*err;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// call G_set_error_m13() for causal errors only
	// return error local error condition for errors returned from functions, no messages necessary
	// superuser function - any thread can call
	
	// clear error

	err = &globals_m13->error;
	pthread_mutex_lock_m13(&err->mutex);

	err->code = E_NONE_m13;
	err->signal = 0;
	*err->message = 0;
	err->line = 0;
	err->function = NULL;
	isem_chown_m13(&err->isem, 0);
	
	pthread_mutex_unlock_m13(&err->mutex);

	return_void_m13;
}


si4	G_error_code_m13(void)
{
	si4		code;
	ERROR_m13	*err;
	
	
	err = &globals_m13->error;
	
	pthread_mutex_lock_m13(&err->mutex);
	
	code = err->code;
	
	pthread_mutex_unlock_m13(&err->mutex);

	return(code);
}


void	G_error_message_m13(const si1 *fmt, ...)
{
	ui4		behavior;
	va_list		v_args;
	

	behavior = G_current_behavior_m13();
	
	if (behavior & IGNORE_ERROR_m13)
		return;
	
	// RED suppressible text to stderr with option to exit program
	if (!(behavior & SUPPRESS_ERROR_OUTPUT_m13)) {
		#ifndef MATLAB_m13
		fprintf(stderr, TC_RED_m13);
		#endif
		
		va_start(v_args, fmt);
		vfprintf_m13(stderr_m13, fmt, v_args);
		va_end(v_args);
			
		#ifndef MATLAB_m13
		fprintf(stderr, TC_RESET_m13);
		fflush(stderr);
		#endif
	}
	
	if (behavior & RETURN_ON_FAIL_m13)
		return;
	
	exit_m13(E_GEN_m13);
}


static tern	G_escrow_derive_master_m13(const si1 *password_bytes, ui1 level, UH_m13 *uh, ui1 *master)
{
	ui1	dk[SHA_HASH_BYTES_m13], salt[CRYPTO_KDF_SALT_BYTES_m13];
	ui4	iterations;

	// PBKDF2 password bytes -> master under this universal header's salt & the LEVEL's iteration count (the slow step).
	// level (1/2/3) selects uh->kdf_exponent[level-1]; the caller passes the level the password bytes are being tried as.

	if (uh->session_UID == UID_NO_ENTRY_m13) {
		G_set_error_m13(E_CRYP_m13, "universal header session UID not set (required as KDF salt)");
		return FALSE_m13;
	}
	G_build_kdf_salt_m13(uh, salt);
	iterations = (ui4) 1 << uh->kdf_exponent[level - 1];
	SHA_pbkdf2_m13((ui1 *) password_bytes, PASSWORD_BYTES_m13, salt, CRYPTO_KDF_SALT_BYTES_m13, iterations, dk);
	memcpy(master, dk, CRYPTO_MASTER_BYTES_m13);
	G_secure_erase_m13(dk, SHA_HASH_BYTES_m13);

	return TRUE_m13;
}


static tern	G_escrow_validate_master_m13(const ui1 *cand_master, ui1 level, UH_m13 *uh)
{
	ui1	hash[SHA_HASH_BYTES_m13], putative_L1_master[CRYPTO_MASTER_BYTES_m13];
	si4	i;

	// is cand_master the master secret of the given level, per this universal header's validation fields?
	// level 1: direct HMAC fingerprint; level 2: transitively through the level 1 field (chain XOR)

	if (level == 1) {
		SHA_hmac_m13(cand_master, CRYPTO_MASTER_BYTES_m13, (ui1 *) CRYPTO_VALIDATE_STRING_m13, (si8) strlen(CRYPTO_VALIDATE_STRING_m13), hash);
		if (memcmp(hash, uh->level_1_password_validation_field, PASSWORD_VALIDATION_FIELD_BYTES_m13) == 0)
			return TRUE_m13;
		return FALSE_m13;
	}
	// level 2
	if (G_all_zeros_m13(uh->level_2_password_validation_field, PASSWORD_VALIDATION_FIELD_BYTES_m13) == TRUE_m13)
		return FALSE_m13;
	SHA_hmac_m13(cand_master, CRYPTO_MASTER_BYTES_m13, (ui1 *) CRYPTO_CHAIN_STRING_m13, (si8) strlen(CRYPTO_CHAIN_STRING_m13), hash);
	for (i = 0; i < CRYPTO_MASTER_BYTES_m13; ++i)
		putative_L1_master[i] = hash[i] ^ uh->level_2_password_validation_field[i];

	return G_escrow_validate_master_m13(putative_L1_master, 1, uh);
}


si4	G_estimate_password_bits_m13(const si1 *password)
{
	si1	lower[MAX_PASSWORD_STRING_BYTES_m13], unleet[MAX_PASSWORD_STRING_BYTES_m13];
	si4	i, j, len, pool, bits;
	sf8	best[MAX_PASSWORD_STRING_BYTES_m13], cost;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// Conservative entropy estimate, in bits, for a CREATION-TIME password.  Used only to SUGGEST a
	// KDF exponent (G_suggest_kdf_exponent_m13()) - never to accept or reject a password, & never at
	// read time.  Callers apply a further haircut on top: see CRYPTO_KDF_ESTIMATE_HAIRCUT_m13.
	//
	// Method: the password is DECOMPOSED into the cheapest sequence of recognizable tokens, & their
	// costs are summed.  This is what makes multi-word passphrases score honestly - "correcthorse"
	// is two dictionary lookups, not twelve random characters - which a per-character or single-
	// discount model gets badly wrong in the unsafe direction.  Minimum over all segmentations is
	// found by dynamic programming: best[i] = min over j < i of best[j] + cost(span j..i).
	//
	// Estimating entropy from one sample is formally impossible, so this is used only where being
	// wrong is safe: too LOW an estimate merely buys more KDF iterations.

	if (STR_is_empty_m13(password) == TRUE_m13)
		return_m13(0);

	len = (si4) strlen(password);
	if (len > (MAX_PASSWORD_STRING_BYTES_m13 - 1))
		len = MAX_PASSWORD_STRING_BYTES_m13 - 1;

	// MULTIBYTE (non-ascii) passwords: the analysis below is byte-oriented, so a UTF-8 character
	// would be counted as its 2-4 constituent bytes & credited far more entropy than it carries
	// (8 Greek letters = 16 bytes would score ~80 bits instead of ~45).  That is the UNSAFE
	// direction - it would suggest too FEW KDF iterations - so until the estimator is made
	// character-aware, any non-ascii password returns 0 bits & therefore receives the standing
	// default exponent.  Nothing here precludes proper multibyte support: make the token walk
	// operate on decoded characters & give PW_char_pool_m13() a per-script alphabet size, & the
	// rest of the machinery (segmentation, tables, costs) is unchanged.
	for (i = 0; i < len; ++i)
		if ((ui1) password[i] > 127)
			return_m13(0);
	for (i = 0; i < len; ++i) {
		lower[i] = (password[i] >= 'A' && password[i] <= 'Z') ? (password[i] + 32) : password[i];
		unleet[i] = PW_unleet_m13(lower[i]);
	}
	lower[len] = unleet[len] = 0;
	pool = PW_char_pool_m13(password, len);

	// cheapest explanation of every prefix
	best[0] = (sf8) 0.0;
	for (i = 1; i <= len; ++i) {
		best[i] = (sf8) -1.0;
		for (j = 0; j < i; ++j) {
			cost = best[j] + PW_token_cost_m13(lower, unleet, password, j, i - j, pool);
			if (best[i] < (sf8) 0.0 || cost < best[i])
				best[i] = cost;
		}
	}

	bits = (si4) best[len];

	return_m13((bits < 0) ? 0 : bits);
}


si1	G_exists_m13(const si1 *path)
{
	si1			tmp_path[PATH_BYTES_m13];
	si4			err;
	struct_stat_m13 	sb;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// can be used for files or directories
	
	if (STR_is_empty_m13(path) == TRUE_m13)
		return_m13(DOES_NOT_EXIST_m13);
		
	G_full_path_m13(path, tmp_path);
	
	G_push_behavior_m13(RETURN_QUIETLY_m13);
	err = stat_m13(tmp_path, &sb);
	G_pop_behavior_m13();
	if (err) {
		if (err == ENOENT)
			return_m13(DOES_NOT_EXIST_m13);
		return_m13(EXISTS_ERR_m13);
	}
	
#if defined MACOS_m13 || defined LINUX_m13
	if (S_ISDIR(sb.st_mode))
		return_m13(DIR_EXISTS_m13);
#endif
#ifdef WINDOWS_m13
	if ((sb.st_mode & S_IFMT) == S_IFDIR)
		return_m13(DIR_EXISTS_m13);
#endif
	
	return_m13(FILE_EXISTS_m13);
}


si8	G_file_length_m13(void *fp, const si1 *path)
{
	si4			fd;
	tern			is_std;
	si8			len;
	FILE_m13		*m13_fp;
	struct_stat_m13		sb;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// pass either FILE pointer, or path to file
		
	m13_fp = NULL;
	if (fp) {
		is_std = FILE_is_std_m13(fp);  // fp not NULL
		if (is_std == FALSE_m13) {
			m13_fp = (FILE_m13 *) fp;
			if (m13_fp->flags & FILE_FLAGS_LEN_m13)
				return_m13(m13_fp->len);
		}
		fd = fileno_m13(fp);
	} else if (STR_is_empty_m13(path) == TRUE_m13) {
		G_set_error_m13(E_GEN_m13, "both fp & path are empty");
		return_m13(-1);
	} else {
		is_std = UNKNOWN_m13;
	}
	
	if (fp)
		fstat_m13(fd, &sb);
	else
		stat_m13(path, &sb);
	len = (si8) sb.st_size;
	
	if (is_std == FALSE_m13)
		m13_fp->len = len;
	
	return_m13(len);
}


si1	**G_file_list_m13(si1 **file_list, si4 *n_files, const si1 *enclosing_directory, const si1 *name, const si1 *extension, ui4 flags)
{
	tern	regex;
	si1	tmp_enclosing_directory[PATH_BYTES_m13], tmp_path[PATH_BYTES_m13];
	si1	tmp_name[PATH_BYTES_m13], tmp_extension[16], tmp_ext[16], *buffer, *c, *c2;
	si1	**tmp_ptr_ptr;
	ui4	path_parts;
	si4	i, j, n_in_files, *n_out_files;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// can be used to get a directory list also
	// file_list entries, enclosing_directory, name, & extension can contain regexp
	// if file_list is null it will be allocated
	
	n_in_files = *n_files;
	n_out_files = n_files;
	path_parts = flags & GFL_PATH_PARTS_MASK_m13;
	
	// shortcut for nothing to do (file_list passed, paths are from root, & contain no regex)
	if (file_list && n_in_files > 0) {
		if (G_check_file_list_m13(file_list, n_in_files) == TRUE_m13) {
			if ((flags & GFL_FREE_INPUT_LIST_m13) == 0) {  // caller expects a copy to be returned
				tmp_ptr_ptr = (si1 **) calloc_2D_m13((size_t) n_in_files, PATH_BYTES_m13, sizeof(si1));
				for (i = 0; i < n_in_files; ++i)
					strcpy(tmp_ptr_ptr[i], file_list[i]);
				file_list = tmp_ptr_ptr;
			}
			goto GFL_CONDITION_RETURN_DATA_m13;
		}
	}
	
	// file list passed:
	// If list components do not have a file name, and one is passed, it is used.
	// If list components do not have a file name, and none is passed, "*" is used.
	// If list components do not have an enclosing directory, and one is passed, it is used.
	// If list components do not have an enclosing directory, and none is passed, G_full_path_m13() is used.
	// If list components do not have an extension, and one is passed, it is used.
	// If list components do not have an extension, and none is passed, none is used.
	// copy incoming arguments so as not to modify, and in case they are statically allocated
	if (enclosing_directory == NULL)
		*tmp_enclosing_directory = 0;
	else
		strcpy(tmp_enclosing_directory, enclosing_directory);
	enclosing_directory = tmp_enclosing_directory;
				
	if (name == NULL)
		*tmp_name = 0;
	else
		strcpy(tmp_name, name);
	name = tmp_name;
	
	if (extension == NULL)
		*tmp_extension = 0;
	else
		strcpy(tmp_extension, extension);
	extension = tmp_extension;
	
	regex = FALSE_m13;
	if (file_list) {
		if (*enclosing_directory)  // resolve the base directory to a full path up front, so bare-name
			G_full_path_m13(enclosing_directory, tmp_enclosing_directory);  // entries prepend to a full path (intent: full paths regardless of how listed)
		tmp_ptr_ptr = (si1 **) calloc_2D_m13((size_t) n_in_files, PATH_BYTES_m13, sizeof(si1));
		// copy file_list
		for (i = 0; i < n_in_files; ++i) {
			// check for regex
			if (regex == FALSE_m13)
				regex = STR_contains_regex_m13(file_list[i]);
			// fill in list entry path components
			G_path_parts_m13(file_list[i], tmp_path, NULL, tmp_ext);  // for tmp_ext only (see below)
			// Resolve every entry to a FULL PATH, mirroring how a user would list at a terminal - then
			// the list is sorted & trimmed to the GFL_* output.  "Has a directory?" must be judged from
			// the RAW entry: G_path_parts_m13() always resolves to root (via G_full_path_m13()), so its
			// path output is never empty & cannot be used to detect a bare name.
			if (STR_is_empty_m13(file_list[i]) == TRUE_m13) {  // nothing to list (NULL / empty)
				*tmp_ptr_ptr[i] = 0;
			} else if (strchr(file_list[i], DIR_BREAK_m13) == NULL) {  // bare name, no directory
				if (*enclosing_directory)  // base directory given => prepend it (already full, above)
					sprintf_m13(tmp_ptr_ptr[i], "%s/%s", enclosing_directory, file_list[i]);
				else  // no base => relative to current directory
					G_full_path_m13(file_list[i], tmp_ptr_ptr[i]);
			} else {  // entry carries a directory (relative or absolute) => resolve to full (abs is idempotent)
				G_full_path_m13(file_list[i], tmp_ptr_ptr[i]);
			}
			if (*tmp_ext == 0 && *extension)
				sprintf_m13(tmp_ptr_ptr[i], "%s.%s", tmp_ptr_ptr[i], extension);
		}
 		if (flags & GFL_FREE_INPUT_LIST_m13)
			free_2D_m13((void **) file_list, n_in_files);
		file_list = tmp_ptr_ptr;
	}

	// no file_list passed (+/- enclosing_directory, +/- name, +/- extension, are passed instead)
	// If no enclosing_directory passed, G_full_path_m130() is used.
	// If no name is passed, "*" is used.
	// If no extension is passed, none is used.
	else {  // file_list == NULL
		file_list = (si1 **) calloc_2D_m13((size_t) 1, PATH_BYTES_m13, sizeof(si1));
		G_full_path_m13(enclosing_directory, (si1 *) enclosing_directory);
		enclosing_directory = (const si1 *) tmp_enclosing_directory;
		if (*name)
			sprintf_m13(file_list[0], "%s/%s", enclosing_directory, name);
		else
			sprintf_m13(file_list[0], "%s/*", enclosing_directory);
		if (*extension)
			sprintf_m13(file_list[0], "%s.%s", file_list[0], extension);
		n_in_files = 1;
		if (STR_contains_regex_m13(file_list[0]) == TRUE_m13)
			regex = TRUE_m13;
	}

	// expand regex (use system shell to expand regex)
	if (regex == TRUE_m13) {

	#if defined MACOS_m13 || defined LINUX_m13
		si1		*command;
		si4		r_val;
		size_t		len;

		len = n_in_files * PATH_BYTES_m13;
		if (flags & GFL_INCLUDE_INVISIBLE_m13)
			len <<= 1;
		len += 16;
		command = (si1 *) malloc((size_t) len);
		if (command == NULL) {
			G_set_error_m13(E_ALLOC_m13, NULL);
			return_m13(NULL);
		}
		#ifdef MACOS_m13
		strcpy(command, "/bin/ls -1d");
		#endif
		#ifdef LINUX_m13
		strcpy(command, "/usr/bin/ls -1d");
		#endif
		for (i = 0; i < n_in_files; ++i) {
			STR_escape_chars_m13(file_list[i], (si1) 0x20, PATH_BYTES_m13);  // escape spaces
			STR_escape_chars_m13(file_list[i], (si1) 0x27, PATH_BYTES_m13);  // escape apostrophes
			STR_escape_chars_m13(file_list[i], (si1) 0x60, PATH_BYTES_m13);  // escape grave accent
			len = sprintf_m13(command, "%s %s", command, file_list[i]);
			if (flags & GFL_INCLUDE_INVISIBLE_m13) {
				G_path_parts_m13(file_list[i], NULL, (si1 *) name, (si1 *) extension);
				len = sprintf_m13(command, "%s %s/.%s", command, enclosing_directory, name);  // explicitly include hidden files & directories with a prepended "."
				if (*extension)
					len = sprintf_m13(command, "%s.%s", command, extension);
			}
		}
		free_2D_m13((void **) file_list, n_in_files);

		buffer = NULL;
		r_val = system_pipe_m13(&buffer, 0, command, (SP_BEHAVIOR_PASSED_m13 | SP_SEPARATE_STREAMS_m13), RETURN_QUIETLY_m13, NULL, 0);  // pass NULL error buffer because don't actually want error output
		free(command);
		if (r_val || buffer == NULL) {
			if (buffer)
				free_m13(buffer);
			*n_out_files = 0;
			return_m13(NULL);
		}

		// count expanded file list
		c = buffer;
		*n_out_files = 0;
		while (*c++) {
			if (*c == '\n')
				++(*n_out_files);
		}
		if (*n_out_files == 0) {
			free_m13(buffer);
			return_m13(NULL);
		}

		// re-allocate
		file_list = (si1 **) calloc_2D_m13((size_t) *n_out_files, PATH_BYTES_m13, sizeof(si1));
		
		// build file list
		c = buffer;
		for (i = 0; i < *n_out_files; ++i) {
			c2 = file_list[i];
			while (*c != '\n')
				*c2++ = *c++;
			*c2 = 0;
			++c;
		}
	#endif  // MACOS_m13 || LINUX_m13
		
	#ifdef WINDOWS_m13
		buffer = NULL;
		*n_out_files = WN_ls_1d_to_buf_m13(file_list, n_in_files, TRUE_m13, &buffer);
		free_m13(file_list);
		if (*n_out_files <= 0) {  // error
			*n_out_files = 0;
			return_m13(NULL);
		}

		// re-allocate
		file_list = (si1 **) calloc_2D_m13((size_t) *n_out_files, PATH_BYTES_m13, sizeof(si1));

		// build file list
		c = buffer;
		for (i = 0; i < *n_out_files; ++i) {
			c2 = file_list[i];
			while (*c != '\n' && *c != '\r' && *c != 0)
				*c2++ = *c++;
			*c2 = 0;
			if (*c == '\r')
				++c;
			++c;
		}
	#endif  // WINDOWS_m13
		
		free_m13(buffer);
	}

GFL_CONDITION_RETURN_DATA_m13:
	
	// return requested path parts.  Use LOCAL scratch buffers (not the name/extension/enclosing_directory
	// args) to parse each file: the shortcut above jumps here without normalizing those args, so they may
	// still be NULL - keeping the fast path fast while this stays crash-safe.
	for (i = j = 0; i < *n_out_files; ++i) {
		G_path_parts_m13(file_list[i], tmp_enclosing_directory, tmp_name, tmp_extension);
		if ((flags & GFL_INCLUDE_INVISIBLE_m13) == 0)  // exclude invisible files
			if (*tmp_name == '.')
				continue;
		if ((flags & GFL_INCLUDE_PARITY_m13) == 0)  // exclude parity files (PRTY_is_parity_m13() is more robust, but this is more efficient)
			if (strncmp_m13(tmp_name, "parity", 6) == 0)
				continue;
		switch (path_parts) {
			case GFL_FULL_PATH_m13:
				if (i != j)
					strcpy(file_list[j], file_list[i]);
				break;
			case (GFL_PATH_m13 | GFL_NAME_m13):
				sprintf_m13(file_list[j], "%s/%s", tmp_enclosing_directory, tmp_name);
				break;
			case (GFL_NAME_m13 | GFL_EXTENSION_m13):
				sprintf(file_list[j], "%s.%s", tmp_name, tmp_extension);
				break;
			case GFL_NAME_m13:
				strcpy(file_list[j], tmp_name);
				break;
			default:
				G_set_error_m13(E_GEN_m13, "unrecognized path component combination (path_parts == 0x%08x)", path_parts);
				return_m13(NULL);
		}
		++j;
	}
	*n_out_files = j;

	// sort file list (so results are consistent across operating systems)
	STR_sort_m13(file_list, *n_out_files);

	return_m13(file_list);
}


FILE_TIMES_m13	*G_file_times_m13(FILE_m13 *fp, const si1 *path, FILE_TIMES_m13 *ft, tern set_time)
{
	FILE	*std_fp;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif
	
	if (fp == NULL && STR_is_empty_m13(path) == TRUE_m13) {
		G_set_error_m13(E_GEN_m13, "both fp & path are empty");
		return_m13(NULL);
	}

	std_fp = NULL;
	if (fp) {
		if (FILE_is_std_m13(fp) == TRUE_m13)
			std_fp = (FILE *) fp;
		else
			std_fp = fp->fp;
	}

	// caller must free
	if (ft == NULL)
		ft = (FILE_TIMES_m13 *) malloc_m13(sizeof(FILE_TIMES_m13));

#if defined MACOS_m13 || defined LINUX_m13
	si4			fd;
	struct_stat_m13		sb;
	struct timeval 		set_times[2] = {0};
	
	
	// set times: access and modification only
	if (set_time == TRUE_m13) {
		// set access & modification times to current time
		if (ft == NULL) {
			gettimeofday(set_times, NULL);
			set_times[1] = set_times[0];
		} else {  // use passed times (if non-zero)
			if (ft->access) {
				set_times[0].tv_sec = ft->access / (si8) 1000000;
				set_times[0].tv_usec = ft->access % (si8) 1000000;
			}
			if (ft->modification) {
				set_times[1].tv_sec = ft->modification / (si8) 1000000;
				set_times[1].tv_usec = ft->modification % (si8) 1000000;
			}
		}
	}
	
	if (std_fp == NULL) {
		stat(path, &sb);
	} else {
		fd = fileno(std_fp);
		fstat(fd, &sb);
	}

	#ifdef MACOS_m13
		#ifdef _DARWIN_FEATURE_64_BIT_INODE
			ft->creation = ((si8) sb.st_birthtimespec.tv_sec * (si8) 1000000) + ((si8) sb.st_birthtimespec.tv_nsec / (si8) 1000);
		#else
			ft->creation = ((si8) sb.st_ctimespec.tv_sec * (si8) 1000000) + ((si8) sb.st_ctim.tv_nsec / (si8) 1000);  // time of last status change - may be creation time - not guaranteed
		#endif
		ft->access = ((si8) sb.st_atimespec.tv_sec * (si8) 1000000) + ((si8) sb.st_atimespec.tv_nsec / (si8) 1000);
		ft->modification = ((si8) sb.st_mtimespec.tv_sec * (si8) 1000000) + ((si8) sb.st_mtimespec.tv_nsec / (si8) 1000);
	#endif
	#ifdef LINUX_m13
		ft->creation = ((si8) sb.st_ctim.tv_sec * (si8) 1000000) + ((si8) sb.st_ctim.tv_nsec / (si8) 1000);  // time of last status change - may be creation time - not guaranteed
		ft->access = ((si8) sb.st_atim.tv_sec * (si8) 1000000) + ((si8) sb.st_atim.tv_nsec / (si8) 1000);
		ft->modification = ((si8) sb.st_mtim.tv_sec * (si8) 1000000) + ((si8) sb.st_mtim.tv_nsec / (si8) 1000);
	#endif

	// set times: access and modification only
	if (set_time == TRUE_m13) {
		if (set_times[0].tv_sec == 0) {
			set_times[0].tv_sec = ft->access / (si8) 1000000;
			set_times[0].tv_usec = ft->access % (si8) 1000000;
		}
		if (set_times[1].tv_sec == 0) {
			set_times[1].tv_sec = ft->modification / (si8) 1000000;
			set_times[1].tv_usec = ft->modification % (si8) 1000000;
		}
		utimes(path, set_times);
	}
	
	return_m13(ft);
#endif  // MACOS_m13 || LINUX_m13

#ifdef WINDOWS_m13
	si4		fd;
	HANDLE		file_h;
	FILETIME	win_create_time, win_access_time, win_modify_time;
	FILETIME	set_access_time, set_modify_time;
	SYSTEMTIME 	sys_time;
	
	
	if (set_time == TRUE_m13) {
		if (ft == NULL) {
			GetSystemTime(&sys_time);
			SystemTimeToFileTime(&sys_time, &set_access_time);
			set_modify_time = set_access_time;
		} else {
			set_access_time = WN_uutc_to_win_time_m13(ft->access);
			set_modify_time = WN_uutc_to_win_time_m13(ft->modification);
		}
	}

	if (std_fp == NULL) {
		if ((file_h = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL)) == INVALID_HANDLE_VALUE) {
			G_set_error_m13(E_GEN_m13, "CreateFile failed with error %d", GetLastError());
			return_m13(NULL);
		}
	} else {
		fd = _fileno(std_fp);
		if ((file_h = (HANDLE) _get_osfhandle(fd)) == INVALID_HANDLE_VALUE) {
			G_set_error_m13(E_GEN_m13, "get_osfhandle failed with error %d", GetLastError());
			return_m13(NULL);
		}
	}
	
	if (set_time == TRUE_m13) {
		if (!SetFileTime(file_h, NULL, &set_access_time, &set_modify_time)) {
			G_set_error_m13(E_GEN_m13, "SetFileTime failed with error %d", GetLastError());
			return_m13(NULL);
		}
	}

	if (!GetFileTime(file_h, &win_create_time, &win_access_time, &win_modify_time)) {
		G_set_error_m13(E_GEN_m13, "GetFileTime failed with error %d", GetLastError());
		return_m13(NULL);
	}
	
	if (ft == NULL) {
		ft = (FILE_TIMES_m13 *) malloc_m13(sizeof(FILE_TIMES_m13));
		if (ft == NULL)
			return_m13(NULL);
	}

	ft->creation = WN_time_to_uutc_m13(win_create_time);
	ft->access = WN_time_to_uutc_m13(win_access_time);
	ft->modification = WN_time_to_uutc_m13(win_modify_time);
	
	if (std_fp == NULL)
		CloseHandle(file_h);
	
	return_m13(ft);
#endif
}


CONTIGUON_m13	*G_find_discontinuities_m13(void *level_header, si8 *n_contigua)
{
	si1				tmp_str[PATH_BYTES_m13];
	si4				i, start_seg_num, end_seg_num, seg_idx, n_segs, last_seg_num;
	si8				j, k, nc, n_indices, *sample_offsets;
	sf8				samp_period, sf8_samps;
	FPS_m13				**tsi_fps;
	LH_m13				*lh;
	PROC_GLOBS_m13			*pg;
	TS_IDX_m13			*tsi, *last_tsi;
	TS_METADATA_SECTION_2_m13	*md2;
	SEG_m13				*seg;
	CHAN_m13			*chan;
	SESS_m13			*sess;
	CONTIGUON_m13			*contigua;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// The difference between this function & G_build_contigua_m13(), is that this does not use time slice as delimiter for returned contigua.
	// Caller is responsible for freeing contigua.
	
	lh = (LH_m13 *) level_header;
	switch (lh->type_code) {
		case TS_SEG_TYPE_CODE_m13:
			seg = (SEG_m13 *) lh;
			chan = NULL;
			start_seg_num = end_seg_num = seg->metadata_fps->uh->segment_number;
			break;
		case TS_CHAN_TYPE_CODE_m13:
		case SESS_TYPE_CODE_m13:
			pg = G_proc_globs_m13(lh);
			if (lh->type_code == TS_CHAN_TYPE_CODE_m13) {
				chan = (CHAN_m13 *) lh;
			} else {
				chan = pg->current_session.index_channel;
				if (chan->type_code != TS_CHAN_TYPE_CODE_m13) {
					sess = (SESS_m13 *) lh;
					chan = sess->ts_chans[0];
				}
			}
			start_seg_num = 1;
			end_seg_num = pg->current_session.n_segments;
			break;
		case VID_CHAN_TYPE_CODE_m13:
		case VID_SEG_TYPE_CODE_m13:
			G_set_error_m13(E_GEN_m13, "not coded for video channels yet");
			return_m13(NULL);
		default:
			G_set_error_m13(E_GEN_m13, "invalid level type");
			return_m13(NULL);
	}

	n_segs = (end_seg_num - start_seg_num) + 1;
	tsi_fps = (FPS_m13 **) calloc((size_t) n_segs, sizeof(FPS_m13 *));
	if (tsi_fps == NULL) {
		G_set_error_m13(E_ALLOC_m13, NULL);
		return_m13(NULL);
	}
	sample_offsets = (si8 *) malloc((size_t) n_segs * sizeof(si8));
	if (sample_offsets == NULL) {
		G_set_error_m13(E_ALLOC_m13, NULL);
		free(tsi_fps);
		return_m13(NULL);
	}
	
	// get time series indices & sample offsets
	seg_idx = start_seg_num - 1;  // all segments always mapped => direct index
	if (seg_idx == FALSE_m13)
		return_m13(NULL);
	samp_period = (sf8) 0.0;
	for (i = 0, j = seg_idx; i < n_segs; ++i, ++j) {
		if (chan) {
			seg = chan->segs[j];
			sprintf_m13(tmp_str, "%s/%s.%s", seg->path, seg->name, TS_INDS_TYPE_STR_m13);
			seg->ts_inds_fps = FPS_read_m13(seg->ts_inds_fps, 0, FPS_FULL_FILE_m13, 0, tmp_str, "r", NULL, NULL, LH_NO_FLAGS_m13);
			sprintf_m13(tmp_str, "%s/%s.%s", seg->path, seg->name, TS_METADATA_TYPE_STR_m13);
			seg->metadata_fps = FPS_read_m13(seg->metadata_fps, FPS_FULL_FILE_m13, METADATA_BYTES_m13, 1, tmp_str, "r", NULL, NULL, LH_NO_FLAGS_m13);
		}
		tsi_fps[i] = seg->ts_inds_fps;
		md2 = &seg->metadata_fps->metadata->time_series_section_2;
		sample_offsets[i] = md2->session_start_sample_number;
		if (samp_period == (sf8) 0.0)
			samp_period = (sf8) 1.0e6 / md2->sampling_frequency;
	}
	
	// count contigua
	nc = 0;
	for (i = 0; i < n_segs; ++i) {
		tsi = tsi_fps[i]->ts_inds;
		n_indices = tsi_fps[i]->uh->n_entries - 1;  // exclude terminal index
		for (j = 0; j < n_indices; ++j)
			if (tsi[j].file_offset < 0)
				++nc;
	}
	contigua = (CONTIGUON_m13 *) calloc_m13((size_t) nc, sizeof(CONTIGUON_m13));
	
	// start first contiguon
	tsi = tsi_fps[0]->ts_inds;
	contigua[0].start_time = tsi[0].start_time;
	contigua[0].start_samp_num = 0;
	contigua[0].start_seg_num = start_seg_num;
	nc = 0;
	last_tsi = tsi;
	last_seg_num = 1;

	// fill in contigua
	for (i = start_seg_num, j = 0; i <= end_seg_num; ++i, ++j) {
		tsi = tsi_fps[j]->ts_inds;
		n_indices = tsi_fps[j]->uh->n_entries - 1;  // exclude terminal index
		for (k = 0; k < n_indices; ++k) {
			// make sample numbers global
			tsi[k].start_samp_num += sample_offsets[j];
			if (tsi[k].file_offset < 0) {
				// skip first block encountered, as it is a duplicate of contigua[0]'s start info
				if (k == 0 && j == 0) {
					last_tsi = tsi + k;
					last_seg_num = i;
					continue;
				}
				// finish last contiguon
				sf8_samps = (sf8) (tsi[k].start_samp_num - last_tsi->start_samp_num);
				contigua[nc].end_time = last_tsi->start_time + (si8) ((sf8_samps * samp_period) + (sf8) 0.5);
				contigua[nc].end_samp_num = tsi[k].start_samp_num - 1;
				contigua[nc].end_seg_num = last_seg_num;
				// start new contiguon
				++nc;
				contigua[nc].start_time = tsi[k].start_time;
				contigua[nc].start_samp_num = tsi[k].start_samp_num;
				contigua[nc].start_seg_num = i;
				// nc = 0;
			}
		  last_tsi = tsi + k;
		  last_seg_num = i;
		}
	}
	// finish last contiguon (using terminal index values)
	contigua[nc].end_time = tsi[k].start_time;
	contigua[nc].end_samp_num = tsi[k].start_samp_num + sample_offsets[j - 1] - 1;
	contigua[nc].end_seg_num = last_seg_num;
	
	// clean up
	if (lh->type_code == TS_SEG_TYPE_CODE_m13)
		for (i = 0; i < n_segs; ++i)
			FPS_free_m13(tsi_fps + i);
	free(tsi_fps);
	free(sample_offsets);
	
	*n_contigua = nc + 1;
	
	return_m13(contigua);
}


si8	G_find_index_m13(SEG_m13 *seg, si8 target, ui4 mode)
{
	ui4			target_frame_number;
	si8			i, n_inds, seg_start_time, seg_end_time;
	si8			block_samples, block_duration, seg_samples, clip_frames, clip_duration, seg_frames;
	TS_IDX_m13	*tsi_base, *tsi;
	VID_IDX_m13		*vi_base, *vi;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// returns index containing requested time/sample
	// returns -1 if before first index
	// returns n_inds - 1 (terminal index index) if after last index
	// NO_OVERFLOWS_m13: restrict returned index to valid segment values (ORed with search type)
	// INDEX_SEARCH_m13: indices must be session-relative (global indexing)
	// TIME_SEARCH_m13: times must be offset uutc

	n_inds = seg->ts_inds_fps->uh->n_entries - 1;  // account for terminal index here - cleaner code below
	
	if (seg->type_code == TS_SEG_TYPE_CODE_m13) {
		tsi_base = seg->ts_inds_fps->ts_inds;
		if (mode & TIME_SEARCH_m13) {
			seg_start_time = seg->ts_inds_fps->uh->segment_start_time;
			if (target < seg_start_time) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(0);
				return_m13(-1);
			}
			seg_end_time = seg->ts_inds_fps->uh->segment_end_time;
			if (target > seg_end_time) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(n_inds - 1);
				return_m13(n_inds);
			}
			// estimate index
			block_duration = (si8) (seg->metadata_fps->metadata->time_series_section_2.maximum_block_duration + (sf8) 0.5);
			i = (target - seg_start_time) / block_duration;
			if (i > n_inds)
				i = n_inds;
			// search: exit at first index <= target
			tsi = tsi_base + i;
			if (tsi->start_time <= target) {  // forward linear search
				while (tsi->start_time <= target)
					++tsi;
				--tsi;
			} else {  // backward linear search
				while (tsi->start_time > target)
					--tsi;
			}
		} else {  //  INDEX_SEARCH_m13
			target -= seg->metadata_fps->metadata->time_series_section_2.session_start_sample_number;  // convert target to local indexing
			if (target < 0) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(0);
				return_m13(-1);
			}
			seg_samples = seg->metadata_fps->metadata->time_series_section_2.number_of_samples;
			if (target >= seg_samples) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(n_inds - 1);
				return_m13(n_inds);
			}
			// estimate index
			block_samples = (si8) seg->metadata_fps->metadata->time_series_section_2.maximum_block_samples;
			i = target / block_samples;
			if (i > n_inds)
				i = n_inds;
			// search: exit at first index <= target
			tsi = tsi_base + i;
			if (tsi->start_samp_num <= target) {  // forward linear search
				while (tsi->start_samp_num <= target)
					++tsi;
				--tsi;
			} else {  // backward linear search
				while (tsi->start_samp_num > target)
					--tsi;
			}
		}
		i = tsi - tsi_base;
	} else {  // LEVEL_VIDEO_SEG_m13
		vi_base = seg->vid_inds_fps->vid_inds;
		if (mode & TIME_SEARCH_m13) {
			seg_start_time = seg->vid_inds_fps->uh->segment_start_time;
			if (target < seg_start_time) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(0);
				return_m13(-1);
			}
			seg_end_time = seg->vid_inds_fps->uh->segment_end_time;
			if (target > seg_end_time) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(n_inds - 1);
				return_m13(n_inds);
			}
			// estimate index
			clip_duration = (si8) (seg->metadata_fps->metadata->video_section_2.maximum_clip_duration + (sf8) 0.5);
			i = (target - seg_start_time) / clip_duration;
			if (i > n_inds)
				i = n_inds;
			// search: exit at first index <= target
			vi = vi_base + i;
			if (vi->start_time <= target) {  // forward linear search
				while (vi->start_time <= target)
					++vi;
				--vi;
			} else {  // backward linear search
				while (vi->start_time > target)
					--vi;
			}
		} else {  //  INDEX_SEARCH_m13  (target frame numbers must be in absolute frame)
			target -= seg->metadata_fps->metadata->video_section_2.session_start_frame_number;  // convert target to local indexing
			if (target < 0) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(0);
				return_m13(-1);
			}
			seg_frames = seg->metadata_fps->metadata->video_section_2.number_of_frames;
			if (target >= seg_frames) {
				if (mode & NO_OVERFLOWS_m13)
					return_m13(n_inds - 1);
				return_m13(n_inds);
			}
			// estimate index
			clip_frames = (si8) seg->metadata_fps->metadata->video_section_2.maximum_clip_frames;
			i = target / clip_frames;
			// search: exit at first index <= target
			vi = vi_base + i;
			target_frame_number = (ui4) target;
			if (vi->start_frame_num <= target_frame_number) {  // forward linear search
				while (vi->start_frame_num <= target_frame_number)
					++vi;
				--vi;
			} else {  // backward linear search
				while (vi->start_frame_num > target_frame_number)
					--vi;
			}
		}
		i = vi - vi_base;
	}
	
	if (mode & NO_OVERFLOWS_m13) {
		if (i == -1)
			return_m13(0);
		else if (i == n_inds)
			return_m13(n_inds - 1);
	}
	
	return_m13(i);
}


#if defined MACOS_m13 || defined LINUX_m13
si1	*G_find_metadata_file_m13(const si1 *path, si1 *md_path)
{
	tern		match;
	si1		*c, *name;
	ui4		code;
	size_t		len;
	DIR		*dir;
	struct dirent	*entry;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// large directory trees can take a long time to search with "find" or "ls"
	// cumbersome code => function unrolled for speed

	if (STR_is_empty_m13(path) == TRUE_m13) {
		G_set_error_m13(E_GEN_m13, "path is empty");
		return_m13(NULL);
	}

	// caller responsible for freeing, if allocated
	if (md_path == NULL)
		md_path = (si1 *) malloc_m13((size_t) PATH_BYTES_m13);
	
	// find entry level
	G_full_path_m13(path, md_path);
	code = G_MED_type_code_from_string_m13(md_path);
	switch(code) {
		case SESS_TYPE_CODE_m13:
			break;
		case TS_CHAN_TYPE_CODE_m13:
		case VID_CHAN_TYPE_CODE_m13:
			goto FIND_MDF_CHAN_LEVEL_m13;
		case TS_SEG_TYPE_CODE_m13:
		case VID_SEG_TYPE_CODE_m13:
			goto FIND_MDF_SEG_LEVEL_m13;
		default:
			G_set_error_m13(E_FMED_m13, "input path must be a MED session, channel, or segment directory");  // global error
			return_m13(NULL);
	}
	
	// session level
	dir = opendir(md_path);
	if (dir == NULL) {
		G_set_error_m13(E_GEN_m13, "opendir() failed");
		return_m13(NULL);
	}
	match = FALSE_m13;
	while ((entry = readdir(dir))) {
		if (entry->d_type != DT_DIR)
			continue;
		name = entry->d_name;
		if (*name == '.')
			continue;
		len = strlen(name);
		if (len < 6)  // min 1 letter channel name + 5 chars for extension
			continue;
		c = name + len - 5;
		if (*c++ != '.')
			continue;
		// check for MED channel ([tv]icd extension)
		if (*c == 't' || *c == 'v') {
			if (*++c == 'i') {
				if (*++c == 'c') {
					if (*++c == 'd') {
						match = TRUE_m13;
						break;
					}
				}
			}
		}
	}
	
	if (match == FALSE_m13) {
		G_set_error_m13(E_META_m13, NULL);  // global error
		return_m13(NULL);
	}
	
	len = strlen(md_path);
	md_path[len++] = '/';
	strcpy(md_path + len, name);
	closedir(dir);

FIND_MDF_CHAN_LEVEL_m13:
	dir = opendir(md_path);
	if (dir == NULL) {
		G_set_error_m13(E_GEN_m13, "opendir() failed");
		return_m13(NULL);
	}
	match = FALSE_m13;
	while ((entry = readdir(dir))) {
		if (entry->d_type != DT_DIR)
			continue;
		name = entry->d_name;
		if (*name == '.')
			continue;
		len = strlen(name);
		if (len < 12)  // min 1 letter channel name + 6 chars for segment designation + 5 chars for extension
			continue;
		c = name + len - 5;
		if (*c++ != '.')
			continue;
		// check for MED segment ([tv]isd extension)
		if (*c == 't' || *c == 'v') {
			if (*++c == 'i') {
				if (*++c == 's') {
					if (*++c == 'd') {
						match = TRUE_m13;
						break;
					}
				}
			}
		}
	}
	
	if (match == FALSE_m13) {
		G_set_error_m13(E_META_m13, NULL);  // global error
		return_m13(NULL);
	}
	
	len = strlen(md_path);
	md_path[len++] = '/';
	strcpy(md_path + len, name);
	closedir(dir);

FIND_MDF_SEG_LEVEL_m13:
	dir = opendir(md_path); // open the path
	if (dir == NULL) {
		G_set_error_m13(E_META_m13, NULL);
		return_m13(NULL); // if was not able, return
	}
	match = FALSE_m13;
	while ((entry = readdir(dir))) {  // if we were able to read something from the directory
		if (entry->d_type != DT_REG && entry->d_type != DT_LNK)
			continue;
		name = entry->d_name;
		if (*name == '.')
			continue;
		len = strlen(name);
		if (len < 12)  // min 1 letter channel name + 6 chars for segment desiognation + 5 chars for extension
			continue;
		c = name + len - 5;
		if (*c++ != '.')
			continue;
		// check for MED metadata ([tv]met extension)
		if (*c == 't' || *c == 'v') {
			if (*++c == 'm') {
				if (*++c == 'e') {
					if (*++c == 't') {
						match = TRUE_m13;
						break;
					}
				}
			}
		}
	}

	if (match == FALSE_m13) {
		G_set_error_m13(E_META_m13, "no metadata found in \"%s\"", md_path);
		return_m13(NULL);
	}
	
	len = strlen(md_path);
	md_path[len++] = '/';
	strcpy(md_path + len, name);
	closedir(dir);

	return_m13(md_path);
}
#endif  // MACOS_m13 || LINUX_m13


#ifdef WINDOWS_m13
si1	*G_find_metadata_file_m13(const si1 *path, si1 *md_path)
{
	si1			*name;
	ui4			code;
	size_t			len;
	WIN32_FIND_DATAA 	ffd;
	HANDLE			find_h;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// large directory trees can take a long time to search with "find" or "ls"
	// cumbersome code => function unrolled for speed

	// caller responsible for freeing, if allocated
	if (md_path == NULL)
		md_path = (si1 *) malloc_m13((size_t) PATH_BYTES_m13);
	
	// find entry level
	G_full_path_m13(path, md_path);
	code = G_MED_type_code_from_string_m13(path);
	switch(code) {
		case SSR_TYPE_CODE_m13:
			G_path_parts_m13(md_path, md_path, NULL, NULL);
			code = SESS_TYPE_CODE_m13;
			break;
		case SESS_TYPE_CODE_m13:
			break;
		case TS_CHAN_TYPE_CODE_m13:
		case VID_CHAN_TYPE_CODE_m13:
			goto WN_FIND_MDF_CHAN_LEVEL_m13;
		case TS_SEG_TYPE_CODE_m13:
		case VID_SEG_TYPE_CODE_m13:
			goto WN_FIND_MDF_SEG_LEVEL_m13;
		default:
			G_set_error_m13(E_FMED_m13, "input path must be a MED session, channel, or segment directory");  // global error
			return_m13(NULL);
	}
	
	// session level
	len = strlen(md_path);
	strcpy(md_path + len, "\\*.?icd");
	find_h = FindFirstFileA((LPCSTR) md_path, &ffd);
	if (find_h == INVALID_HANDLE_VALUE) {
		G_set_error_m13(E_GEN_m13, "FindFirstFileA() failed");
		return_m13(NULL);
	}
	name = ffd.cFileName;
	while (*name == '.') {
		if (FindNextFileA(find_h, &ffd) == 0)
			return_m13(NULL);
		name = ffd.cFileName;
	}
	strcpy(md_path + len + 1, name);
	FindClose(find_h);
	
	// channel level
WN_FIND_MDF_CHAN_LEVEL_m13:
	len = strlen(md_path);
	strcpy(md_path + len, "\\*.?isd");
	find_h = FindFirstFileA((LPCSTR) md_path, &ffd);
	if (find_h == INVALID_HANDLE_VALUE) {
		G_set_error_m13(E_GEN_m13, "FindFirstFileA() failed");
		return_m13(NULL);
	}
	name = ffd.cFileName;
	while (*name == '.') {
		if (FindNextFileA(find_h, &ffd) == 0)
			return_m13(NULL);
		name = ffd.cFileName;
	}
	strcpy(md_path + len + 1, name);
	FindClose(find_h);

	// segment level
WN_FIND_MDF_SEG_LEVEL_m13:
	len = strlen(md_path);
	strcpy(md_path + len, "\\*.?met");
	find_h = FindFirstFileA((LPCSTR) md_path, &ffd);
	if (find_h == INVALID_HANDLE_VALUE) {
		G_set_error_m13(E_META_m13, "no metadata found in \"%s\"", md_path);
		return_m13(NULL);
	}
	name = ffd.cFileName;
	while (*name == '.') {
		if (FindNextFileA(find_h, &ffd) == 0)
			return_m13(NULL);
		name = ffd.cFileName;
	}
	strcpy(md_path + len + 1, name);
	FindClose(find_h);

	return_m13(md_path);
}
#endif  // WINDOWS_m13


si8	G_find_record_index_m13(FPS_m13 *rec_inds_fps, si8 target_time, ui4 mode, si8 low_idx)
{
	si8		i, idx, n_inds, high_idx, high_time_diff, low_time_diff;
	REC_IDX_m13	*ri;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// Modes (note there can be multiple records with the same start time):
	//	FIND_CLOSEST_m13: If target_time == start_time, and there are multiple indices with the
	//			  same start time, the function will return the first of these indices.
	//			  If they are equally close, the lower index will be returned.
	//	FIND_LAST_BEFORE_m13
	//	FIND_FIRST_ON_OR_AFTER_m13
	//	FIND_LAST_ON_OR_BEFORE_m13
	//	FIND_FIRST_AFTER_m13
	//
	//	low_idx: as indices are often needed in pairs, pass low_idx to reduce search time if known (if not, pass zero)

	// NOTE: this function does not currently handle record files with no terminal index
	// needs to be updated

	ri = rec_inds_fps->rec_inds;
	n_inds = rec_inds_fps->uh->n_entries;
	if (n_inds <= 1) {
		if (n_inds == 1) {
			if (ri->type_code == REC_Term_TYPE_CODE_m13)
				return_m13(NO_IDX_m13);  // only a terminal index, no records
		} else {
			return_m13(NO_IDX_m13); // no records
		}
	}

	if (target_time < ri[low_idx].start_time) {
		switch (mode) {
			case FIND_FIRST_AFTER_m13:
			case FIND_CLOSEST_m13:
			case FIND_FIRST_ON_OR_AFTER_m13:
				return_m13(low_idx);
			// "on" or "before" condition impossible
			case FIND_LAST_ON_OR_BEFORE_m13:
			case FIND_LAST_BEFORE_m13:
				return_m13(NO_IDX_m13);
			default:
				G_set_error_m13(E_GEN_m13, "unsupported mode (%u)", mode);
				return_m13(NO_IDX_m13);
		}
	}
	high_idx = n_inds - 1;
	if (ri[high_idx].type_code == REC_Term_TYPE_CODE_m13)
		--high_idx;  // last true index (only a terminal index handled above)
	if (target_time >= ri[high_idx].start_time) {
		switch (mode) {
			case FIND_CLOSEST_m13:
			case FIND_LAST_BEFORE_m13:
			case FIND_LAST_ON_OR_BEFORE_m13:
				return_m13(high_idx);
			// "on" or "after" condition impossible
			case FIND_FIRST_ON_OR_AFTER_m13:
			case FIND_FIRST_AFTER_m13:
				return_m13(NO_IDX_m13);
		}
	}
	if (low_idx == high_idx)
		return_m13(low_idx);
	
	// binary search
	do {
		idx = (low_idx + high_idx) >> 1;
		if (ri[idx].start_time > target_time)
			high_idx = idx;
		else
			low_idx = idx;
	} while ((high_idx - low_idx) > 1);
	if (target_time >= ri[high_idx].start_time)
		idx = high_idx;
	else if (target_time < ri[high_idx].start_time)
		idx = low_idx;
	// search exits with idx == FIND_LAST_ON_OR_BEFORE_m13 condition
	// i.e. where:  ri[idx].start_time <= target_time < ri[idx + 1].start_time
	// i.e. the last index where target_time >= index start_time

	switch (mode) {
		case FIND_CLOSEST_m13:
			low_time_diff = target_time - ri[idx].start_time;
			high_time_diff = ri[idx + 1].start_time - target_time;
			if (high_time_diff < low_time_diff)
				++idx;  // advance to first record of next time
			else
				for (i = idx - 1; ri[i].start_time == ri[idx].start_time; idx = i--);  // rewind to first record of this time
			break;
		case FIND_LAST_BEFORE_m13:
			if (target_time == ri[idx].start_time) {
				for (i = idx - 1; ri[i].start_time == ri[idx].start_time; idx = i--);  // rewind to first record of this time
				--idx;  // step back to last record of last time
			}
			// there may be other records with the same time preceding this one
			break;
		case FIND_FIRST_ON_OR_AFTER_m13:
			if (target_time == ri[idx].start_time)  // "on" condition
				for (i = idx - 1; ri[i].start_time == ri[idx].start_time; idx = i--);  // rewind to first record of this time
			else
				++idx;  // advance to first record of next time
		case FIND_LAST_ON_OR_BEFORE_m13:
			break;  // no rewind: there may be other records with the same time preceding this one
		case FIND_FIRST_AFTER_m13:
			++idx;  // advance to first record of next time
			break;
	}
	
	return_m13(idx);
}


si4	G_first_open_segment_m13(void *level_header)
{
	si4			i, sess_segs;
	LH_m13			*lh;
	PROC_GLOBS_m13		*pg;
	CHAN_m13		*chan;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// returns the index of the first OPEN (non-NULL) segment on the reference (index) channel; (si4) FALSE_m13 if none.
	// pass NULL for level header to get the main process proc_globs.
	// All channels open the same segment set, so this index is valid across channels - callers use it to reach an open
	// segment's metadata (e.g. sampling frequency) without requiring ephemeral metadata.
	// (Direct segment indexing is now just segment_number - 1 - all segments are always mapped, the per-channel segs
	// arrays are full-length & stable - so G_segment_index_m13()/G_check_segment_map_m13() were removed; only this
	// "find any open segment" scan remained useful.)

	lh = (LH_m13 *) level_header;
	pg = G_proc_globs_m13(lh);
	sess_segs = pg->current_session.n_segments;
	chan = pg->current_session.index_channel;
	if (chan == NULL) {
		G_set_error_m13(E_GEN_m13, "reference channel not set");
		return_m13((si4) FALSE_m13);
	}
	if (chan->segs == NULL) {
		G_set_error_m13(E_GEN_m13, "segments not allocated on reference channel \"%s\"", chan->name);
		return_m13((si4) FALSE_m13);
	}
	for (i = 0; i < sess_segs; ++i)
		if (chan->segs[i])
			return_m13(i);

	G_set_error_m13(E_GEN_m13, "no open segments on reference channel \"%s\"", chan->name);
	return_m13((si4) FALSE_m13);
}


si8	G_flen_m13(FILE_m13 *fp, const si1 *path)
{
	si8	offset;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// returns file data length including header, but excluding any pcrc data if present
	// returns FALSE_m13 on failure
	// see G_flen_m13() for FPS version
	
	// use fp, if possible
	if (fp) {
		offset = PCRC_offset_m13(fp, NULL, NULL);
		if (offset != FALSE_m13)
			return_m13(offset);
		
		// try to get a path
		if (STR_is_empty_m13(path) == TRUE_m13)
			path = fp->path;
	}
	
	// use path
	if (STR_is_empty_m13(path) == TRUE_m13) {
		G_set_error_m13(E_GEN_m13, "file path can't be determined");
		return_m13(FALSE_m13);
	}
	
	offset = PCRC_offset_m13(NULL, path, NULL);
	if (offset == FALSE_m13)
		return_m13(FALSE_m13);
	
	return_m13(offset);
}


tern	G_free_channel_m13(void *ptr)
{
	ui4			type_code;
	si4			i;
	CHAN_m13		*chan, **chan_ptr;
	SEG_m13			*seg;
	PROC_GLOBS_m13		*pg;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// pass CHAN_m13 *, or CHAN_m13 ** to NULL local pointer
	// returns FALSE_m13 if does not free channel
	
	if (ptr == NULL) {
		G_set_error_m13(E_GEN_m13, "pointer is null");
		return_m13(FALSE_m13);
	}
	type_code = *((ui4 *) ptr);
	if (CHANNEL_CODE_m13(type_code) == TRUE_m13) {
		chan = (CHAN_m13 *) ptr;
		chan_ptr = NULL;
	} else {
		chan_ptr = (CHAN_m13 **) ptr;
		chan = *chan_ptr;
		if (chan == NULL) {
			G_set_error_m13(E_GEN_m13, "segment is null");
			return_m13(FALSE_m13);
		}
		type_code = *((ui4 *) chan);
		if (CHANNEL_CODE_m13(type_code) == FALSE_m13) {
			G_set_error_m13(E_GEN_m13, "channel is invalid");
			return_m13(FALSE_m13);
		}
	}

	if (chan->segs) {
		pg = G_proc_globs_m13(chan);
		for (i = 0; i < pg->current_session.n_segments; ++i) {
			seg = chan->segs[i];
			if (seg)
				G_free_segment_m13(seg);
		}
		free_m13(chan->segs);  // ok whether allocated en bloc or not
	}
	if (chan->metadata_fps)
		FPS_free_m13(chan->metadata_fps);
	if (chan->rec_data_fps)
		FPS_free_m13(chan->rec_data_fps);
	if (chan->rec_inds_fps)
		FPS_free_m13(chan->rec_inds_fps);
	if (chan->contigua)
		free_m13(chan->contigua);
	
	// delete process globals
	if (chan->proc_globs)
		G_proc_globs_delete_m13((LH_m13 *) chan->proc_globs);

	// free
	if (chan->allocated == TRUE_m13) {
		free_m13(chan);
		if (chan_ptr)  // can't set stack addresses to NULL; shouldn't set en bloc addresses to NULL
			*chan_ptr = NULL;
	} else {
		memset(chan, 0, sizeof(CHAN_m13));
	}
	
	return_m13(TRUE_m13);
}


void	G_free_global_tables_m13(void)
{
	GLOBAL_TABLES_m13	*tables;
	
	
	tables = globals_m13->tables;
	if (tables == NULL)
		return;
		
	// constant lookup tables borrow .rodata masters (see the *_init_tables_m13() functions) - do not free, just clear
	tables->timezone_table = NULL;
	tables->country_aliases_table = NULL;
	tables->country_acronym_aliases_table = NULL;
	tables->AES_sbox_table = NULL;
	tables->AES_rsbox_table = NULL;
	tables->AES_rcon_table = NULL;
	tables->SHA_h0_table = NULL;
	tables->SHA_k_table = NULL;
	tables->CMP_normal_CDF_table = NULL;
	tables->CMP_VDS_threshold_map = NULL;
	tables->E_strings_table = NULL;

	if (tables->CRC_tables)  // CRC tables are COMPUTED at runtime (not a .rodata const) => guarded & sealed, free via the guarded path
		 G_guarded_table_free_m13((void *) tables->CRC_tables, (CRC_TABLES_m13 * sizeof(crc4 *)) + ((size_t) CRC_TABLES_m13 * CRC_TABLE_ENTRIES_m13 * sizeof(crc4)));
	if (tables->CMP_log_table) {  // COMPUTED entropy-estimator LUT => guarded & sealed, free via the guarded path
		G_guarded_table_free_m13((void *) tables->CMP_log_table, (size_t) CMP_LOG_TABLE_ENTRIES_m13 * sizeof(sf8));
		tables->CMP_log_table = NULL;
	}

	#ifdef WINDOWS_m13
	if (globals_m13->tables->hNTdll)
		FreeLibrary(globals_m13->tables->hNTdll);
	#endif

	// destroy mutex
	pthread_mutex_destroy_m13(&tables->mutex);
	
	free(tables);
	globals_m13->tables = NULL;
	
	return;
}


void	G_free_globals_m13(tern cleanup_for_exit)
{
	si4			i, list_size;
	FLOCK_ENTRY_m13		**lock_ptrs;
	PROC_GLOBS_m13		**pg_ptrs;
	ERROR_m13		*err;
	
#ifdef FT_DEBUG_m13
	FUNCTION_STACK_m13	**function_stack_ptrs;
#endif
	
	// unset signal traps (sometimes necessary for begugging)
	// G_set_signal_traps_m13(FALSE_m13);

	if (cleanup_for_exit == TRUE_m13) {
		tempclean_m13();
		#ifdef WINDOWS_m13
		WN_cleanup_m13();
		#endif
	}
	
	CMP_free_buffer_depot_m13();  // release pooled checkout/return scratch bundles

	pthread_mutex_lock_m13(&globals_m13->mutex);
	globals_m13->miscellaneous.suspend_stacks = TRUE_m13;
	++stacks_epoch_m13;  // invalidate every thread's cached function-stack pointer (stacks freed below)

	if (globals_m13->record_filters) {
		// often statically allocated, so can't just free()
		// e.g. si4 rec_filts = { REC_Seiz_TYPE_CODE_m13, REC_Note_TYPE_CODE_m13, NO_TYPE_CODE_m13 };
		// pg->record_filters = rec_filts;
		if (freeable_m13(globals_m13->record_filters) == TRUE_m13)
			free_m13(globals_m13->record_filters);
	}
			
	// (behavior stacks are thread-local - reclaimed per thread by their TSD destructor, nothing to free here)


	if (globals_m13->file_lock_list) {
		// file locks allocated in blocks of GLOBALS_FLOCK_LIST_SIZE_INCREMENT_m13
		list_size = globals_m13->file_lock_list->size;
		lock_ptrs = globals_m13->file_lock_list->lock_ptrs;
		// locks allocated in blocks of GLOBALS_FLOCK_LIST_SIZE_INCREMENT_m13
		for (i = 0; i < list_size; i += GLOBALS_FLOCK_LIST_SIZE_INCREMENT_m13)
			free(lock_ptrs[i]);
		free(lock_ptrs);
		pthread_mutex_destroy_m13(&globals_m13->file_lock_list->mutex);
		free(globals_m13->file_lock_list);
	}
	
#ifdef FT_DEBUG_m13
	if (globals_m13->function_stack_list) {
		// functions allocated for each stack
		list_size = globals_m13->function_stack_list->size;
		function_stack_ptrs = globals_m13->function_stack_list->stack_ptrs;
		for (i = 0; i < list_size; ++i)
			if (function_stack_ptrs[i]->size)
				free(function_stack_ptrs[i]->functions);
		// stacks allocated in blocks of GLOBALS_FUNCTION_STACKS_LIST_SIZE_INCREMENT_m13
		for (i = 0; i < list_size; i += GLOBALS_FUNCTION_STACKS_LIST_SIZE_INCREMENT_m13)
			free(function_stack_ptrs[i]);
		free(function_stack_ptrs);
		pthread_mutex_destroy_m13(&globals_m13->function_stack_list->mutex);
		free(globals_m13->function_stack_list);
	}
#endif
	
	if (globals_m13->proc_globs_list) {
		// Sgmt_recs_list allocated for each proc_glob
		list_size = globals_m13->proc_globs_list->size;
		pg_ptrs = globals_m13->proc_globs_list->proc_globs_ptrs;
		for (i = 0; i < list_size; ++i) {
			if (pg_ptrs[i]->_id) {
				pg_ptrs[i]->ref_count = 1;  // G_proc_globs_delete_m13 decrements & then checks == zero
				G_proc_globs_delete_m13((LH_m13 *) pg_ptrs[i]);
			}
		}
		// process globals allocated in blocks of GLOBALS_PROC_GLOBS_LIST_SIZE_INCREMENT_m13
		for (i = 0; i < list_size; i += GLOBALS_PROC_GLOBS_LIST_SIZE_INCREMENT_m13)
			free(pg_ptrs[i]);
		free(pg_ptrs);
		pthread_mutex_destroy_m13(&globals_m13->proc_globs_list->mutex);
		free(globals_m13->proc_globs_list);
	}

	if (globals_m13->thread_list) {
		if (globals_m13->thread_list->entries)
			free(globals_m13->thread_list->entries);
		pthread_mutex_destroy_m13(&globals_m13->thread_list->mutex);
		free(globals_m13->thread_list);
	}

	if (globals_m13->app_info)
		free(globals_m13->app_info);
	
#ifdef AT_DEBUG_m13
	if (globals_m13->AT_list) {
//		free_all_m13();  // display memory still allocated & free it
		free(globals_m13->AT_list->entries);
		pthread_mutex_destroy_m13(&globals_m13->AT_list->mutex);
		free(globals_m13->AT_list);
	}
#endif
	
	err = &globals_m13->error;
	pthread_mutex_destroy_m13(&err->mutex);
	isem_destroy_m13(&err->isem);

	G_free_global_tables_m13();
	
	globals_m13->miscellaneous.suspend_stacks = FALSE_m13;
	pthread_mutex_unlock_m13(&globals_m13->mutex);
	pthread_mutex_destroy_m13(&globals_m13->mutex);

	free(globals_m13);
	globals_m13 = NULL;  // a dangling pointer here made re-initialization skip G_init_globals_m13() & dereference the freed tables pointer

	return;
}


