si4	G_show_function_stack_m13(pid_t_m13 _id)
{
#ifdef FT_DEBUG_m13
	const si1		*thread_name;
	si1			*c, title[THREAD_NAME_BYTES_m13 + 48];
	si4			i, j, s, func_start_num;
	FUNCTION_ENTRY_m13	*frames;
	FUNCTION_STACK_m13	*stack;
	FT_SNAP_STACK_m13	*snap;
	pid_t_m13		_pid;


	// pass _id == 0 for error or local thread call
	// returns -1 on failure
	// error displays show the error snapshot (stacks & propagation as they were at the error);
	// non-error displays show the live stack of the requested thread

	if (_id == 0) {
		if (G_error_code_m13())
			_id = globals_m13->error.thread_id;
		else
			_id = gettid_m13();
	}

	// error snapshot display (causal thread & its ancestors; base of the chain shown first)
	if (FT_error_snapshot_m13.active == TRUE_m13 && FT_error_snapshot_m13.stacks[0]._id == _id) {
		for (j = 0, s = FT_error_snapshot_m13.n_stacks - 1; s >= 0; --s) {
			snap = FT_error_snapshot_m13.stacks + s;

			// print thread name (from the error's ancestry snapshot - snapshot threads may have exited)
			thread_name = G_error_chain_name_m13(snap->_id);
			if (thread_name)
				sprintf_m13(title, "Function Stack for %s(id: %lu)", thread_name, snap->_id);
			else
				sprintf_m13(title, "Function Stack for Thread %lu:", snap->_id);
			printf_m13("%s\n", title);

			// replace string characters with '-' (terminal zero preserved)
			c = title - 1;
			while (*++c)
				*c = '-';
			printf_m13("%s\n", title);

			// print frames
			frames = snap->frames;
			for (i = 0; i < snap->n_frames; ++i, ++j) {
				if (frames[i].return_line <= 0)
					printf_m13("%d)\t%s(%s%d -> ~%s)\n", j, frames[i].name, TC_BLUE_m13, frames[i].entry_line, TC_RESET_m13);
				else
					printf_m13("%d)\t%s(%s%d -> %d%s)\n", j, frames[i].name, TC_BLUE_m13, frames[i].entry_line, frames[i].return_line, TC_RESET_m13);
			}
			printf_m13("\n");
		}
		return(j);
	}

	// live stack display
	stack = G_function_stack_m13(_id);
	if (stack == NULL)
		return(-1);

	// recurse
	_pid = PROC_thread_parent_id_m13(_id);
	if (_pid) {
		func_start_num = G_show_function_stack_m13(_pid);
		if (func_start_num == -1)
			return(-1);
	} else {
		func_start_num = 0;
	}

	// print thread name
	thread_name = PROC_thread_name_m13(_id);
	if (thread_name)
		sprintf_m13(title, "Function Stack for %s(id: %lu)", thread_name, _id);
	else
		sprintf_m13(title, "Function Stack for Thread %lu:", _id);
	printf_m13("%s\n", title);

	// replace string characters with '-' (terminal zero preserved)
	c = title - 1;
	while (*++c)
		*c = '-';
	printf_m13("%s\n", title);
	
	// print stack
	for (i = 0, j = func_start_num; i <= stack->top_idx; ++i, ++j) {
		if (stack->functions[i].return_line <= 0)
			printf_m13("%d)\t%s(%s%d -> ~%s)\n", j, stack->functions[i].name, TC_BLUE_m13, stack->functions[i].entry_line, TC_RESET_m13);
		else
			printf_m13("%d)\t%s(%s%d -> %d%s)\n", j, stack->functions[i].name, TC_BLUE_m13, stack->functions[i].entry_line, stack->functions[i].return_line, TC_RESET_m13);
	}
	printf_m13("\n");

	return(j);

#endif  // FT_DEBUG_m13
	
	return(-1);
}


void	G_show_globals_m13(void)
{
	si4	i;
	

	printf_m13("\nGlobals\n=======\n");

	printf_m13("\nRecord Filters\n--------------\n");
	if (globals_m13->record_filters == NULL) {
		printf_m13("no entry\n");
	} else if (globals_m13->record_filters[0] == NO_TYPE_CODE_m13) {
		printf_m13("no entry\n");
	} else {
		printf_m13("0x%08x", globals_m13->record_filters[0]);
		for (i = 1; globals_m13->record_filters[i] != NO_TYPE_CODE_m13; ++i)
			printf_m13(", 0x%08x", globals_m13->record_filters[i]);
		printf_m13("\n");
	}

	printf_m13("\nBehavior\n-----");
	G_show_behavior_m13(globals_m13->default_behavior.code);
	
	printf_m13("\nError\n-----");
	G_show_error_m13();

	printf_m13("\nMiscellaneous\n-------------\n");
	if (*globals_m13->miscellaneous.temp_dir)
		printf_m13("Temporary File Directory: \"%s\"\n", globals_m13->miscellaneous.temp_dir);
	else
		printf_m13("Temporary File Directory: no entry\n");
	if (*globals_m13->miscellaneous.temp_file)
		printf_m13("Temporary File: \"%s\"\n", globals_m13->miscellaneous.temp_file);
	else
		printf_m13("Temporary File: no entry\n");
	printf_m13("File Creation umask: %u\n", globals_m13->miscellaneous.file_creation_umask);
	if (globals_m13->miscellaneous.file_lock_mode == FLOCK_MODE_NONE_m13)
		printf_m13("File Lock Mode: none\n");
	else if (globals_m13->miscellaneous.file_lock_mode == FLOCK_MODE_MED_m13)
		printf_m13("File Lock Mode: MED files only\n");
	else if (globals_m13->miscellaneous.file_lock_mode == FLOCK_MODE_ALL_m13)
		printf_m13("File Lock Mode: all files\n");
	else
		printf_m13("File Lock Mode: unrecognized (%hhd)\n", globals_m13->miscellaneous.file_lock_mode);
	printf_m13("Threading: %s\n", STR_tern_m13(globals_m13->miscellaneous.threading, TRUE_m13));
	printf_m13("Memory Mapping: %s\n", STR_tern_m13(globals_m13->miscellaneous.memory_mapping, TRUE_m13));
	printf_m13("CRC Mode: %u\n", globals_m13->miscellaneous.CRC_mode);
	printf_m13("Write Sorted Records: %s\n", STR_tern_m13(globals_m13->miscellaneous.write_sorted_records, TRUE_m13));
	printf_m13("Write Corrected Headers: %s\n", STR_tern_m13(globals_m13->miscellaneous.write_corrected_headers, TRUE_m13));
	printf_m13("Update File System Names: %s\n", STR_tern_m13(globals_m13->miscellaneous.update_file_system_names, TRUE_m13));
	printf_m13("Update Header Names: %s\n", STR_tern_m13(globals_m13->miscellaneous.update_header_names, TRUE_m13));
	printf_m13("Update MED Version: %s\n\n", STR_tern_m13(globals_m13->miscellaneous.update_MED_version, TRUE_m13));
	
	return;
}


