sf8	*CMP_lin_interp_2_sf8_m13(si8 *in_x, sf8 *in_y, si8 in_len, sf8 *out_y, si8 *out_len)
{
	tern	free_out_y = FALSE_m13;
	si8	i, local_out_len, *xp, dx, last_x;
	sf8	*yp, *oy, dy, last_y, step;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif
	
	// linear interpolation between points in (x,y) pairs at unitary spacing
		
	if (out_len == NULL)
		out_len = &local_out_len;
	*out_len = (in_x[in_len - 1] - in_x[0]) + 1;
	
	*out_len = (in_x[in_len - 1] - in_x[0]) + 1;
	if (out_y == NULL) {
		free_out_y = TRUE_m13;
		out_y = (sf8 *) malloc_m13((size_t) (*out_len << 3));
	}

	xp = in_x + 1;
	last_x = *xp;
	yp = in_y + 1;
	last_y = *yp;
	oy = out_y;
	*oy++ = *in_y;
	for (i = in_len - 1; i--;) {
		dx = *xp - last_x;
		if (dx <= 0) {
			if (dx)
				G_set_error_m13(E_CMP_m13, "x is not sorted");
			else
				G_set_error_m13(E_CMP_m13, "x is not unique");
			if (free_out_y == TRUE_m13)
				free_m13(out_y);
			return_m13(NULL);
		}
		dy = *yp - last_y;
		step = dy / dx;
		while (dx--)
			*oy++ = (last_y += step);
		last_x = *xp++;
		last_y = *yp++;
	}
	
	return_m13(out_y);
}


sf8	*CMP_lin_interp_sf8_m13(sf8 *in_data, si8 in_len, sf8 *out_data, si8 out_len)
{
	sf8 x, inc, f_bot_x, bot_y, range;
	si8 i, bot_x, top_x, last_bot_x;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (out_data == NULL)
		out_data = (sf8 *) malloc_m13((size_t) (out_len << 3));
	
	if (in_len <= 1) {
		if (in_len == 0)
			return_m13(NULL);
		for (i = 0; i < out_len; ++i)
			out_data[i] = in_data[0];
		return_m13(out_data);
	}
	if (in_len == out_len) {
		memcpy(out_data, in_data, (size_t) (in_len << 3));
		return_m13(out_data);
	}
	
	// interpolate
	--in_len; --out_len;
	inc = (sf8) in_len / (sf8) out_len;
	
	out_data[0] = in_data[0];
	if (out_len <= (in_len << 1)) {  // downsample, or upsample ratio <= 2:1 (upsampling this way is faster than below)
		for (x = inc, i = 1; i < out_len; ++i, x += inc) {
			top_x = (bot_x = (si8) x) + 1;
			out_data[i] = (x - (sf8) bot_x) * (in_data[top_x] - in_data[bot_x]) + in_data[bot_x];
		}
	} else {  // upsample ratio > 2:1
		for (last_bot_x = -1, x = inc, i = 1; i < out_len; ++i, x += inc) {
			bot_x = (si8) x;
			if (bot_x != last_bot_x) {
				range = in_data[bot_x + 1] - in_data[bot_x];
				bot_y = in_data[bot_x];
				f_bot_x = (sf8) bot_x;
				last_bot_x = bot_x;
			}
			out_data[i] = ((x - f_bot_x) * range) + bot_y;
		}
	}
	out_data[out_len] = in_data[in_len];
	
	return_m13(out_data);
}


si4	*CMP_lin_interp_si4_m13(si4 *in_data, si8 in_len, si4 *out_data, si8 out_len)
{
	sf8 x, inc, f_bot_x, bot_y, range;
	si8 i, bot_x, top_x, last_bot_x;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (out_data == NULL)
		out_data = (si4 *) malloc_m13((size_t) (out_len << 2));
	
	if (in_len <= 1) {
		if (in_len == 0)
			return_m13(NULL);
		for (i = 0; i < out_len; ++i)
			out_data[i] = in_data[0];
		return_m13(out_data);
	}
	if (in_len == out_len) {
		memcpy(out_data, in_data, (size_t) (in_len << 2));
		return_m13(out_data);
	}
	
	// interpolate
	--in_len; --out_len;
	inc = (sf8) in_len / (sf8) out_len;
	
	out_data[0] = in_data[0];
	if (out_len <= (in_len << 1)) {  // downsample, or upsample ratio <= 2:1
		for (x = inc, i = 1; i < out_len; ++i, x += inc) {
			top_x = (bot_x = (si8) x) + 1;
			out_data[i] = CMP_round_si4_m13((x - (sf8) bot_x) * ((sf8) in_data[top_x] - (sf8) in_data[bot_x]) + (sf8) in_data[bot_x]);
		}
	} else {  // upsample ratio > 2:1
		for (last_bot_x = -1, x = inc, i = 1; i < out_len; ++i, x += inc) {
			bot_x = (si8) x;
			if (bot_x != last_bot_x) {
				range = (sf8) in_data[bot_x + 1] - (sf8) in_data[bot_x];
				bot_y = (sf8) in_data[bot_x];
				f_bot_x = (sf8) bot_x;
				last_bot_x = bot_x;
			}
			out_data[i] = CMP_round_si4_m13(((x - f_bot_x) * range) + bot_y);
		}
	}
	out_data[out_len] = in_data[in_len];
	
	return_m13(out_data);
}


tern	CMP_lin_reg_2_si4_m13(si4 *x_input_buffer, si4 *y_input_buffer, si8 len, sf8 *m, sf8 *b)
{
	sf8	sx, sy, sxx, sxy, n, mx, my, x_val, y_val;
	si8	i;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// linear least_squares regression (2 array input)
	n = (sf8) len;
	sx = sy = sxx = sxy = (sf8) 0.0;
	for (i = len; i--;) {
		x_val = (sf8) *x_input_buffer++;
		y_val = (sf8) *y_input_buffer++;
		sx += x_val;
		sxx += x_val * x_val;
		sy += y_val;
		sxy += x_val * y_val;
	}
	
	mx = sx / n;
	my = sy / n;
	*m = (((sx * my) - sxy) / ((sx * mx) - sxx));
	*b = (my - (*m * mx));
		
	return_m13(TRUE_m13);
}


tern	CMP_lin_reg_si4_m13(si4 *input_buffer, si8 len, sf8 *m, sf8 *b)
{
	sf8	sx, sy, sxx, sxy, n, mx, my, c, val;
	si8	i;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// linear least_squares regression (1 array input)
	
	n = (sf8) len;
	sx = (n * (n + (sf8) 1.0)) / (sf8) 2.0;
	sxx = (n * (n + (sf8) 1.0) * ((n * (sf8) 2.0) + (sf8) 1.0)) / (sf8) 6.0;
	
	c = sy = sxy = (sf8) 0.0;
	for (i = len; i--;) {
		val = (sf8)*input_buffer++;
		sy += val;
		sxy += val * (c += (sf8) 1.0);
	}
	
	mx = sx / n;
	my = sy / n;
	*m = (((sx * my) - sxy) / ((sx * mx) - sxx));
	*b = (my - (*m * mx));
	
	return_m13(TRUE_m13);
}


sf8	CMP_LLP_score_m13(si4 *data, si8 len)
{
	sf8	scores[CMP_NS_BYTES_m13];

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// LOCAL LINEAR PREDICTION. The second difference is exactly the residual of predicting each sample by
	// linear extrapolation from the two before it; normalizing by the first difference makes the statistic
	// scale free. Returns [0,1]: 0 == perfectly predictable, 1 == at least as unpredictable as white noise.
	//
	// NORMALIZED BY sqrt(3), which is EXACT, not calibrated: for an iid sequence of variance v, Var(d1x) = 2v
	// & Var(d2x) = 6v, so the white-noise ratio of standard deviations is sqrt(6/2) = sqrt(3).
	//
	// ⚠️ SUMS OF SQUARES, not absolute values. Under the absolute form the white-noise reference drifts with
	// distribution shape - MEASURED gaussian 1.731, laplace 1.742, uniform 1.751, heavy-tailed 1.813, bimodal
	// 1.940 - so merely non-gaussian data reads as noisier than white noise & clips. Under the RMS form the
	// reference is sqrt(3) for ANY iid finite-variance sequence. On real data it matters: dataset y reads
	// 1.579 under the absolute form but 1.500 under RMS. (An earlier MATLAB prototype used 1.75, which is
	// sqrt(3) measured on UNIFORM white noise - rand, not randn.)
	//
	// The clip at 1 is meaningful: strong sample-to-sample alternation IS less predictable than white noise.
	// A flat block returns 0 - perfectly predictable, which is true. The ENTROPY score is what separates
	// flat-and-dead from smooth-and-real; these bytes are meant to be read as a vector.
	// ⚠️ A random walk scores 0.816 (sqrt(2)/sqrt(3)), not near 0: its increments are unpredictable even though
	// it looks smooth. And on a signal whose second difference falls below one quantization step, this measures
	// the QUANTIZATION FLOOR rather than the signal.
	//
	// ⭐ USEFUL SIDE EFFECT: this ratio is a SPECTRAL SLOPE proxy, computed for free. Var(d2)/Var(d1) is
	// 4*integral(sin^4 . S) / integral(sin^2 . S), which is 3 for a flat spectrum & falls as the spectrum
	// steepens. MEASURED on synthetic noise at 1 kHz: white (f^0) 254, pink (1/f) 232, brown (1/f^2) 207.
	// The background slope of neural data shifts in physiologically meaningful ways (state, depth of
	// anaesthesia, pathology), so this byte carries more than a noise verdict - it tracks that slope, and
	// nothing else in the block does.

	scores[CMP_NS_LLP_IDX_m13] = (sf8) 0.0;
	CMP_noise_scores_m13(data, len, scores, CMP_NS_LLP_SEL_m13);

	return_m13(scores[CMP_NS_LLP_IDX_m13]);
}


tern	CMP_noise_scores_m13(si4 *data, si8 len, sf8 *scores, ui4 which)
{
	const sf8	*norm_cdf;
	sf8		sx, sx2, mx, sd, val, z, H, Hmax, p, inv_n, d, dk, e, sn, sd2, r, run, tot, D, diff, ncdf_max;
	si8		i, span, n_bins, bin, cnt[CMP_NS_ENTROPY_BINS_m13], kcnt[CMP_NORMAL_CDF_TABLE_ENTRIES_m13];
	si4		mn, mx_i;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// ONE implementation of the three library-computed noise scores, sharing their passes over the data.
	// scores[] is sf8[CMP_NS_BYTES_m13] & each selected entry is written in [0,1]; unselected entries are left
	// alone. Byte 0 (line noise) is not produced here - it needs the filter, not a pass over the samples.
	//
	// Merged because all three walk the SAME array: separately they cost five passes (entropy needs extrema
	// then a histogram, normality needs mean/sd then a histogram, LLP needs one), and together they cost two.
	// The selector keeps a single-score caller from paying for the others, so the wrappers below stay honest.
	//
	// Each score is documented at its wrapper: CMP_entropy_deficit_m13(), CMP_KS_score_m13(), CMP_LLP_score_m13().

	if (data == NULL || scores == NULL || len < 1) {
		G_set_error_m13(E_CMP_m13, "noise scores need data & at least one sample");
		return_m13(FALSE_m13);
	}

	// ---- PASS 1: extrema, first two moments, & the LLP difference sums ---------------------------------
	mn = mx_i = data[0];
	sx = sx2 = sn = sd2 = (sf8) 0.0;
	d = (len > 1) ? ((sf8) data[1] - (sf8) data[0]) : (sf8) 0.0;
	for (i = 0; i < len; ++i) {
		val = (sf8) data[i];
		if (data[i] < mn)
			mn = data[i];
		else if (data[i] > mx_i)
			mx_i = data[i];
		sx += val;
		sx2 += val * val;
		if (i >= 2) {
			dk = val - (sf8) data[i - 1];
			e = d - dk;
			sn += e * e;
			sd2 += d * d;
			d = dk;
		}
	}
	mx = sx / (sf8) len;
	sd = sqrt((sx2 / (sf8) len) - (mx * mx));

	// ---- LLP (no second pass needed) ----------------------------------------------------------------------
	if (which & CMP_NS_LLP_SEL_m13) {
		if (len < 3 || sd2 <= (sf8) 0.0) {
			r = (sf8) 0.0;
		} else {
			r = sqrt(sn / sd2) / sqrt((sf8) 3.0);
			if (r > (sf8) 1.0)
				r = (sf8) 1.0;
		}
		scores[CMP_NS_LLP_IDX_m13] = r;
	}

	if ((which & (CMP_NS_ENTROPY_DEFICIT_SEL_m13 | CMP_NS_NON_NORMALITY_SEL_m13)) == 0)
		return_m13(TRUE_m13);

	// ---- PASS 2: both histograms together ------------------------------------------------------------------
	span = (si8) mx_i - (si8) mn + 1;
	n_bins = (span < (si8) CMP_NS_ENTROPY_BINS_m13) ? span : (si8) CMP_NS_ENTROPY_BINS_m13;
	if (n_bins < 1)
		n_bins = 1;
	memset((void *) cnt, 0, (size_t) n_bins * sizeof(si8));
	memset((void *) kcnt, 0, sizeof(kcnt));
	tot = (sf8) 0.0;
	for (i = 0; i < len; ++i) {
		val = (sf8) data[i];
		if (span > 1) {
			bin = (((si8) data[i] - (si8) mn) * n_bins) / span;
			if (bin >= n_bins)
				bin = n_bins - 1;
			++cnt[bin];
		}
		z = (val - mx) / sd;
		if (isnan(z))
			continue;
		bin = (si8) ((z + (sf8) 3.1) * (sf8) 10.0);
		if (bin < 0)
			bin = 0;
		else if (bin >= CMP_NORMAL_CDF_TABLE_ENTRIES_m13)
			bin = CMP_NORMAL_CDF_TABLE_ENTRIES_m13 - 1;
		++kcnt[bin];
		tot += (sf8) 1.0;
	}

	// ---- ENTROPY DEFICIT ------------------------------------------------------------------------------------
	if (which & CMP_NS_ENTROPY_DEFICIT_SEL_m13) {
		if (span <= 1) {
			scores[CMP_NS_ENTROPY_DEFICIT_IDX_m13] = (sf8) 1.0;   // flat: no information
		} else {
			inv_n = (sf8) 1.0 / (sf8) len;
			H = (sf8) 0.0;
			for (i = 0; i < n_bins; ++i) {
				if (cnt[i]) {
					p = (sf8) cnt[i] * inv_n;
					H -= p * log2(p);
				}
			}
			Hmax = log2((sf8) n_bins);
			if (Hmax <= (sf8) 0.0) {
				scores[CMP_NS_ENTROPY_DEFICIT_IDX_m13] = (sf8) 1.0;
			} else {
				H = (sf8) 1.0 - (H / Hmax);
				if (H < (sf8) 0.0) H = (sf8) 0.0;
				else if (H > (sf8) 1.0) H = (sf8) 1.0;
				scores[CMP_NS_ENTROPY_DEFICIT_IDX_m13] = H;
			}
		}
	}

	// ---- NORMALITY (Kolmogorov-Smirnov D, null corrected) ----------------------------------------------------
	if (which & CMP_NS_NON_NORMALITY_SEL_m13) {
		if (tot == (sf8) 0.0) {
			scores[CMP_NS_NON_NORMALITY_IDX_m13] = (sf8) 1.0;   // a point mass is maximally non-normal
		} else {
			if (globals_m13->tables->CMP_normal_CDF_table == NULL)
				CMP_init_tables_m13();
			norm_cdf = globals_m13->tables->CMP_normal_CDF_table;
			ncdf_max = norm_cdf[CMP_NORMAL_CDF_TABLE_ENTRIES_m13 - 1];
			run = D = (sf8) 0.0;
			for (i = 0; i < CMP_NORMAL_CDF_TABLE_ENTRIES_m13; ++i) {
				run += (sf8) kcnt[i];
				diff = (run / tot) - (norm_cdf[i] / ncdf_max);
				if (diff < (sf8) 0.0)
					diff = -diff;
				if (diff > D)
					D = diff;
			}
			D -= ((sf8) CMP_KS_NULL_COEF_m13 / sqrt(tot)) + (sf8) CMP_KS_NULL_FLOOR_m13;
			if (D < (sf8) 0.0) D = (sf8) 0.0;
			else if (D > (sf8) 1.0) D = (sf8) 1.0;
			scores[CMP_NS_NON_NORMALITY_IDX_m13] = D;
		}
	}

	return_m13(TRUE_m13);
}


tern	CMP_lock_buffers_m13(CMP_BUFFERS_m13 *buffers)
{
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// lock
	if (buffers->locked != TRUE_m13)
		buffers->locked = mlock_m13(buffers->buffer, -((si8) buffers->total_allocated_bytes));

	return_m13(buffers->locked);
}


// Mofified Akima cubic interpolation
// Attribution: modifications based on Matlab's adjustments to weights of Akima function
// Note: input x's are integers, output x's are floats
sf8	*CMP_mak_interp_sf8_m13(CMP_BUFFERS_m13 *in_bufs, si8 in_len, CMP_BUFFERS_m13 *out_bufs, si8 out_len)
{
	si8	*index, *si8_p1, *si8_p2;
	si8 	i, j, filled_slopes, in_nm1, tmp_delta_len;
	si8	*in_x;
	sf8 	*delta, *tmp_delta, *weights, *slopes;
	sf8	delta_0, delta_m1, delta_n, delta_n1;
	sf8	*sf8_p1, *sf8_p2, *sf8_p3, *sf8_p4, *sf8_p5, *sf8_p6;
	sf8	sf8_v1, sf8_v2, sf8_v3, sf8_v4;
	sf8 	*in_y, *dx, *out_x, *tmp_out_x, *out_y, *coefs[4];

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// Note: This function strays from the usual medlib template in that it does not allocate its processing buffers if not passed.
	// This is just because this function inherently complex anyway, and because otherwise there would be too many arguments for my taste.

	// input buffers
	// allocate with in_bufs =  CMP_allocate_buffers_m13(NULL, CMP_MAK_INTERP_INPUT_BUFFERS_m13, in_len + CMP_MAK_INTERP_PAD_SAMPLES_m13, sizeof(sf8), FALSE_m13, FALSE_m13);
	in_y = (sf8 *) in_bufs->buffer[CMP_MAK_IN_Y_BUF];  // == 0
	in_x = (si8 *) in_bufs->buffer[CMP_MAK_IN_X_BUF];  // == 1
	dx = (sf8 *) in_bufs->buffer[2];
	tmp_delta = (sf8 *) in_bufs->buffer[3];
	slopes = (sf8 *) in_bufs->buffer[4];
	weights = (sf8 *) in_bufs->buffer[5];
	coefs[0] = (sf8 *) in_bufs->buffer[6];
	coefs[1] = (sf8 *) in_bufs->buffer[7];
	
	// output buffers
	// allocate with out_bufs = CMP_allocate_buffers_m13(NULL, CMP_MAK_INTERP_OUTPUT_BUFFERS_m13, out_len, sizeof(sf8), FALSE_m13, FALSE_m13);
	out_y = (sf8 *) out_bufs->buffer[CMP_MAK_OUT_Y_BUF];  // == 0
	out_x = (sf8 *) out_bufs->buffer[CMP_MAK_OUT_X_BUF];  // == 1
	tmp_out_x = (sf8 *) out_bufs->buffer[2];
	index = (si8 *) out_bufs->buffer[3];

	// special cases
	if (in_len <= 1) {
		if (in_len == 0)
			return_m13(out_y);
		for (i = 0; i < out_len; ++i)
			out_y[i] = in_y[0];
		return_m13(out_y);
	}
	if (in_len == out_len) {
		sf8_p1 = out_x;
		si8_p1 = in_x;
		for (i = in_len; i--;)  // check for non-linearly spaced interpolation
			if (*sf8_p1++ != (sf8) *si8_p1++)
				break;
		if (i == -1) {
			memcpy(out_y, in_y, (size_t) (in_len << 3));
			return_m13(out_y);
		}
	}

	in_nm1 = in_len - 1;
	tmp_delta_len = in_nm1 + 4;
	delta = tmp_delta + 2;
	si8_p1 = in_x;
	si8_p2 = in_x + 1;
	sf8_p1 = dx;
	sf8_p2 = delta;
	sf8_p3 = in_y;
	sf8_p4 = in_y + 1;
	for (i = in_nm1; i--;) {
		*sf8_p1 = (sf8) (*si8_p2++ - *si8_p1++); // dx
		*sf8_p2++ = (*sf8_p4++ - *sf8_p3++) / *sf8_p1++;  // delta = dy / dx
	}

	if (in_len > 2) {
		delta_0 = ((sf8) 2.0 * delta[0]) - delta[1];
		delta_m1 = ((sf8) 2.0 * delta_0) - delta[0];
		delta_n = ((sf8) 2.0 * delta[in_len - 2]) - delta[in_len - 3];
		delta_n1 = ((sf8) 2.0 * delta_n) - delta[in_len - 2];

		tmp_delta[0] = delta_m1;
		tmp_delta[1] = delta_0;
		tmp_delta[tmp_delta_len - 2] = delta_n;
		tmp_delta[tmp_delta_len - 1] = delta_n1;

		sf8_p1 = tmp_delta;
		sf8_p2 = tmp_delta + 1;
		sf8_p3 = weights;
		for (i = tmp_delta_len - 1; i--;) {
			sf8_v1 = *sf8_p1++;
			sf8_v2 = *sf8_p2++;
			sf8_v3 = (sf8_v1 + sf8_v2) / (sf8) 2.0;
			sf8_v3 = (sf8_v3 >= (sf8) 0.0) ? sf8_v3 : -sf8_v3;
			sf8_v4 = (sf8_v2 - sf8_v1);
			sf8_v4 = (sf8_v4 >= (sf8) 0.0) ? sf8_v4 : -sf8_v4;
			*sf8_p3++ = sf8_v3 + sf8_v4;
		}
		sf8_p1 = weights;
		sf8_p2 = weights + 2;
		sf8_p3 = tmp_delta + 1;
		sf8_p4 = tmp_delta + 2;
		sf8_p5 = slopes;
		for (i = in_len; i--;) {
			sf8_v1 = *sf8_p1 + *sf8_p2;
			if (sf8_v1 != 0.0)
				*sf8_p5++ = ((*sf8_p2++ * *sf8_p3++) + (*sf8_p1++ * *sf8_p4++)) / sf8_v1;
		}
		filled_slopes = (si8) (sf8_p5 - slopes);
	} else {
		slopes[0] = slopes[1] = delta[0];
		filled_slopes = (si8) 2;
	}
	// unfilled slopes need to be zeroed
	sf8_p1 = slopes + filled_slopes;
	for (i = in_len - filled_slopes; i--;)
		*sf8_p1++ = (sf8)  0.0;

	coefs[2] = slopes;
	coefs[3] = in_y;
	sf8_p1 = dx;
	sf8_p2 = slopes;
	sf8_p3 = slopes + 1;
	sf8_p4 = delta;
	sf8_p5 = coefs[0];
	sf8_p6 = coefs[1];
	for (i = in_nm1; i--;) {
		*sf8_p5++ = ((*sf8_p2 + *sf8_p3) - (*sf8_p4 * (sf8) 2.0)) / (*sf8_p1 * *sf8_p1);  // column 0
		*sf8_p6++ = ((*sf8_p4++ * (sf8) 3.0) - (*sf8_p2++ * (sf8) 2.0) - *sf8_p3++) / *sf8_p1++;  // column 1
	}

	for (i = 0, j = 0; i < out_len; ++i) {
		sf8_v1 = out_x[i];
		while (((sf8) in_x[j]) <= sf8_v1) {
			++j;
			if (j == in_nm1)
				break;
		}
		index[i] = j - 1;
		if (j == in_nm1) {
			for (++i, --j; i < out_len; ++i)
				index[i] = j;
			break;
		}
	}

	memcpy(tmp_out_x, out_x, (size_t) (out_len << 3));  // don't destroy out_x (for repeat calls)
	sf8_p1 = tmp_out_x;
	si8_p1 = index;
	for (i = out_len; i--;)
		*sf8_p1++ -= in_x[*si8_p1++];
	sf8_p1 = out_y;
	sf8_p2 = coefs[0];
	si8_p1 = index;
	for (i = out_len; i--;)
		*sf8_p1++ = sf8_p2[*si8_p1++];

	for (i = 1; i < 4; ++i) {
		sf8_p1 = out_y;
		sf8_p2 = tmp_out_x;
		sf8_p3 = coefs[i];
		si8_p1 = index;
		for (j = out_len; j--; ++sf8_p1)
			*sf8_p1 = ((sf8) *sf8_p2++ * *sf8_p1) + sf8_p3[*si8_p1++];
	}

	return_m13(out_y);
}


si8	CMP_max_compressed_bytes_m13(CPS_m13 *cps, si8 block_samps, si8 n_blocks)
{
	ui1	n_derivs;
	ui4	flags, bit, n_params;
	si4	i;
	si8	var_bytes, red_model, pred_model, mbe_total, coded_body, block_bytes;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// Worst-case bytes one block of block_samps samples can occupy in the compressed buffer, for THIS cps's
	// algorithm & directives. Replaces CMP_MAX_COMPRESSED_BYTES_m13(), which could see neither the variable
	// region nor the algorithm nor the fall-through directive, and so under-bounded every one of them.

	// VARIABLE REGION. CMP_set_variable_region_m13() computes this per block, but the buffer must be sized
	// before any block exists, so derive it from params + directives: the library parameter bits it will set
	// (detrend => intercept + gradient; amplitude/frequency scale; noise scores) plus the user's own bits,
	// 4 bytes per bit, plus the record / protected / discretionary reservations.
	flags = cps->params.user_parameter_flags;
	if (cps->direcs.flags & CPS_DF_DETREND_DATA_m13)
		flags |= (CMP_PF_INTERCEPT_m13 | CMP_PF_GRADIENT_m13);
	if (cps->direcs.flags & CPS_DF_ALL_NOISE_SCORES_m13)  // any score requested => the block carries the parameter
		flags |= CMP_PF_NOISE_SCORES_m13;
	for (bit = 1, n_params = i = 0; i < CMP_PF_PARAMETER_FLAG_BITS_m13; ++i, bit <<= 1)
		if (flags & bit)
			++n_params;
	var_bytes = (si8) (n_params << 2) + (si8) cps->params.user_record_region_bytes +
		    (si8) cps->params.protected_region_bytes + (si8) cps->params.user_discretionary_region_bytes;

	// MODEL REGIONS. Statistics are at most CMP_RED_MAX_STATS_BINS_m13 entries of (ui2 count + ui1 symbol);
	// PRED carries CMP_PRED_CATS_m13 of them. Each derivative level costs one raw si4 anchor - bounded by
	// CMP_MAX_DERIVATIVE_LEVEL_m13 for the FIND search, but a SET caller may promise more, so charge the greater.
	n_derivs = CMP_MAX_DERIVATIVE_LEVEL_m13;
	if ((cps->direcs.flags & CPS_DF_SET_DERIVATIVE_LEVEL_m13) && cps->params.goal_derivative_level > n_derivs)
		n_derivs = cps->params.goal_derivative_level;
	red_model = (si8) CMP_RED_MODEL_FIXED_HDR_BYTES_m13 + (si8) (n_derivs << 2) + (CMP_RED_MAX_STATS_BINS_m13 * 3);
	pred_model = (si8) CMP_PRED_MODEL_FIXED_HDR_BYTES_m13 + (si8) (n_derivs << 2) +
		     (CMP_PRED_CATS_m13 * CMP_RED_MAX_STATS_BINS_m13 * 3);

	// BODIES. MBE is exact at its ceiling of 32 bits/sample. The entropy-coded body is bounded by the keysample
	// stream (CMP_MAX_KEYSAMPLE_BYTES_m13: the coder's model is the block's own histogram, so it cannot need more
	// than a byte per keysample byte at the ideal) times CMP_RED_CODER_WORST_CASE_MULT_m13 for the coder's
	// pathological overhead - see that macro.
	mbe_total = (si8) CMP_MBE_MODEL_FIXED_HDR_BYTES_m13 + (block_samps << 2);
	coded_body = (si8) (CMP_MAX_KEYSAMPLE_BYTES_m13(block_samps) * CMP_RED_CODER_WORST_CASE_MULT_m13);

	switch (cps->direcs.flags & CPS_DF_ALGORITHM_MASK_m13) {
		case CPS_DF_MBE_ALGORITHM_m13:
			block_bytes = mbe_total;
			break;
		case CPS_DF_RED1_ALGORITHM_m13:
		case CPS_DF_RED2_ALGORITHM_m13:
		case CPS_DF_PRED1_ALGORITHM_m13:
		case CPS_DF_PRED2_ALGORITHM_m13:
			// With FALL_THROUGH set (the default) the encoder compares its ESTIMATED total against MBE's exact
			// total, biased by CMP_MBE_BIAS_m13, so a stream that runs at all is smaller than the MBE block -
			// the MBE total bounds both outcomes. With it clear there is no diversion at all: the caller asked
			// for pure RED/PRED, which must be sized for the coder's worst case.
			if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13) {
				block_bytes = mbe_total + CMP_ESTIMATE_CUSHION_BYTES_m13;
			} else {
				block_bytes = coded_body;
				block_bytes += ((cps->direcs.flags & (CPS_DF_PRED1_ALGORITHM_m13 | CPS_DF_PRED2_ALGORITHM_m13)) ?
						pred_model : red_model);
				if (block_bytes < mbe_total)  // the buffer-overflow guard still emits MBE
					block_bytes = mbe_total;
			}
			break;
		case CPS_DF_SRRED_ALGORITHM_m13:
			// TWO sub-blocks (scaled + residual) packed into one block, each an independent RED stream that may
			// itself fall through to MBE. Until SRRED gains its own whole-block estimate-vs-MBE redirect, both
			// can go MBE, which is how an SRRED block reaches ~2x a plain one (measured 31,832 B where plain MBE
			// was 15,936).
			block_bytes = (si8) CMP_SRRED_MODEL_FIXED_HDR_BYTES_m13;
			if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13)
				block_bytes += (mbe_total + CMP_ESTIMATE_CUSHION_BYTES_m13) << 1;  // each sub-encode decides separately
			else
				block_bytes += (coded_body + red_model) << 1;
			break;
		case CPS_DF_VDS_ALGORITHM_m13:
			// amplitude (PRED) + time (RED) sub-blocks over at most block_samps anchors, or a whole-block
			// redirect to PRED2 over the real sample stream - the two-sub-block form bounds both.
			block_bytes = (si8) CMP_VDS_MODEL_FIXED_HDR_BYTES_m13;
			if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13)
				block_bytes += (mbe_total + CMP_ESTIMATE_CUSHION_BYTES_m13) << 1;  // each sub-encode decides separately
			else
				block_bytes += (coded_body << 1) + pred_model + red_model;
			break;
		default:  // unknown/unset algorithm: charge the largest of the above
			block_bytes = (si8) CMP_VDS_MODEL_FIXED_HDR_BYTES_m13 + ((coded_body + pred_model) << 1);
			break;
	}

	block_bytes += (si8) CMP_BLOCK_FIXED_HDR_BYTES_m13 + var_bytes + 7;  // + G_pad_m13() to 8

	return_m13(block_bytes * n_blocks);
}


tern	CMP_MBE_decode_m13(CPS_m13 *cps)
{
	ui4				n_samps, total_header_bytes;
	si4				*si4_p, *init_val_p, bits_per_samp, n_derivs;
	si8				i, lmin;
	ui8				out_val, *in_word, mask, temp_mask, high_bits, in_word_val;
	ui1				in_bit;
	CMP_FIXED_BH_m13		*bh;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// read header
	bh = cps->block_header;
	n_samps = bh->number_of_samples;
	MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	lmin = (si8) MBE_header->minimum_value;
	bits_per_samp = (si4) MBE_header->bits_per_sample;
	n_derivs = (si4) MBE_header->derivative_level;
	
	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_MBE_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		cps->decompressed_ptr[i] = *init_val_p++;
	
	// set parameters for return
	cps->params.derivative_level = n_derivs;

	// MBE decode
	// Note: can't use bh->total_header_bytes in case input is VDS fall through
	total_header_bytes = (ui4) ((cps->params.model_region - (ui1 *) bh) + CMP_MBE_MODEL_FIXED_HDR_BYTES_m13 + (n_derivs * 4));
	in_word = (ui8 *) ((ui1 *) bh + (total_header_bytes & ~((ui4) 7)));
	in_bit = (total_header_bytes & (ui4) 7) << 3;
	mask = ((ui8) 1 << bits_per_samp) - 1;
	si4_p = cps->decompressed_ptr + n_derivs;
	in_word_val = *in_word >> in_bit;
	for (i = n_samps - n_derivs; i--;) {
		out_val = in_word_val & mask;
		in_word_val >>= bits_per_samp;
		if ((in_bit += bits_per_samp) > 63) {
			in_word_val = *++in_word;
			if (in_bit &= 63) {
				temp_mask = ((ui8) 1 << in_bit) - 1;
				high_bits = in_word_val & temp_mask;
				out_val |= (high_bits << (bits_per_samp - in_bit));
				in_word_val >>= in_bit;
			}
		}
		*si4_p++ = (si4) ((si8) out_val + lmin);
	}
	
	// integrate derivatives
	if ((cps->block_header->block_flags & CMP_BF_SRRED_ENCODING_m13) == 0)  // skip only for SRRED sub-streams (SRRED_decode_m13() integrates once after adding residuals); a standalone RED/PRED/MBE block - including one SRRED redirected to - is flagged as itself & must integrate, even when decoded by an SRRED-configured CPS
		CMP_integrate_m13(cps);

	return_m13(TRUE_m13);
}


tern	CMP_MBE_encode_m13(CPS_m13 *cps)
{
	ui1				n_derivs;
	si4				*init_out_vals, *si4_p, bits_per_samp;
	ui4				n_samps, n_deriv_samps, cmp_data_bytes;
	si8				i, cmp_data_bits, lmin, lmax;
	ui8				out_val, *out_word;
	ui1				out_bit, *output;
	CMP_FIXED_BH_m13		*bh;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// compress from input buffer to block header
	// (compression algorithms are responsible for filling in: algorithm block flag, total_block_bytes, total_header_bytes, model_region_bytes, & model details)
	
	// set algorithm block flag
	bh = cps->block_header;
	bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
	bh->block_flags |= CMP_BF_MBE_ENCODING_m13;

	MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	// The RED/PRED fallback pre-fills lmin / derivative_level / bits_per_sample here ON PURPOSE - those encoders
	// already computed them for the RED-vs-MBE decision, so recomputing would be wasted work (Matt, 2026-08-02).
	// What may NOT come from the block buffer is the SIGNAL that they were pre-filled: the buffer is realloc'd &
	// never zeroed, so a flag bit read out of it is a pre-existing value (the previous block's compressed bytes)
	// that this encoder never wrote. A stale bit took the "already preprocessed" branch with garbage parameters.
	// The signal therefore lives in the CPS; the flags field is initialized here for the same reason.
	if (cps->params.MBE_preprocessed == TRUE_m13) {
		cps->params.MBE_preprocessed = FALSE_m13;  // consume the handoff
		lmin = MBE_header->minimum_value;
		n_derivs = MBE_header->derivative_level;
		bits_per_samp = MBE_header->bits_per_sample;
		MBE_header->flags = 0;
	} else {
		MBE_header->flags = 0;
		// calculate derivatives
		if (cps->direcs.flags & CPS_DF_SRRED_ALGORITHM_m13)  // derivatives already in derivative buffer
			n_derivs = cps->params.derivative_level;
		else
			n_derivs = CMP_differentiate_m13(cps);  // CMP_differentiate_m13() sets parameter mins & maxs
		MBE_header->derivative_level = n_derivs;
		if (n_derivs == 0xFF)  // no entry
			return_m13(FALSE_m13);
		if (n_derivs == 0) {
			lmin = (si8) cps->params.minimum_sample_value;
			lmax = (si8) cps->params.maximum_sample_value;
		} else {
			cps->input_buffer = cps->params.derivative_buffer;
			lmin = (si8) cps->params.minimum_difference_value;
			lmax = (si8) cps->params.maximum_difference_value;
		}
		for (bits_per_samp = 0, i = lmax - lmin; i; i >>= 1)
			++bits_per_samp;
		MBE_header->minimum_value = (si4) lmin;
		MBE_header->bits_per_sample = bits_per_samp;
	}
	
	// copy initial derivative values
	n_samps = bh->number_of_samples;
	if (n_derivs) {
		init_out_vals = (si4 *) (cps->params.model_region + CMP_MBE_MODEL_FIXED_HDR_BYTES_m13);
		for (i = 0; i < n_derivs; ++i)
			init_out_vals[i] = cps->input_buffer[i];
	}
	n_deriv_samps = n_samps - n_derivs;
	
	// calculate header bytes
	bh->model_region_bytes = CMP_MBE_MODEL_FIXED_HDR_BYTES_m13 + (n_derivs * 4);
	bh->total_header_bytes = (cps->params.model_region - (ui1 *) bh) + bh->model_region_bytes;
	output = (ui1 *) bh + bh->total_header_bytes;
	
	// calculate total encoding bytes
	cmp_data_bits = (si8) n_deriv_samps * (si8) bits_per_samp;
	cmp_data_bytes = cmp_data_bits >> 3;
	if (cmp_data_bits & 7)
		++cmp_data_bytes;
	
	// MBE encode
	memset(output, 0, cmp_data_bytes);
	out_word = (ui8 *) bh + (bh->total_header_bytes >> 3);
	out_bit = (bh->total_header_bytes & 7) << 3;
	si4_p = cps->input_buffer + n_derivs;
	out_val = 0;
	for (i = n_deriv_samps; i--;) {
		out_val = (ui8) ((si8) *si4_p++ - lmin);
		*out_word |= (out_val << out_bit);
		if ((out_bit += bits_per_samp) > 63) {
			out_bit &= 63;
			*++out_word = (out_val >> (bits_per_samp - out_bit));
		}
	}
	
	// fill in block header
	bh->total_block_bytes = G_pad_m13((ui1 *) bh, (si8) (cmp_data_bytes + bh->total_header_bytes), 8);
	
	return_m13(TRUE_m13);
}


si8	CMP_MBE_estimate_bytes_m13(CPS_m13 *cps, tern *use_raw, si4 *bits_per_sample)
{
	// Total MBE block size in bytes (8-byte padded). MBE stores each value in a fixed bit width set by the data range
	// (max - min), so unlike the RED/PRED estimators this is EXACT, not an estimate - the size is fully determined by
	// the range & sample count (no scaling - that is an SRRED concern). Picks raw samples vs derivatives by whichever
	// needs fewer bits/sample (raw can win in very noisy data, where differentiating widens the range). Outputs
	// *use_raw & *bits_per_sample for the caller to fill the MBE header & pick the input buffer; does NOT mutate cps.
	// Everything else is derived from the CPS (assumes extrema known & derivative level set - true at every call site):
	// n_samps = block number_of_samples, derivative level = params.derivative_level, header_bytes = model_region - bh.
	tern	sub_stream;
	si4	raw_bps, bps, n_derivs;
	si8	i, data_bits, bytes, header_bytes;
	ui4	rem, n_samps;

	n_samps = cps->block_header->number_of_samples;
	n_derivs = (si4) cps->params.derivative_level;
	header_bytes = (si8) (cps->params.model_region - (ui1 *) cps->block_header);

	// RAW MODE IS FORBIDDEN FOR SRRED SUB-STREAMS. The raw emit path keeps input_buffer, which holds the OUTER
	// block's raw samples - an SRRED sub-encode's stream lives in derivative_buffer (scaled derivatives or
	// residuals), so raw mode would encode the wrong data entirely: both sides then agree on bytes that are not
	// the stream, and the block round-trips to garbage SILENTLY (found 2026-08-03 on spiked large-amplitude
	// data: raw_bps beat the stale derivative extrema's bps, MBE encoded the raw samples as the scaled stream).
	// params.SRRED_sub_encode is TRUE only across CMP_SRRED_encode_m13()'s sub-encoder calls, so every
	// WHOLE-BLOCK use - the scale-search MBE seed, the degenerate-scale redirect, & all standalone encoders -
	// keeps raw pricing: truly noisy data where d0's bit range beats d1's still gets its raw MBE block.
	sub_stream = cps->params.SRRED_sub_encode;

	for (raw_bps = 0, i = (si8) cps->params.maximum_sample_value - (si8) cps->params.minimum_sample_value; i; i >>= 1)
		++raw_bps;
	if (n_derivs || sub_stream == TRUE_m13) {
		for (bps = 0, i = (si8) cps->params.maximum_difference_value - (si8) cps->params.minimum_difference_value; i; i >>= 1)
			++bps;
		if (sub_stream == TRUE_m13)
			*use_raw = FALSE_m13;
		else
			*use_raw = (raw_bps > bps) ? FALSE_m13 : TRUE_m13;  // raw can beat derivatives in very noisy data
	} else {
		*use_raw = TRUE_m13;
	}
	if (*use_raw == TRUE_m13) {
		bps = raw_bps;
		n_derivs = 0;  // raw => derivative_level 0, no initial derivative values stored
	}
	*bits_per_sample = bps;
	data_bits = (si8) (*use_raw == TRUE_m13 ? n_samps : (n_samps - (ui4) n_derivs)) * (si8) bps;
	bytes = (data_bits + 7) >> 3;
	bytes += header_bytes + (si8) CMP_MBE_MODEL_FIXED_HDR_BYTES_m13 + ((si8) n_derivs << 2);  // + common header + MBE model header + initial derivative values
	if ((rem = (ui4) (bytes & 7)))  // pad to 8 bytes
		bytes += 8 - rem;
	return(bytes);
}


// Bytes RED emits per overflow value, from the stream's extrema. Pure: no CPS or header is touched, so the
// estimators can call it on hypothetical extrema (SRRED needs it on the SCALED stream, i.e. extrema x scale)
// without the header-stamping side effect CMP_get_overflow_bytes_m13() performs for the encoder.
// pos_derivs: the caller's non-overflow range is 1..255 rather than -127..127, so no sign bit is needed.
// Clamp: a stream with NO overflow can compute 1 here (its byte loop never runs, so the value is unused), but
// 2 is the true floor once any value actually overflows - |val| >= 128 => >= 9 bits. Clamping makes that
// explicit & keeps a 1 from ever reaching the header stamp, which only encodes 2 & 3 (anything else reads 4).
static ui1	CMP_overflow_bytes_for_extrema_m13(si8 min_val, si8 max_val, tern pos_derivs)
{
	ui1	bits_per_samp;
	si8	i, val, abs_min, abs_max;

	abs_min = ABS_m13(min_val);  // cannot make 0x80000000 positive as si4, so these are si8
	abs_max = ABS_m13(max_val);
	val = (abs_min > abs_max) ? abs_min : abs_max;
	for (bits_per_samp = 1, i = val; i; i >>= 1)
		++bits_per_samp;
	if (pos_derivs == TRUE_m13)
		--bits_per_samp;  // don't need a sign bit
	bits_per_samp = (bits_per_samp + 7) >> 3;
	if (bits_per_samp < 2)
		bits_per_samp = 2;
	else if (bits_per_samp > CPS_PARAMS_OVERFLOW_BYTES_DEFAULT_m13)  // 4
		bits_per_samp = CPS_PARAMS_OVERFLOW_BYTES_DEFAULT_m13;

	return(bits_per_samp);
}


sf8	CMP_p2z_m13(sf8 p)
{
	const sf8	P_EPS = (sf8) 5.0e-7;
	sf8 		z, low_z, high_z, temp_z, low_p, high_p, temp_p;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// forward search
	low_z = (sf8) 0.0;
	high_p = CMP_z2p_m13(low_z);
	high_z = (sf8) 2.0;
	low_p = CMP_z2p_m13(high_z);
	while (low_p > p) {
		low_z = high_z;
		high_p = low_p;
		high_z *= (sf8) 2.0;
		low_p = CMP_z2p_m13(high_z);
	}
	
	// binary search
	while ((high_p - low_p) > P_EPS) {
		temp_z = (low_z + high_z) / (sf8) 2.0;
		temp_p = CMP_z2p_m13(temp_z);
		if (temp_p >= p) {
			high_p = temp_p;
			low_z = temp_z;
		} else {
			low_p = temp_p;
			high_z = temp_z;
		}
	}
	z = (low_z + high_z) / (sf8) 2.0;
	
	return_m13(z);
}


tern	CMP_PRED1_decode_m13(CPS_m13 *cps)
{
	tern				no_zero_counts;
	ui1				*comp_p, *ui1_p, *low_bound_high_byte_p, *high_bound_high_byte_p;
	ui1				*goal_bound_high_byte_p, prev_cat, overflow_bytes;
	ui1				*symbol_map[CMP_PRED_CATS_m13], *symbols;
	si1				*si1_p1, *si1_p2, *key_p;
	ui2				*bin_counts, *stats_entries, *count[CMP_PRED_CATS_m13];
	ui4				n_samps, n_derivs, n_keysample_bytes, total_stats_entries, sign_bit, sign_bytes;
	si4				*si4_p, *init_val_p, overflow_val;
	ui8				**minimum_range, **cumulative_count;
	ui8				low_bound, high_bound, prev_high_bound, goal_bound, range;
	si8				i, j;
	CMP_FIXED_BH_m13		*bh;
	CMP_PRED_MODEL_FIXED_HDR_m13	*PRED_header;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP decompress from block header to decompressed_ptr
	
	bh = cps->block_header;
	n_samps = bh->number_of_samples;
	
	// zero samples, or only one value
	if (n_samps <= 1) {
		if (bh->number_of_samples == 1)
			cps->decompressed_ptr[0] = *((si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13));
		cps->params.derivative_level = 0;
		return_m13(TRUE_m13);
	}
	
	PRED_header = (CMP_PRED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_derivs = PRED_header->derivative_level;
	n_keysample_bytes = PRED_header->n_keysample_bytes;
	stats_entries = PRED_header->n_statistics_bins;
	for (total_stats_entries = i = 0; i < CMP_PRED_CATS_m13; ++i)
		total_stats_entries += (ui4) stats_entries[i];
	
	// set parameters for return
	cps->params.derivative_level = n_derivs;
	
	// get block flags
	if (PRED_header->flags & CMP_PRED_FLAGS_NO_ZERO_COUNTS_m13)
		no_zero_counts = TRUE_m13;
	else
		no_zero_counts = FALSE_m13;
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_DECOMPRESSION_MODE_m13, CMP_PRED_COMPRESSION_m13);
	sign_bit = (ui4) 1 << ((overflow_bytes << 3) - 1);
	if (overflow_bytes == 4)
		sign_bytes = (ui4) 0;
	else  // Windows: shift of 32 bits is equated to shift of 0, so have to do this
		sign_bytes = (ui4) 0xFFFFFFFF << (overflow_bytes << 3);

	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		cps->decompressed_ptr[i] = *init_val_p++;

	// build symbol map, count arrays, & minimum ranges
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + total_stats_entries);
	cumulative_count = (ui8 **) cps->params.cumulative_count;
	minimum_range = (ui8 **) cps->params.minimum_range;
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		count[i] = bin_counts; bin_counts += stats_entries[i];
		symbol_map[i] = symbols; symbols += stats_entries[i];
		if (no_zero_counts == TRUE_m13) {  // TO DO: decide mapping scheme for unmapped symbols in symbol map
			// TO DO: copy count & symbol map to arrays with 256 elements
			for (j = stats_entries[i]; i < 256; ++i)
				count[i][j] = 1;
		}
		for (cumulative_count[i][0] = j = 0; j < stats_entries[i]; ++j) {
			cumulative_count[i][j + 1] = cumulative_count[i][j] + (ui8) count[i][j];
			minimum_range[i][j] = CMP_RED_TOTAL_COUNTS_m13 / count[i][j];
			if (CMP_RED_TOTAL_COUNTS_m13 > (count[i][j] * minimum_range[i][j]))
				++minimum_range[i][j];
		}
	}
	
	// range decode
	key_p = cps->params.keysample_buffer;
	prev_high_bound = goal_bound = low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	comp_p = (ui1 *) bh + bh->total_header_bytes;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	goal_bound_high_byte_p = ((ui1 *) &goal_bound) + 5;
	ui1_p = goal_bound_high_byte_p;
	*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
	*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
	prev_cat = CMP_PRED_NIL_m13;
		
	for (i = n_keysample_bytes; i;) {
		for (j = 0; range >= minimum_range[prev_cat][j];) {
			high_bound = low_bound + ((range * cumulative_count[prev_cat][j + 1]) >> 16);
			if (high_bound > goal_bound) {
				*key_p = symbol_map[prev_cat][j];
				if (!--i)
					goto PRED1_RANGE_DECODE_DONE_m13;
				range = high_bound - (low_bound = prev_high_bound);
				prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;
				j = 0;
			} else {
				prev_high_bound = high_bound;
				++j;
			}
		}
		high_bound = low_bound + range;
		if (*low_bound_high_byte_p != *high_bound_high_byte_p) {
			ui1_p = goal_bound_high_byte_p;
			*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
			*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
			low_bound = 0;
			range = CMP_RED_MAXIMUM_RANGE_m13;
		} else {
			do {
				low_bound <<= 8;
				high_bound <<= 8;
				goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				range <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
			goal_bound &= CMP_RED_RANGE_MASK_m13;
		}
		prev_high_bound = low_bound;
	} PRED1_RANGE_DECODE_DONE_m13:

	// generate derivatives from keysample data
	si4_p = cps->decompressed_ptr + n_derivs;
	si1_p1 = (si1 *) cps->params.keysample_buffer;
	for (i = n_samps - n_derivs; i--;) {
		if (*si1_p1 == CMP_SI1_KEYSAMPLE_FLAG_m13) {
			overflow_val = 0;
			++si1_p1;
			si1_p2 = (si1 *) &overflow_val;
			j = overflow_bytes; do {
				*si1_p2++ = *si1_p1++;
			} while (--j);
			if (overflow_val & sign_bit)
				overflow_val |= sign_bytes;
			*si4_p++ = overflow_val;
		} else {
			*si4_p++ = (si4) *si1_p1++;
		}
	}

	// integrate derivatives
	CMP_integrate_m13(cps);

	return_m13(TRUE_m13);
}


tern	CMP_PRED1_encode_m13(CPS_m13 *cps)
{
	tern				no_zero_counts, use_raw;
	ui1				*low_bound_high_byte_p, *high_bound_high_byte_p, *ui1_p, prev_cat, n_derivs;
	ui1				*key_p, *comp_p, *symbols, **symbol_map, overflow_bytes;
	ui2				*bin_counts, *stats_entries;
	ui4				n_samps, n_keysamp_bytes, **count, n_deriv_samps, PRED_total_bytes, total_stats_entries;
	ui4				cat_total_counts[CMP_PRED_CATS_m13], goal_total_counts[CMP_PRED_CATS_m13], bin, fall_through_bytes;
	si4				*deriv_p, *init_val_p, diff, bits_per_samp;
	ui8				**cumulative_count, **minimum_range;
	ui8				range, high_bound, low_bound;
	si8				i, j, k, m, extra_counts, scaled_total_counts;
	CMP_STATISTICS_BIN_m13		**sorted_count, temp_sorted_count;
	CMP_FIXED_BH_m13		*bh;
	CMP_PRED_MODEL_FIXED_HDR_m13	*PRED_header;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP compress from input buffer to block header
	// (compression algorithms are responsible for filling in: algorithm block flag, total_block_bytes, total_header_bytes, model_region_bytes, & model details)

	// set algorithm block flag
	bh = cps->block_header;
	bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
	bh->block_flags |= CMP_BF_PRED1_ENCODING_m13;
	
	PRED_header = (CMP_PRED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_samps = bh->number_of_samples;
	PRED_header->flags = (ui2) 0;
	// pad is WRITTEN TO THE FILE, so it must be deterministic. model_region is a reused CPS buffer &
	// nothing anywhere assigns pad, so it otherwise carries bytes left by whatever block used the buffer
	// before: byte-identical re-encoding is impossible, & arbitrary heap contents land in a WORM archive.
	// (These are also the bytes a per-block derivative offset would live in - see the offset design.)
	memset(PRED_header->pad, 0, sizeof(PRED_header->pad));

	// zero or one or samples
	if (n_samps <= 1) {
		bh->model_region_bytes = (ui2) CMP_PRED_MODEL_FIXED_HDR_BYTES_m13;
		if (bh->number_of_samples == 1) {
			*((si4 *) (cps->params.model_region + bh->model_region_bytes)) = cps->input_buffer[0];  // note: no statistics
			bh->model_region_bytes += sizeof(si4);
		}
		PRED_header->n_keysample_bytes = 0;
		PRED_header->derivative_level = 0;
		PRED_header->n_nil_statistics_bins = PRED_header->n_pos_statistics_bins = PRED_header->n_neg_statistics_bins = 0;
		bh->total_header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh) + bh->model_region_bytes;
		bh->total_block_bytes = G_pad_m13((ui1 *) bh, bh->total_header_bytes, 8);
		return_m13(TRUE_m13);
	}
	
	// calculate derivatives
	n_derivs = CMP_differentiate_m13(cps);

	// set up PRED arrays
	count = (ui4 **) cps->params.count;
	cumulative_count = (ui8 **) cps->params.cumulative_count;
	minimum_range = (ui8 **) cps->params.minimum_range;
	sorted_count = (CMP_STATISTICS_BIN_m13 **) cps->params.sorted_count;
	symbol_map = (ui1 **) cps->params.symbol_map;

	// set model parameters
	PRED_header->derivative_level = n_derivs;
	if (cps->direcs.flags & CMP_PRED_FLAGS_NO_ZERO_COUNTS_m13) {
		no_zero_counts = TRUE_m13;
		PRED_header->flags |= CMP_PRED_FLAGS_NO_ZERO_COUNTS_m13;
	} else {
		no_zero_counts = FALSE_m13;
	}
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_COMPRESSION_MODE_m13, CMP_PRED_COMPRESSION_m13);

	// generate count & build keysample array
	memset(count[0], 0, CMP_RED_MAX_STATS_BINS_m13 * CMP_PRED_CATS_m13 * sizeof(ui4));
	key_p = (ui1 *) cps->params.keysample_buffer;
	deriv_p = cps->params.derivative_buffer + n_derivs;
	prev_cat = CMP_PRED_NIL_m13;
	n_deriv_samps = n_samps - (ui4) n_derivs;
	for (i = n_deriv_samps; i--;) {
		diff = *deriv_p++;
		if (diff < -127 || diff > 127) {
			ui1_p = (ui1 *) &diff;
			++count[prev_cat][*key_p++ = CMP_UI1_KEYSAMPLE_FLAG_m13];
			prev_cat = CMP_PRED_NEG_m13;
			j = overflow_bytes; do {
				++count[prev_cat][*key_p = *ui1_p++];
				prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;  // do not increment within call to CAT
			} while (--j);
		} else {
			++count[prev_cat][*key_p = (ui1) diff];
			prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;  // do not increment within call to CAT
		}
	}
	n_keysamp_bytes = (ui4) (key_p - (ui1 *) cps->params.keysample_buffer);
	
	// build sorted_count: interleave
	stats_entries = PRED_header->n_statistics_bins;
	for (total_stats_entries = i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (j = stats_entries[i] = 0, k = 255, m = 128; m--; ++j, --k) {
			if (count[i][j]) {
				sorted_count[i][stats_entries[i]].count = count[i][j];
				sorted_count[i][stats_entries[i]++].value = (si1) j;
			}
			if (count[i][k]) {
				sorted_count[i][stats_entries[i]].count = count[i][k];
				sorted_count[i][stats_entries[i]++].value = (si1) k;
			}
		}
		total_stats_entries += stats_entries[i];
	}

	// build sorted_count: bubble sort
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		m = stats_entries[i];
		do {
			for (j = 0, k = 1; k < m; ++k) {
				if (sorted_count[i][k - 1].count < sorted_count[i][k].count) {
					temp_sorted_count = sorted_count[i][k - 1];
					sorted_count[i][k - 1] = sorted_count[i][k];
					sorted_count[i][k] = temp_sorted_count;
					j = k;  // highest swap index
				}
			}
		} while ((m = j) > 1);
	}
	
	// get separate count for each category
	for (i = 0; i < CMP_PRED_CATS_m13; ++i)
		for (cat_total_counts[i] = j = 0; j < stats_entries[i]; ++j)
			cat_total_counts[i] += sorted_count[i][j].count;
	
	// scale count so that each category's total_counts equals (RED_TOTAL_COUNTS - 1)
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		goal_total_counts[i] = CMP_RED_TOTAL_COUNTS_m13 - 1;
		if (no_zero_counts == TRUE_m13)
			goal_total_counts[i] -= (256 - stats_entries[i]);  // reserve one count in each model category for all zero count bins
		// TO DO: decide mapping scheme for unmapped symbols in symbol map
	}

	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		if (!stats_entries[i])
			continue;
		for (scaled_total_counts = j = 0; j < stats_entries[i]; ++j) {
			sorted_count[i][j].count = (ui4) (((((ui8) goal_total_counts[i] << 1) * (ui8) sorted_count[i][j].count) + (ui8) cat_total_counts[i]) / ((ui8) cat_total_counts[i] << 1));
			if (sorted_count[i][j].count == 0)
				sorted_count[i][j].count = 1;
			scaled_total_counts += (si8)sorted_count[i][j].count;
		}
		extra_counts = ((si8) goal_total_counts[i] - (si8) scaled_total_counts);
		if (extra_counts > 0) {
			do {
				for (j = 0; (j < stats_entries[i]) && extra_counts; ++j) {
					++sorted_count[i][j].count;
					--extra_counts;
				}
			} while (extra_counts);
		} else if (extra_counts < 0) {
			extra_counts = -extra_counts;
			do {
				for (j = stats_entries[i] - 1; (j >= 0) && extra_counts; --j) {
					if (sorted_count[i][j].count > 1) {
						--sorted_count[i][j].count;
						--extra_counts;
					}
				}
			} while (extra_counts);
		}
	}
	
	// build symbol maps, count arrays & minimum ranges
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (cumulative_count[i][0] = j = 0; j < stats_entries[i]; ++j) {
			symbol_map[i][(ui1) sorted_count[i][j].value] = (ui1) j;
			cumulative_count[i][j + 1] = cumulative_count[i][j] + (ui8) (count[i][j] = sorted_count[i][j].count);
			minimum_range[i][j] = CMP_RED_TOTAL_COUNTS_m13 / count[i][j];
			if (CMP_RED_TOTAL_COUNTS_m13 > (count[i][j] * minimum_range[i][j]))
				++minimum_range[i][j];
		}
	}
	
	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		*init_val_p++ = cps->params.derivative_buffer[i];

	// write scaled counts & symbols into header
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + total_stats_entries);
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (j = 0; j < stats_entries[i]; ++j) {
			*bin_counts++ = (ui2) sorted_count[i][j].count;
			*symbols++ = sorted_count[i][j].value;
		}
	}
	
	// fill header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	bh->model_region_bytes = (ui2) (ui2) (symbols - cps->params.model_region);
	bh->total_header_bytes = (ui4) (symbols - (ui1 *) bh);
	PRED_header->n_keysample_bytes = n_keysamp_bytes;
	
	// range encode
	key_p = (ui1 *) cps->params.keysample_buffer;
	comp_p = (ui1 *) bh + bh->total_header_bytes;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	prev_cat = CMP_PRED_NIL_m13;
	
	for (i = n_keysamp_bytes; i;) {
		for (; range >= minimum_range[prev_cat][bin = symbol_map[prev_cat][*key_p]]; key_p++) {
			high_bound = low_bound + ((range * cumulative_count[prev_cat][bin + 1]) >> 16);
			if (bin)
				low_bound += (range * cumulative_count[prev_cat][bin]) >> 16;
			range = high_bound - low_bound;
			if (!--i)
				break;
			prev_cat = CMP_PRED_CAT_m13(*key_p);
		}
		if ((*low_bound_high_byte_p != *high_bound_high_byte_p) || !i) {
			ui1_p = low_bound_high_byte_p;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			range = CMP_RED_MAXIMUM_RANGE_m13;
			low_bound = 0;
		} else {
			do {
				*comp_p++ = *low_bound_high_byte_p;
				low_bound <<= 8;
				high_bound <<= 8;
				range <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
		}
	}
	
	// finish header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	PRED_total_bytes = (si8) (comp_p - (ui1 *) bh);
	bh->total_block_bytes = (ui4) G_pad_m13((ui1 *) bh, PRED_total_bytes, 8);
	
	// calculate fall through encoding bytes
	if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13) {
		fall_through_bytes = (ui4) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);  // exact MBE size; sets use_raw & bits_per_samp for the emit
		if (fall_through_bytes < bh->total_block_bytes) {
			bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
			bh->block_flags |= CMP_BF_MBE_ENCODING_m13;
			MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
			if (use_raw == TRUE_m13) {
				// cps->input_buffer = unchanged
				MBE_header->minimum_value = cps->params.minimum_sample_value;
				MBE_header->derivative_level = 0;
			} else {
				cps->input_buffer = cps->params.derivative_buffer;
				MBE_header->minimum_value = cps->params.minimum_difference_value;
				MBE_header->derivative_level = n_derivs;
			}
			MBE_header->bits_per_sample = bits_per_samp;
			cps->params.MBE_preprocessed = TRUE_m13;  // handoff via CPS, not the never-zeroed block buffer
			CMP_MBE_encode_m13(cps);
		}
	}

	return_m13(TRUE_m13);
}


tern	CMP_PRED2_decode_m13(CPS_m13 *cps)
{
	tern				no_zero_counts, multiply_method;
	ui1				*comp_p, *ui1_p, prev_cat, overflow_bytes;
	ui1				*low_bound_high_byte_p, *high_bound_high_byte_p, *goal_bound_high_byte_p;
	ui1				*symbol_map[CMP_PRED_CATS_m13], *symbols;
	si1				*si1_p1, *si1_p2, *key_p;
	ui2				*bin_counts, *stats_entries, *count[CMP_PRED_CATS_m13], *tc;
	ui4				n_samps, n_derivs, n_keysample_bytes, total_stats_entries, sign_bit, sign_bytes;
	si4				*si4_p, *init_val_p, overflow_val;
	ui8				**minimum_range, **cumulative_count, *cc;
	ui8				low_bound, high_bound, prev_high_bound, goal_bound, range, target_cc;
	si8				i, j, k, se, n_stored_c, model_bins[CMP_PRED_CATS_m13];
	ui2				*block_count_c, count_exp[CMP_PRED_CATS_m13][256];
	ui1				*block_symbols_c, symbol_map_exp[CMP_PRED_CATS_m13][256], present[256];
	sf8				average_steps, multiply_time;
	CMP_FIXED_BH_m13		*bh;
	CMP_PRED_MODEL_FIXED_HDR_m13	*PRED_header;
	HW_PERFORMANCE_SPECS_m13	*perf_specs;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP decompress from block header to decompressed_ptr
	bh = cps->block_header;
	n_samps = bh->number_of_samples;

	// zero samples, or only one value
	if (n_samps <= 1) {
		if (bh->number_of_samples == 1)
			cps->decompressed_ptr[0] = *((si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13));
		cps->params.derivative_level = 0;
		return_m13(TRUE_m13);
	}
	
	PRED_header = (CMP_PRED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_derivs = PRED_header->derivative_level;
	n_keysample_bytes = PRED_header->n_keysample_bytes;
	stats_entries = PRED_header->n_statistics_bins;
	for (total_stats_entries = i = 0; i < CMP_PRED_CATS_m13; ++i)
		total_stats_entries += (ui4) stats_entries[i];
	
	// set parameters for return
	cps->params.derivative_level = n_derivs;
	
	// get block flags
	if (PRED_header->flags & CMP_PRED_FLAGS_NO_ZERO_COUNTS_m13)
		no_zero_counts = TRUE_m13;
	else
		no_zero_counts = FALSE_m13;
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_DECOMPRESSION_MODE_m13, CMP_PRED_COMPRESSION_m13);
	sign_bit = (ui4) 1 << ((overflow_bytes << 3) - 1);
	if (overflow_bytes == 4)
		sign_bytes = (ui4) 0;
	else  // Windows: shift of 32 bits is equated to shift of 0, so have to do this
		sign_bytes = (ui4) 0xFFFFFFFF << (overflow_bytes << 3);

	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		cps->decompressed_ptr[i] = *init_val_p++;

	// build per-category models: symbol_map[c] (rank -> byte value), counts, cumulative counts, minimum ranges
	// normal: each category's model is exactly its stored bins (stats_entries[c])
	// no_zero_counts: each category stores only nonzero bins; every byte value absent from that category's
	//   stored symbol list is an implicit count-1 bin at ranks stats_entries[c]..255 in ascending byte order.
	//   Encoder & decoder derive this identical assignment from the stored symbol list alone (no zeros stored).
	//   Same scheme as CMP_RED2_decode_m13(), applied independently to each of the CMP_PRED_CATS_m13 contexts.
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + total_stats_entries);
	cumulative_count = (ui8 **) cps->params.cumulative_count;
	minimum_range = (ui8 **) cps->params.minimum_range;
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		n_stored_c = (si8) stats_entries[i];
		block_count_c = bin_counts; bin_counts += n_stored_c;
		block_symbols_c = symbols; symbols += n_stored_c;
		if (no_zero_counts == TRUE_m13) {
			memset(present, 0, sizeof(present));
			for (j = 0; j < n_stored_c; ++j) {
				count_exp[i][j] = block_count_c[j];
				symbol_map_exp[i][j] = block_symbols_c[j];
				present[block_symbols_c[j]] = 1;
			}
			for (k = n_stored_c, j = 0; j < 256; ++j) {  // absent byte values, ascending, count 1
				if (present[j] == 0) {
					count_exp[i][k] = 1;
					symbol_map_exp[i][k++] = (ui1) j;
				}
			}
			count[i] = count_exp[i];
			symbol_map[i] = symbol_map_exp[i];
			model_bins[i] = 256;
		} else {
			count[i] = block_count_c;
			symbol_map[i] = block_symbols_c;
			model_bins[i] = n_stored_c;
		}
		for (cumulative_count[i][0] = j = 0; j < model_bins[i]; ++j) {
			cumulative_count[i][j + 1] = cumulative_count[i][j] + (ui8) count[i][j];
			minimum_range[i][j] = CMP_RED_TOTAL_COUNTS_m13 / count[i][j];
			if (CMP_RED_TOTAL_COUNTS_m13 > (count[i][j] * minimum_range[i][j]))
				++minimum_range[i][j];
		}
	}
	
	// determine decompression method
	perf_specs = &globals_m13->tables->HW_params.performance_specs;  // gathered at G_init_medlib_m13()
	for (average_steps = (sf8) 0.0, i = 0; i < CMP_PRED_CATS_m13; ++i) {
		tc = count[i];
		se = model_bins[i];
		for (j = 0; j < se; ++j)
			average_steps += (sf8) (j * (si8) tc[j]);
	}
	average_steps /= (sf8) (CMP_RED_TOTAL_COUNTS_m13 * CMP_PRED_CATS_m13);
	multiply_time = average_steps * perf_specs->nsecs_per_integer_multiplication;
	if (multiply_time < perf_specs->nsecs_per_integer_division)
		multiply_method = TRUE_m13;
	else
		multiply_method = FALSE_m13;

	// range decode
	key_p = cps->params.keysample_buffer;
	prev_high_bound = goal_bound = low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	comp_p = (ui1 *) bh + bh->total_header_bytes;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	goal_bound_high_byte_p = ((ui1 *) &goal_bound) + 5;
	ui1_p = goal_bound_high_byte_p;
	*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
	*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
	prev_cat = CMP_PRED_NIL_m13;
	
	if (multiply_method == TRUE_m13) {
		for (j = 0, i = n_keysample_bytes; i;) {
			while (range >= minimum_range[prev_cat][j]) {
				high_bound = low_bound + ((range * cumulative_count[prev_cat][j + 1]) >> 16);
				if (high_bound > goal_bound) {
					*key_p = symbol_map[prev_cat][j];
					if (!--i)
						goto PRED2_RANGE_DECODE_DONE_m13;
					range = high_bound - (low_bound = prev_high_bound);
					prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;
					j = 0;
				} else {
					prev_high_bound = high_bound;
					++j;
				}
			}
			high_bound = low_bound + range;
			if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p) {
				ui1_p = goal_bound_high_byte_p;
				*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
				*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
				low_bound = 0;
				range = CMP_RED_MAXIMUM_RANGE_m13;
			} else {
				do {
					low_bound <<= 8;
					high_bound <<= 8;
					goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
				low_bound &= CMP_RED_RANGE_MASK_m13;
				high_bound &= CMP_RED_RANGE_MASK_m13;
				goal_bound &= CMP_RED_RANGE_MASK_m13;
				range = high_bound - low_bound;
			}
			prev_high_bound = low_bound;
			if (j)
				prev_high_bound += (range * cumulative_count[prev_cat][j]) >> 16;
		}
	} else {  // division method
		for (j = 0, i = n_keysample_bytes; i;) {
			while (range >= minimum_range[prev_cat][j]) {
				high_bound = low_bound + ((range * cumulative_count[prev_cat][j + 1]) >> 16);
				if (high_bound > goal_bound) {
					*key_p = symbol_map[prev_cat][j];
					if (!--i)
						goto PRED2_RANGE_DECODE_DONE_m13;
					range = high_bound - (low_bound = prev_high_bound);
					prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;
					target_cc =  ((goal_bound - low_bound) << 16) / range;
					cc = cumulative_count[prev_cat];
					for (j = 1; j < model_bins[prev_cat]; ++j)
						if (target_cc <= cc[j])
							break;
					if (--j)
						prev_high_bound += (range * cumulative_count[prev_cat][j]) >> 16;
				} else {
					prev_high_bound = high_bound;
					++j;
				}
			}
			high_bound = low_bound + range;
			if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p) {
				ui1_p = goal_bound_high_byte_p;
				*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
				*ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++; *ui1_p-- = *comp_p++;
				low_bound = 0;
				range = CMP_RED_MAXIMUM_RANGE_m13;
			} else {
				do {
					low_bound <<= 8;
					high_bound <<= 8;
					goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
				low_bound &= CMP_RED_RANGE_MASK_m13;
				high_bound &= CMP_RED_RANGE_MASK_m13;
				goal_bound &= CMP_RED_RANGE_MASK_m13;
				range = high_bound - low_bound;
			}
			prev_high_bound = low_bound;
			target_cc =  ((goal_bound - low_bound) << 16) / range;
			cc = cumulative_count[prev_cat];
			for (j = 1; j < model_bins[prev_cat]; ++j)
				if (target_cc <= cc[j])
					break;
			if (--j)
				prev_high_bound += (range * cumulative_count[prev_cat][j]) >> 16;
		}
	}
	PRED2_RANGE_DECODE_DONE_m13:

	// generate derivatives from keysample data
	si4_p = cps->decompressed_ptr + n_derivs;
	si1_p1 = (si1 *) cps->params.keysample_buffer;
	for (i = n_samps - n_derivs; i--;) {
		if (*si1_p1 == CMP_SI1_KEYSAMPLE_FLAG_m13) {
			overflow_val = 0;
			++si1_p1;
			si1_p2 = (si1 *) &overflow_val;
			j = overflow_bytes; do {
				*si1_p2++ = *si1_p1++;
			} while (--j);
			if (overflow_val & sign_bit)
				overflow_val |= sign_bytes;
			*si4_p++ = overflow_val;
		} else {
			*si4_p++ = (si4) *si1_p1++;
		}
	}

	// integrate derivatives
	if ((cps->block_header->block_flags & CMP_BF_SRRED_ENCODING_m13) == 0)  // skip only for SRRED sub-streams (SRRED_decode_m13() integrates once after adding residuals); a standalone RED/PRED/MBE block - including one SRRED redirected to - is flagged as itself & must integrate, even when decoded by an SRRED-configured CPS
		CMP_integrate_m13(cps);

	return_m13(TRUE_m13);
}


tern	CMP_PRED2_encode_m13(CPS_m13 *cps)
{
	tern				no_zero_counts, use_raw, force_mbe;
	ui1				*low_bound_high_byte_p, *high_bound_high_byte_p, *ui1_p, prev_cat, n_derivs;
	ui1				*key_p, *comp_p, *symbols, **symbol_map, overflow_bytes, present_enc[256];
	ui2				*bin_counts, *stats_entries;
	ui4				n_samps, n_keysamp_bytes, **count, n_deriv_samps, PRED_total_bytes, total_stats_entries, header_bytes;
	ui4				cat_total_counts[CMP_PRED_CATS_m13], goal_total_counts[CMP_PRED_CATS_m13], bin, fall_through_bytes;
	si4				*deriv_p, *init_val_p, diff, bits_per_samp;
	ui8				**cumulative_count, **minimum_range;
	ui8				range, high_bound, low_bound;
	si8				i, j, k, m, extra_counts, scaled_total_counts;
	CMP_STATISTICS_BIN_m13		**sorted_count, temp_sorted_count;
	CMP_FIXED_BH_m13		*bh;
	CMP_PRED_MODEL_FIXED_HDR_m13	*PRED_header;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP compress from input buffer to block header
	// (compression algorithms are responsible for filling in: algorithm block flag, total_block_bytes, total_header_bytes, model_region_bytes, & model details)

	// set algorithm block flag
	bh = cps->block_header;
	bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
	bh->block_flags |= CMP_BF_PRED2_ENCODING_m13;
	
	PRED_header = (CMP_PRED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_samps = bh->number_of_samples;
	PRED_header->flags = (ui2) 0;
	// pad is WRITTEN TO THE FILE, so it must be deterministic. model_region is a reused CPS buffer &
	// nothing anywhere assigns pad, so it otherwise carries bytes left by whatever block used the buffer
	// before: byte-identical re-encoding is impossible, & arbitrary heap contents land in a WORM archive.
	// (These are also the bytes a per-block derivative offset would live in - see the offset design.)
	memset(PRED_header->pad, 0, sizeof(PRED_header->pad));

	// zero or one or samples
	if (n_samps <= 1) {
		bh->model_region_bytes = (ui2) CMP_PRED_MODEL_FIXED_HDR_BYTES_m13;
		if (bh->number_of_samples == 1) {
			*((si4 *) (cps->params.model_region + bh->model_region_bytes)) = cps->input_buffer[0];  // note: no statistics
			bh->model_region_bytes += sizeof(si4);
		}
		PRED_header->n_keysample_bytes = 0;
		PRED_header->derivative_level = 0;
		PRED_header->n_nil_statistics_bins = PRED_header->n_pos_statistics_bins = PRED_header->n_neg_statistics_bins = 0;
		bh->total_header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh) + bh->model_region_bytes;
		bh->total_block_bytes = G_pad_m13((ui1 *) bh, bh->total_header_bytes, 8);
		return_m13(TRUE_m13);
	}
	
	// calculate derivatives
	if (cps->direcs.flags & CPS_DF_SRRED_ALGORITHM_m13)  // derivatives already in derivative buffer
		n_derivs = cps->params.derivative_level;
	else
		n_derivs = CMP_differentiate_m13(cps);

	// set up PRED arrays
	count = (ui4 **) cps->params.count;
	cumulative_count = (ui8 **) cps->params.cumulative_count;
	minimum_range = (ui8 **) cps->params.minimum_range;
	sorted_count = (CMP_STATISTICS_BIN_m13 **) cps->params.sorted_count;
	symbol_map = (ui1 **) cps->params.symbol_map;

	// set model parameters
	PRED_header->derivative_level = n_derivs;
	no_zero_counts = FALSE_m13;
	if (cps->direcs.flags & CPS_DF_NO_ZERO_COUNTS_m13) {
		no_zero_counts = TRUE_m13;
		PRED_header->flags |= CMP_PRED_FLAGS_NO_ZERO_COUNTS_m13;
	}
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_COMPRESSION_MODE_m13, CMP_PRED_COMPRESSION_m13);

	// generate count & build keysample array
	memset(count[0], 0, CMP_RED_MAX_STATS_BINS_m13 * CMP_PRED_CATS_m13 * sizeof(ui4));
	key_p = (ui1 *) cps->params.keysample_buffer;
	deriv_p = cps->params.derivative_buffer + n_derivs;
	prev_cat = CMP_PRED_NIL_m13;
	n_deriv_samps = n_samps - (ui4) n_derivs;
	for (i = n_deriv_samps; i--;) {
		diff = *deriv_p++;
		if (diff < -127 || diff > 127) {
			ui1_p = (ui1 *) &diff;
			++count[prev_cat][*key_p++ = CMP_UI1_KEYSAMPLE_FLAG_m13];
			prev_cat = CMP_PRED_NEG_m13;
			j = overflow_bytes; do {
				++count[prev_cat][*key_p = *ui1_p++];
				prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;  // do not increment within call to CAT
			} while (--j);
		} else {
			++count[prev_cat][*key_p = (ui1) diff];
			prev_cat = CMP_PRED_CAT_m13(*key_p); ++key_p;  // do not increment within call to CAT
		}
	}
	n_keysamp_bytes = (ui4) (key_p - (ui1 *) cps->params.keysample_buffer);

	// early PRED-vs-MBE decision, before the range coder: estimate the PRED stream as the SUM over the 3 category
	// models (each ~ entropy + 3 model bytes/nonzero symbol) & compare to MBE. Per-category is essential - a single
	// aggregate histogram would ignore PRED's context gains (underestimating its data) while missing its per-model
	// overhead (3 separate stats tables). Summing the models captures both, so the estimate is honest & correctly
	// penalizes PRED on blocks too small/simple to amortize 3 models. If MBE is smaller, skip the range coder & emit
	// MBE. Both outcomes are lossless; the estimate only risks a hair of size near the crossover. (MBE size mirrors the
	// PRED2_MBE_FALLBACK_m13 computation below, in locals so no encode state is mutated; force_mbe forces MBE emit.)
	// Gated on CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13 (default TRUE, so the default path is unchanged): with the
	// directive clear the caller is asking for pure PRED (the way to force this encoder for testing), so the estimate
	// is skipped entirely rather than silently diverting - which also makes the clear case faster.
	if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13) {
		sf8	est_pred_total, mbe_total;

		header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh);
		est_pred_total = (sf8) (header_bytes + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13 + (n_derivs << 2))  // common + PRED model header + initial derivative values
			+ CMP_PRED_estimate_bytes_m13(count);  // + sum of the 3 per-category RED estimates
		mbe_total = (sf8) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);
		est_pred_total *= CMP_MBE_BIAS_m13;  // favour MBE near the crossover - see the macro
		if (mbe_total < est_pred_total) {
			force_mbe = TRUE_m13;
			goto PRED2_MBE_FALLBACK_m13;
		}
	}
	
	// build sorted_count: interleave
	stats_entries = PRED_header->n_statistics_bins;
	for (total_stats_entries = i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (j = stats_entries[i] = 0, k = 255, m = 128; m--; ++j, --k) {
			if (count[i][j]) {
				sorted_count[i][stats_entries[i]].count = count[i][j];
				sorted_count[i][stats_entries[i]++].value = (si1) j;
			}
			if (count[i][k]) {
				sorted_count[i][stats_entries[i]].count = count[i][k];
				sorted_count[i][stats_entries[i]++].value = (si1) k;
			}
		}
		total_stats_entries += stats_entries[i];
	}

	// build sorted_count: bubble sort
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		m = stats_entries[i];
		do {
			for (j = 0, k = 1; k < m; ++k) {
				if (sorted_count[i][k - 1].count < sorted_count[i][k].count) {
					temp_sorted_count = sorted_count[i][k - 1];
					sorted_count[i][k - 1] = sorted_count[i][k];
					sorted_count[i][k] = temp_sorted_count;
					j = k;  // highest swap index
				}
			}
		} while ((m = j) > 1);
	}
	
	// get separate count for each category
	for (i = 0; i < CMP_PRED_CATS_m13; ++i)
		for (cat_total_counts[i] = j = 0; j < stats_entries[i]; ++j)
			cat_total_counts[i] += sorted_count[i][j].count;
	
	// scale count so that each category's total_counts equals (RED_TOTAL_COUNTS - 1)
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		goal_total_counts[i] = CMP_RED_TOTAL_COUNTS_m13 - 1;
		if (no_zero_counts == TRUE_m13)
			goal_total_counts[i] -= (256 - stats_entries[i]);  // reserve one count in each model category for all zero count bins
		// TO DO: decide mapping scheme for unmapped symbols in symbol map
	}

	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		if (!stats_entries[i])
			continue;
		for (scaled_total_counts = j = 0; j < stats_entries[i]; ++j) {
			sorted_count[i][j].count = (ui4) (((((ui8) goal_total_counts[i] << 1) * (ui8) sorted_count[i][j].count) + (ui8) cat_total_counts[i]) / ((ui8) cat_total_counts[i] << 1));
			if (sorted_count[i][j].count == 0)
				sorted_count[i][j].count = 1;
			scaled_total_counts += (si8) sorted_count[i][j].count;
		}
		extra_counts = ((si8) goal_total_counts[i] - (si8) scaled_total_counts);
		if (extra_counts > 0) {
			do {
				for (j = 0; (j < stats_entries[i]) && extra_counts; ++j) {
					++sorted_count[i][j].count;
					--extra_counts;
				}
			} while (extra_counts);
		} else if (extra_counts < 0) {
			extra_counts = -extra_counts;
			do {
				for (j = stats_entries[i] - 1; (j >= 0) && extra_counts; --j) {
					if (sorted_count[i][j].count > 1) {
						--sorted_count[i][j].count;
						--extra_counts;
					}
				}
			} while (extra_counts);
		}
	}
	
	// build symbol maps, count arrays & minimum ranges
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (cumulative_count[i][0] = j = 0; j < stats_entries[i]; ++j) {
			symbol_map[i][(ui1) sorted_count[i][j].value] = (ui1) j;
			cumulative_count[i][j + 1] = cumulative_count[i][j] + (ui8) (count[i][j] = sorted_count[i][j].count);
			minimum_range[i][j] = CMP_RED_TOTAL_COUNTS_m13 / count[i][j];
			if (CMP_RED_TOTAL_COUNTS_m13 > (count[i][j] * minimum_range[i][j]))
				++minimum_range[i][j];
		}
	}
	if (no_zero_counts == TRUE_m13) {
		// complete each category's model: every byte value absent from its stored bins gets a rank
		// (stats_entries[c]..255) in ascending byte order with count 1 - the identical assignment
		// CMP_PRED2_decode_m13() reconstructs per category. Appended after the stored bins, so present-symbol
		// bounds are unchanged. Unused in same-block encoding (no absent symbol occurs) but keeps the
		// encoder & decoder models identical. Mirrors CMP_RED2_encode_m13().
		for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
			memset(present_enc, 0, sizeof(present_enc));
			for (j = 0; j < stats_entries[i]; ++j)
				present_enc[(ui1) sorted_count[i][j].value] = 1;
			for (k = stats_entries[i], j = 0; j < 256; ++j) {
				if (present_enc[j] == 0) {
					symbol_map[i][j] = (ui1) k;
					count[i][k] = 1;
					cumulative_count[i][k + 1] = cumulative_count[i][k] + (ui8) 1;
					minimum_range[i][k] = CMP_RED_TOTAL_COUNTS_m13;  // 65536 / 1
					++k;
				}
			}
		}
	}

	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_PRED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		*init_val_p++ = cps->params.derivative_buffer[i];

	// write scaled counts & symbols into header
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + total_stats_entries);
	for (i = 0; i < CMP_PRED_CATS_m13; ++i) {
		for (j = 0; j < stats_entries[i]; ++j) {
			*bin_counts++ = (ui2) sorted_count[i][j].count;
			*symbols++ = sorted_count[i][j].value;
		}
	}
	
	// fill header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	bh->model_region_bytes = (ui2) (ui2) (symbols - cps->params.model_region);
	bh->total_header_bytes = (ui4) (symbols - (ui1 *) bh);
	PRED_header->n_keysample_bytes = n_keysamp_bytes;
	
	// range encode
	key_p = (ui1 *) cps->params.keysample_buffer;
	comp_p = (ui1 *) bh + bh->total_header_bytes;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	prev_cat = CMP_PRED_NIL_m13;
	// No bounds check in this loop. The compressed buffer is sized by CMP_max_compressed_bytes_m13(), which
	// covers whatever this encoder can produce under the current directives: with FALL_THROUGH set, the MBE
	// block plus CMP_ESTIMATE_CUSHION_BYTES_m13 - a ceiling FITTED to 3087 matched (estimate, actual) pairs from
	// real & adversarial data at 1k-100k sample blocks, whose residual is a constant, not a fraction of block
	// size; with FALL_THROUGH clear, the range coder's derived worst case, CMP_RED_CODER_WORST_CASE_MULT_m13 x
	// the keysample stream. CMP_allocate_CPS_m13() FLOORS any caller-supplied size at that bound, so the room is
	// there whether or not the caller asked for it - which is what makes dropping the per-dump test safe.
	force_mbe = FALSE_m13;
	
	for (i = n_keysamp_bytes; i;) {
		for (; range >= minimum_range[prev_cat][bin = symbol_map[prev_cat][*key_p]]; key_p++) {
			high_bound = low_bound + ((range * cumulative_count[prev_cat][bin + 1]) >> 16);
			if (bin)
				low_bound += (range * cumulative_count[prev_cat][bin]) >> 16;
			range = high_bound - low_bound;
			if (!--i)
				break;
			prev_cat = CMP_PRED_CAT_m13(*key_p);
		}
		// full dump (all 6 bytes)
		if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p || !i) {
			--high_bound;  // ensure goal < high bound on decode
			ui1_p = high_bound_high_byte_p;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			range = CMP_RED_MAXIMUM_RANGE_m13;
			low_bound = 0;
		} else {  // partial dump (until bounds high bytes differ)
			do {
				*comp_p++ = *high_bound_high_byte_p;
				low_bound <<= 8;
				high_bound <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
			high_bound &= CMP_RED_RANGE_MASK_m13;
			range = high_bound - low_bound;
		}
	}
	
	// finish header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	PRED_total_bytes = (si8) (comp_p - (ui1 *) bh);
	bh->total_block_bytes = (ui4) G_pad_m13((ui1 *) bh, PRED_total_bytes, 8);

	// fall through to MBE if it is smaller, or forced (PRED overflowed the buffer, above)
	if (force_mbe == FALSE_m13 && !(cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13))
		return_m13(TRUE_m13);

PRED2_MBE_FALLBACK_m13:

	fall_through_bytes = (ui4) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);  // exact MBE size; sets use_raw & bits_per_samp for the emit
	// forced (overflow) => always take MBE; otherwise only if smaller than the PRED stream
	if (force_mbe == TRUE_m13 || fall_through_bytes < bh->total_block_bytes) {
		bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
		bh->block_flags |= CMP_BF_MBE_ENCODING_m13;
		MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
		if (use_raw == TRUE_m13) {
			// cps->input_buffer = unchanged
			MBE_header->minimum_value = cps->params.minimum_sample_value;
			MBE_header->derivative_level = 0;
		} else {
			cps->input_buffer = cps->params.derivative_buffer;
			MBE_header->minimum_value = cps->params.minimum_difference_value;
			MBE_header->derivative_level = n_derivs;
		}
		MBE_header->bits_per_sample = bits_per_samp;
		cps->params.MBE_preprocessed = TRUE_m13;  // handoff via CPS, not the never-zeroed block buffer
		CMP_MBE_encode_m13(cps);
	}

	return_m13(TRUE_m13);
}


sf8	CMP_PRED_estimate_bytes_m13(ui4 **cat_cnts)
{
	// Estimated PRED-encoded size in bytes: the sum of the per-category RED estimates over the CMP_PRED_CATS_m13
	// context models. This captures both PRED's context gain (each category's entropy is conditioned on the previous
	// symbol) & its per-model overhead (3 separate stats tables), which a single aggregate histogram cannot. Excludes
	// the PRED model fixed header & initial derivative values (caller adds those, as with CMP_RED_estimate_bytes_m13).
	si8	cat;
	sf8	bytes;

	for (bytes = (sf8) 0.0, cat = 0; cat < CMP_PRED_CATS_m13; ++cat)
		bytes += CMP_RED_estimate_bytes_m13(cat_cnts[cat], (si8) CMP_RED_MAX_STATS_BINS_m13);
	return(bytes);
}


// Algorithm from Niklaus Wirth's book: "Algorithms + data structures = programs".
// Code here is adapted from code by Nicolas Devillard. Public domain.
sf8	CMP_quantval_m13(sf8 *x, si8 len, sf8 quantile, tern preserve_input, sf8 *buf)
{
	tern	free_buf;
	sf8	q, fk, lo_p, lo_v, *lp, *mp, *last_mp, *lo_kp, *hi_kp;
	si8	lo_k;
	sf8	v, t, *xip, *xjp;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (len == 1)
		return_m13(*x);
	
	free_buf = FALSE_m13;
	if (preserve_input == TRUE_m13) {
		if (buf == NULL) {
			buf = (sf8 *) malloc((size_t) len << 3);  // same-function scratch => raw malloc (not tracked)
			if (buf == NULL) {
				G_set_error_m13(E_ALLOC_m13, NULL);
				return_m13((sf8) NAN);
			}
			free_buf = TRUE_m13;
		}
		memcpy(buf, x, (size_t) (len << 3));
		x = buf;
	}

	if (quantile < (sf8) 0.0)  // clamp out-of-range quantile (caller error) so the order-statistic index stays in bounds
		quantile = (sf8) 0.0;
	else if (quantile > (sf8) 1.0)
		quantile = (sf8) 1.0;

	if (quantile == (sf8)1.0) {
		lo_k = len - 2;
		lo_p = (sf8) 0.0;
	} else {
		fk = quantile * (sf8) (len - 1);
		lo_k = (si8) fk;
		lo_p = (sf8) 1.0 - (fk - (sf8) lo_k);
	}
	
	if (len == 2) {
		if (x[0] <= x[1])
			return_m13((x[0] * lo_p) + (x[1] * (1.0 - lo_p)));
		return_m13((x[1] * lo_p) + (x[0] * (1.0 - lo_p)));
	}
	
	lp = x;
	last_mp = mp = x + len - 1;
	lo_kp = x + lo_k;
	hi_kp = lo_kp + 1;
	while (lp < mp) {
		v = *lo_kp;
		xip = lp;
		xjp = mp;
		do {
			for (; *xip < v; ++xip);
			for (; v < *xjp; --xjp);
			if (xip <= xjp) {
				t = *xip;
				*xip++ = *xjp;
				*xjp-- = t;
			}
		} while (xip <= xjp);
		
		if (xjp < lo_kp)
			lp = xip;
		if (hi_kp < xip)
			last_mp = mp;
		if (lo_kp < xip)
			mp = xjp;
	}
	lo_v = *lo_kp;
	
	lp = lo_kp; mp = last_mp;
	while (lp < mp) {
		v = *hi_kp;
		xip = lp;
		xjp = mp;
		do {
			for (; *xip < v; ++xip);
			for (; v < *xjp; --xjp);
			if (xip <= xjp) {
				t = *xip;
				*xip++ = *xjp;
				*xjp-- = t;
			}
		} while (xip <= xjp);
		
		if (xjp < hi_kp)
			lp = xip;
		if (hi_kp < xip)
			mp = xjp;
	}
	
	q = (lo_v * lo_p) + (*hi_kp * ((sf8) 1.0 - lo_p));
	
	if (free_buf == TRUE_m13)
		free(buf);
	
	return_m13(q);
}


CPS_m13		*CMP_realloc_CPS_m13(FPS_m13 *fps, ui4 compression_mode, si8 data_samples, ui4 block_samples)
{
	tern			realloc_flag, freed;
	ui4			new_val;
	si4			i;
	si8			new_compressed_bytes, new_keysample_bytes, new_decompressed_samples;
	si8			mem_units_used, mem_units_avail, pad_samples, block_header_offset;
	CPS_m13			*cps;
	PROC_GLOBS_m13		*pg;
	CHAN_m13		*chan;
	SESS_m13		*sess;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif
	
	// returns NULL on failure

	if (fps->uh->type_code != TS_DATA_TYPE_CODE_m13) {
		G_set_error_m13(E_GEN_m13, "fps must be time series data");
		return_m13(NULL);
	}
	cps = fps->params.cps;
	if (cps == NULL)
		return_m13(NULL);
	
	realloc_flag = FALSE_m13;
	new_compressed_bytes = new_keysample_bytes = new_decompressed_samples = 0;
	
	if (cps->params.allocated_block_samples < block_samples)
		realloc_flag = TRUE_m13;
	
	switch (cps->direcs.flags & CPS_DF_ALGORITHM_MASK_m13) {
		case CPS_DF_RED1_ALGORITHM_m13:
		case CPS_DF_RED2_ALGORITHM_m13:
		case CPS_DF_PRED1_ALGORITHM_m13:
		case CPS_DF_PRED2_ALGORITHM_m13:
		case CPS_DF_VDS_ALGORITHM_m13:
			new_val = CMP_MAX_KEYSAMPLE_BYTES_m13(block_samples);
			if (cps->params.allocated_keysample_bytes < new_val) {
				new_keysample_bytes = new_val;
				realloc_flag = TRUE_m13;
			}
			break;
	}
	
	switch (compression_mode) {
		case CMP_COMPRESSION_MODE_m13:
			if (cps->params.allocated_compressed_bytes) {
				mem_units_used = (ui1 *) cps->block_header - fps->ts_data;
				mem_units_avail = cps->params.allocated_compressed_bytes - mem_units_used;
				new_val = CMP_max_compressed_bytes_m13(cps, (si8) block_samples, 1);  // CPS-aware: variable region, algorithm & fall-through directive
				if (mem_units_avail < new_val) {
					new_compressed_bytes = new_val + mem_units_used;
					realloc_flag = TRUE_m13;
				}
			}
			if (cps->params.allocated_decompressed_samples > 0) {
				// extent measured from params.cache, the REAL base: decompressed_data is the shallow caller's
				// view (cache + offset, see CMP_decode_m13() & G_read_time_series_data_m13()) &
				// allocated_decompressed_samples sizes the whole cache. Measuring the used extent from
				// decompressed_data instead dropped the (decompressed_data - cache) offset, over-reporting the
				// space left by exactly that offset - so a cache that needed to grow could be judged big enough.
				mem_units_used = cps->decompressed_ptr - cps->params.cache;
				mem_units_avail = cps->params.allocated_decompressed_samples - mem_units_used;
				if (mem_units_avail < block_samples) {
					new_decompressed_samples = mem_units_used + block_samples;
					realloc_flag = TRUE_m13;
				}
			}
			break;
		case CMP_DECOMPRESSION_MODE_m13:
			if (cps->params.allocated_decompressed_samples > 0) {  // see the note above
				mem_units_used = cps->decompressed_ptr - cps->params.cache;
				mem_units_avail = cps->params.allocated_decompressed_samples - mem_units_used;
				if (mem_units_avail < data_samples) {
					new_decompressed_samples = mem_units_used + data_samples;
					realloc_flag = TRUE_m13;
				}
			}
			break;
		default:
			G_set_error_m13(E_CMP_m13, "invalid compression mode specified\n");
			return_m13(NULL);
	}
	
	if (realloc_flag == FALSE_m13)
		return_m13(cps);

	// CALLER-OWNED buffers are never freed & never moved, so a needed growth cannot be satisfied - fail LOUDLY
	// rather than proceed into a buffer we cannot grow. The sizes above are true (ownership is a directive, not
	// a sentinel in the size field), so this is a real bounds check & not a guess.
	if (new_decompressed_samples && (cps->direcs.flags & CPS_DF_CALLER_OWNS_DECOMPRESSED_m13)) {
		G_set_error_m13(E_CMP_m13, "caller-owned decompressed buffer holds %ld samples but %ld are needed", cps->params.allocated_decompressed_samples, new_decompressed_samples);
		return_m13(NULL);
	}
	if (new_compressed_bytes && (cps->direcs.flags & CPS_DF_CALLER_OWNS_COMPRESSED_m13)) {
		G_set_error_m13(E_CMP_m13, "caller-owned compressed buffer holds %ld bytes but %ld are needed", cps->params.allocated_compressed_bytes, new_compressed_bytes);
		return_m13(NULL);
	}

	// reallocate. SCRATCH buffers below are free & alloc (nothing in them outlives the block); the DECOMPRESSED
	// cache is copied, since its whole purpose is to survive (see the note at that branch).
	if (new_compressed_bytes) {
		// FPS_realloc_m13() PRESERVES the buffer contents (recalloc_m13) but resets cps->block_header to the BASE
		// of the data region. In compression mode that pointer is the WRITE CURSOR for the next block, & any
		// blocks already encoded but not yet written to disk sit behind it - so the reset made the next block
		// header land on top of BLOCK 0: bytes kept, cursor lost, which is worse than a clean discard because the
		// caller has no way to know. Capture the offset before the buffer moves & restore it after.
		// NOTE: mem_units_used cannot be reused here - the decompressed branch of the switch above overwrites it.
		block_header_offset = (ui1 *) cps->block_header - fps->ts_data;
		if (FPS_realloc_m13(fps, new_compressed_bytes) == FALSE_m13)
			goto CMP_REALLOC_CPS_FAIL_m13;
		cps->block_header = (CMP_FIXED_BH_m13 *) (fps->ts_data + block_header_offset);
	}
	
	if (new_keysample_bytes) {
		free_m13((void * ) cps->params.keysample_buffer);
		if ((cps->params.keysample_buffer = (si1 *) calloc_m13((size_t) new_keysample_bytes, sizeof(ui1))) == NULL)
			goto CMP_REALLOC_CPS_FAIL_m13;
		cps->params.allocated_keysample_bytes = new_keysample_bytes;
	}
	
	if (new_decompressed_samples) {
		// PRESERVE the decode cache across the grow. params.cache is the real base; decompressed_data is the
		// shallow caller's view into it & decompressed_ptr its movable index. The cache exists so that blocks
		// already read & decoded are not re-read & re-decompressed when the next request is contiguous, so
		// free+calloc here silently threw away exactly what the cache is for - & reset both pointers to the
		// base, moving the caller's array out from under it. Copy the window, then re-derive both pointers from
		// their old offsets off the new base.
		// Needing to grow at all is normally a CALLER sizing error (DATA buffers are the caller's contract - see
		// CMP_fit_CPS_scratch_m13() for what the library owns), hence the warning: handled, but not silently.
		si4	*new_cache;
		si8	old_samples, data_offset, ptr_offset;

		if ((new_cache = (si4 *) calloc_m13((size_t) new_decompressed_samples, sizeof(si4))) == NULL)
			goto CMP_REALLOC_CPS_FAIL_m13;
		data_offset = ptr_offset = 0;
		if (cps->params.cache) {
			old_samples = cps->params.allocated_decompressed_samples;
			if (old_samples > new_decompressed_samples)  // never on a grow, but the copy must not outrun either block
				old_samples = new_decompressed_samples;
			if (old_samples > 0)
				memcpy((void *) new_cache, (void *) cps->params.cache, (size_t) old_samples * sizeof(si4));
			data_offset = cps->decompressed_data - cps->params.cache;
			ptr_offset = cps->decompressed_ptr - cps->params.cache;
			free_m13((void * ) cps->params.cache);
		}
		cps->params.cache = new_cache;
		cps->decompressed_data = new_cache + data_offset;
		cps->decompressed_ptr = new_cache + ptr_offset;
		cps->params.allocated_decompressed_samples = calloc_size_m13(new_cache, sizeof(si4));
		if (cps->params.allocated_decompressed_samples == 0)  // size query unavailable (MATLAB persistent): use the requested size
			cps->params.allocated_decompressed_samples = new_decompressed_samples;
		G_warning_message_m13("%s(): decompressed data buffer grown to %ld samples - caller under-sized the CPS data buffer\n", __FUNCTION__, cps->params.allocated_decompressed_samples);
	}
		
	// reallocate the following if they were previously allocated
	if (cps->params.allocated_block_samples < block_samples) {
		if (cps->params.detrended_buffer) {
			free_m13((void * ) cps->params.detrended_buffer);
			if ((cps->params.detrended_buffer = (si4 *) calloc_m13((size_t) block_samples, sizeof(si4))) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}
		// derivative & SRRED buffers: malloc, not calloc, matching CMP_allocate_CPS_m13(). They are fully written
		// before they are read on every block (the derivative anchors at indices 0..level-1 included, since the
		// 2026-08-02 anchor fix), so zeroing them buys nothing but a pass over the memory every realloc.
		// derivative pair: resize through the OWNING handles & re-publish the views. Doing this through the
		// views double-freed mid-recording whenever the search had left them aliased (this runs on every
		// block that grows past allocated_block_samples, not just at teardown).
		if (cps->params.derivative_bufs[0]) {
			free_m13((void * ) cps->params.derivative_bufs[0]);
			if ((cps->params.derivative_bufs[0] = (si4 *) malloc_m13((size_t) (block_samples << 2))) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}
		if (cps->params.derivative_bufs[1]) {
			free_m13((void * ) cps->params.derivative_bufs[1]);
			if ((cps->params.derivative_bufs[1] = (si4 *) malloc_m13((size_t) (block_samples << 2))) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}
		// views follow the allocations: the old targets are gone, & the search re-establishes roles per block
		cps->params.derivative_buffer = cps->params.derivative_bufs[0];
		cps->params.next_derivative_buffer = cps->params.derivative_bufs[1];
		// SRRED residuals/overflows: these were NOT being reallocated at all, so a caller that encoded a larger
		// block later (CMP_encode_m13() reallocs on a bigger n_samples) wrote block_samples si4 into a buffer
		// sized for the previous, smaller block.
		if (cps->params.residuals_buffer) {
			free_m13((void * ) cps->params.residuals_buffer);
			if ((cps->params.residuals_buffer = (si4 *) malloc_m13((size_t) (block_samples << 2))) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}
		if (cps->params.overflows_buffer) {
			free_m13((void * ) cps->params.overflows_buffer);
			if ((cps->params.overflows_buffer = (si4 *) malloc_m13((size_t) (block_samples << 2))) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}

		if (cps->params.VDS_input_buffers) {
			if (compression_mode == CMP_COMPRESSION_MODE_m13)
				pad_samples = CMP_VDS_LOWPASS_ORDER_m13 * 6;
			else
				pad_samples = CMP_MAK_PAD_SAMPLES_m13;
			if (CMP_allocate_buffers_m13(cps->params.VDS_input_buffers, CMP_VDS_INPUT_BUFFERS_m13, (si8) (block_samples + pad_samples), sizeof(sf8), FALSE_m13, FALSE_m13) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
			if (CMP_allocate_buffers_m13(cps->params.VDS_output_buffers, CMP_VDS_OUTPUT_BUFFERS_m13, (si8) block_samples, sizeof(sf8), FALSE_m13, FALSE_m13) == NULL)
				goto CMP_REALLOC_CPS_FAIL_m13;
		}
		cps->params.allocated_block_samples = block_samples;
	}
	
	return_m13(cps);
	
CMP_REALLOC_CPS_FAIL_m13:

	// try freeing caches on inactive channels
	pg = G_proc_globs_m13(fps);
	chan = pg->current_session.index_channel;
	freed = FALSE_m13;
	if (chan) {
		sess = (SESS_m13 *) chan;
		if (sess->type_code == SESS_TYPE_CODE_m13) {
			for (i = 0; i < sess->n_ts_chans; ++i) {
				chan = sess->ts_chans[i];
				if (chan->type_code == TS_CHAN_TYPE_CODE_m13)
					if ((chan->flags & LH_CHAN_ACTIVE_m13) == 0)
						if (CMP_free_CPS_cache_m13(cps) == TRUE_m13)
							freed = TRUE_m13;
			}
		}
	}

	if (freed == TRUE_m13) {
		cps = CMP_realloc_CPS_m13(fps, compression_mode, data_samples, block_samples);
		return_m13(cps);  // CMP_realloc_CPS_m13 returns NULL on failure, which this function also does
	}

	return_m13(NULL);
}


tern	CMP_rectify_m13(si4 *input_buffer, si4 *output_buffer, si8 len)
{
	si4  *si4_p1, *si4_p2;
	si8  i;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// rectify data from input_buffer to output_buffer
	// if input_buffer == output_buffer rectification will be done in place
	
	si4_p1 = input_buffer;
	si4_p2 = output_buffer;
	for (i = len; i--; ++si4_p1)
		*si4_p2++ = ABS_m13(*si4_p1);
	
	return_m13(TRUE_m13);
}


tern	CMP_RED1_decode_m13(CPS_m13 *cps)
{
	tern				pos_derivs, no_zero_counts;
	ui1				*comp_p, *low_bound_high_byte_p, *high_bound_high_byte_p, *goal_bound_high_byte_p;
	ui1				*ui1_p1, *ui1_p2, *symbol_map, n_derivs, overflow_bytes;
	si1				*si1_p1, *si1_p2, *key_p;
	ui2				*count;
	ui4				n_samps, n_keysample_bytes;
	si4				*si4_p, overflow_val, sign_bit, sign_bytes, *init_val_p;
	ui8				*minimum_range, *cumulative_count;
	ui8				low_bound, high_bound, prev_high_bound, goal_bound, range;
	si8				i, j, n_stats_entries;
	CMP_FIXED_BH_m13		*bh;
	CMP_RED_MODEL_FIXED_HDR_m13	*RED_header;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP decompress from bh to decompressed_ptr
	bh = cps->block_header;
	n_samps = bh->number_of_samples;
	
	// zero or one or samples
	if (n_samps <= 1) {
		if (bh->number_of_samples == 1)
			cps->decompressed_ptr[0] = *((si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13));
		cps->params.derivative_level = 0;
		return_m13(TRUE_m13);
	}

	RED_header = (CMP_RED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_derivs = RED_header->derivative_level;
	n_keysample_bytes = RED_header->n_keysample_bytes;
	n_stats_entries = (si8) RED_header->n_statistics_bins;
	
	// set parameters for return
	cps->params.derivative_level = RED_header->derivative_level;
	
	// get block flags
	if (RED_header->flags & CMP_RED_FLAGS_NO_ZERO_COUNTS_m13)
		no_zero_counts = TRUE_m13;
	else
		no_zero_counts = FALSE_m13;
	if (RED_header->flags & CMP_RED_FLAGS_POSITIVE_DERIVATIVES_m13)
		pos_derivs = TRUE_m13;
	else
		pos_derivs = FALSE_m13;
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_DECOMPRESSION_MODE_m13, CMP_RED_COMPRESSION_m13);
	sign_bit = (ui4) 1 << ((overflow_bytes << 3) - 1);
	if (overflow_bytes == 4)
		sign_bytes = (ui4) 0;
	else  // Windows: shift of 32 bits is equated to shift of 0, so have to do this
		sign_bytes = (ui4) 0xFFFFFFFF << (overflow_bytes << 3);
	
	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		cps->decompressed_ptr[i] = *init_val_p++;

	// build symbol map, count array, & minimum ranges
	count = (ui2 *) init_val_p;
	symbol_map = (ui1 *) (count + n_stats_entries);
	if (no_zero_counts == TRUE_m13) {  // TO DO: decide mapping scheme for unmapped symbols in symbol map
		for (i = n_stats_entries; i < 256; ++i)  // TO DO: copy count & symbol map to arrays with 256 elements
			count[i] = 1;
	}
	cumulative_count = (ui8 *) cps->params.cumulative_count;
	minimum_range = (ui8 *) cps->params.minimum_range;
	for (cumulative_count[0] = i = 0; i < n_stats_entries; ++i) {
		cumulative_count[i + 1] = cumulative_count[i] + (ui8) count[i];
		minimum_range[i] = CMP_RED_TOTAL_COUNTS_m13 / count[i];
		if (CMP_RED_TOTAL_COUNTS_m13 > (count[i] * minimum_range[i]))
			++minimum_range[i];
	}

	// range decode
	key_p = cps->params.keysample_buffer;
	prev_high_bound = goal_bound = low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	comp_p = symbol_map + n_stats_entries;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	goal_bound_high_byte_p = ((ui1 *) &goal_bound) + 5;
	ui1_p1 = goal_bound_high_byte_p;
	j = 6; do {
		*ui1_p1-- = *comp_p++;
	} while (--j);
	
	for (i = n_keysample_bytes; i;) {
		for (j = 0; range >= minimum_range[j];) {
			high_bound = low_bound + ((range * cumulative_count[j + 1]) >> 16);
			if (high_bound > goal_bound) {
				range = high_bound - (low_bound = prev_high_bound);
				*key_p = symbol_map[j];
				if (!--i)
					goto RED1_RANGE_DECODE_DONE_m13;
				++key_p;
				j = 0;
			} else {
				prev_high_bound = high_bound;
				++j;
			}
		}
		high_bound = low_bound + range;
		if (*low_bound_high_byte_p != *high_bound_high_byte_p) {
			ui1_p1 = goal_bound_high_byte_p;
			j = 6; do {
				*ui1_p1-- = *comp_p++;
			} while (--j);
			low_bound = 0;
			range = CMP_RED_MAXIMUM_RANGE_m13;
		} else {
			do {
				low_bound <<= 8;
				high_bound <<= 8;
				goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				range <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
			goal_bound &= CMP_RED_RANGE_MASK_m13;
		}
		prev_high_bound = low_bound;
	} RED1_RANGE_DECODE_DONE_m13:
		
	// generate derivatives from keysample data
	si4_p = cps->decompressed_ptr + n_derivs;
	if (pos_derivs == TRUE_m13) {
		ui1_p1 = (ui1 *) cps->params.keysample_buffer;
		for (i = n_samps - n_derivs; i--;) {
			if (*ui1_p1 == CMP_POS_DERIV_KEYSAMPLE_FLAG_m13) {
				++ui1_p1;
				overflow_val = 0;
				ui1_p2 = (ui1 *) &overflow_val;
				j = overflow_bytes; do {
					*ui1_p2++ = *ui1_p1++;
				} while (--j);
				*si4_p++ = overflow_val;
			} else {
				*si4_p++ = (si4) *ui1_p1++;
			}
		}
	} else {
		si1_p1 = (si1 *) cps->params.keysample_buffer;
		for (i = n_samps - n_derivs; i--;) {
			if (*si1_p1 == CMP_SI1_KEYSAMPLE_FLAG_m13) {
				overflow_val = 0;
				++si1_p1;
				si1_p2 = (si1 *) &overflow_val;
				j = overflow_bytes; do {
					*si1_p2++ = *si1_p1++;
				} while (--j);
				if (overflow_val & sign_bit)
					overflow_val |= sign_bytes;
				*si4_p++ = overflow_val;
			} else {
				*si4_p++ = (si4) *si1_p1++;
			}
		}
	}
	
	// integrate derivatives
	CMP_integrate_m13(cps);
	
	return_m13(TRUE_m13);
}


tern	CMP_RED1_encode_m13(CPS_m13 *cps)
{
	tern				pos_derivs, no_zero_counts, use_raw;
	ui1				*low_bound_high_byte_p, *high_bound_high_byte_p, *ui1_p, ks_flag;
	ui1				*key_p, n_derivs, *comp_p, *symbols, *symbol_map, overflow_bytes;
	ui2				*bin_counts;
	ui4				*count, n_keysamp_bytes, RED_total_bytes;
	ui4				n_samps, n_deriv_samps, goal_total_counts, bin, fall_through_bytes;
	si4				*deriv_p, *init_val_p, diff, bits_per_samp;
	si4				low_d, high_d;
	ui8				*cumulative_count, *minimum_range;
	ui8				total_counts, range, high_bound, low_bound;
	si8				i, j, k, n_stats_entries, extra_counts, scaled_total_counts;
	CMP_STATISTICS_BIN_m13		*sorted_count, temp_sorted_count;
	CMP_FIXED_BH_m13		*bh;
	CMP_RED_MODEL_FIXED_HDR_m13	*RED_header;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// compress from input_buffer to bh
	
	// set algorithm block flag
	bh = cps->block_header;
	bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
	bh->block_flags |= CMP_BF_RED1_ENCODING_m13;

	RED_header = (CMP_RED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_samps = bh->number_of_samples;
	RED_header->flags = (ui2) 0;
	// pad is WRITTEN TO THE FILE, so it must be deterministic. model_region is a reused CPS buffer &
	// nothing anywhere assigns pad, so it otherwise carries bytes left by whatever block used the buffer
	// before: byte-identical re-encoding is impossible, & arbitrary heap contents land in a WORM archive.
	// (These are also the bytes a per-block derivative offset would live in - see the offset design.)
	memset(RED_header->pad, 0, sizeof(RED_header->pad));

	// zero or one or samples
	if (n_samps <= 1) {
		bh->model_region_bytes = (ui2) CMP_RED_MODEL_FIXED_HDR_BYTES_m13;
		if (bh->number_of_samples == 1) {
			*((si4 *) (cps->params.model_region + bh->model_region_bytes)) = cps->input_buffer[0];  // note: no statistics
			bh->model_region_bytes += sizeof(si4);
		}
		RED_header->n_keysample_bytes = 0;
		RED_header->derivative_level = 0;
		RED_header->n_statistics_bins = 0;
		bh->total_header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh) + bh->model_region_bytes;
		bh->total_block_bytes = G_pad_m13((ui1 *) bh, bh->total_header_bytes, 8);
		return_m13(TRUE_m13);
	}

	// calculate derivatives
	n_derivs = CMP_differentiate_m13(cps);

	// set up RED arrays
	count = (ui4 *) cps->params.count;
	cumulative_count = (ui8 *) cps->params.cumulative_count;
	minimum_range = (ui8 *) cps->params.minimum_range;
	sorted_count = (CMP_STATISTICS_BIN_m13 *) cps->params.sorted_count;
	symbol_map = (ui1 *) cps->params.symbol_map;

	// set model parameters
	RED_header->derivative_level = n_derivs;
	// RETIRED 2026-08-06: the all-positive model is no longer emitted. The per-block derivative offset covers
	// the same ground (it places the 255-value window where the data is, instead of assuming 128) and covers
	// more of it, so its last caller - VDS times - now relies on the offset. DECODERS still honour the flag:
	// files in the wild may carry it, because before 2026-08-02 it was set by an auto-detect sniff that fired
	// on ordinary sample data. ⚠️ Do NOT reuse bit 1 (see CMP_RED_FLAGS_POSITIVE_DERIVATIVES_m13).
	pos_derivs = FALSE_m13;
	if (cps->direcs.flags & CPS_DF_NO_ZERO_COUNTS_m13) {
		no_zero_counts = TRUE_m13;
		RED_header->flags |= CMP_RED_FLAGS_NO_ZERO_COUNTS_m13;
	} else {
		no_zero_counts = FALSE_m13;
	}
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_COMPRESSION_MODE_m13, CMP_RED_COMPRESSION_m13);

	// generate count & build keysample array
	
	CMP_derivative_window_m13(pos_derivs, &low_d, &high_d, &ks_flag);
	memset(count, 0, CMP_RED_MAX_STATS_BINS_m13 * sizeof(ui4));
	
	key_p = (ui1 *) cps->params.keysample_buffer;
	deriv_p = cps->params.derivative_buffer + n_derivs;
	n_deriv_samps = n_samps - n_derivs;
	for (i = n_deriv_samps; i--;) {
		diff = *deriv_p++;
		if (diff < low_d || diff > high_d) {
			ui1_p = (ui1 *) &diff;
			++count[*key_p++ = ks_flag];
			j = overflow_bytes; do {
				++count[*key_p++ = *ui1_p++];
			} while (--j);
		} else {
			++count[*key_p++ = (ui1) diff];
		}
	}
	n_keysamp_bytes = (ui4) (key_p - (ui1 *) cps->params.keysample_buffer);

	// build sorted_count
	if (pos_derivs == TRUE_m13) {
		for (i = n_stats_entries = 0; i < 256; ++i) {
			if (count[i]) {
				sorted_count[n_stats_entries].count = count[i];
				sorted_count[n_stats_entries++].pos_value = (ui1) i;
			}
		}
	} else {  // pos_derivs == FALSE_m13: interleave (to speed up sort)
		for (i = n_stats_entries = 0, j = 255, k = 128; k--; ++i, --j) {
			if (count[i]) {
				sorted_count[n_stats_entries].count = count[i];
				sorted_count[n_stats_entries++].value = (si1) i;
			}
			if (count[j]) {
				sorted_count[n_stats_entries].count = count[j];
				sorted_count[n_stats_entries++].value = (si1) j;
			}
		}
	}
	RED_header->n_statistics_bins = (ui2) n_stats_entries;
	
	// build sorted_count: bubble sort
	i = n_stats_entries;
	do {
		for (j = 0, k = 1; k < i; ++k) {
			if (sorted_count[k - 1].count < sorted_count[k].count) {
				temp_sorted_count = sorted_count[k - 1];
				sorted_count[k - 1] = sorted_count[k];
				sorted_count[k] = temp_sorted_count;
				j = k;  // highest swap index
			}
		}
	} while ((i = j) > 1);
		
	// scale count so that total counts equals (RED_TOTAL_COUNTS - 1)
	goal_total_counts = CMP_RED_TOTAL_COUNTS_m13 - 1;
	if (no_zero_counts == TRUE_m13) {
		goal_total_counts -= (256 - n_stats_entries); // reserve one count in model for all zero count bins
		// TO DO: decide mapping scheme for unmapped symbols in symbol map
	}
	total_counts = (ui8) n_keysamp_bytes;
	for (scaled_total_counts = i = 0; i < n_stats_entries; ++i) {
		sorted_count[i].count = (ui4) (((((ui8) goal_total_counts << 1) * (ui8) sorted_count[i].count) + total_counts) / (total_counts << 1));
		if (sorted_count[i].count == 0)
			sorted_count[i].count = 1;
		scaled_total_counts += (si8) sorted_count[i].count;
	}
	extra_counts = ((si8) goal_total_counts - (si8) scaled_total_counts);
	if (extra_counts > 0) {
		do {
			for (i = 0; (i < n_stats_entries) && extra_counts; ++i) {
				++sorted_count[i].count;
				--extra_counts;
			}
		} while (extra_counts);
	} else if (extra_counts < 0) {
		extra_counts = -extra_counts;
		do {
			for (i = n_stats_entries - 1; (i >= 0) && extra_counts; --i) {
				if (sorted_count[i].count > 1) {
					--sorted_count[i].count;
					--extra_counts;
				}
			}
		} while (extra_counts);
	}
	
	// build symbol map, count array & minimum ranges
	for (cumulative_count[0] = i = 0; i < n_stats_entries; ++i) {
		symbol_map[sorted_count[i].pos_value] = (ui1) i;
		cumulative_count[i + 1] = cumulative_count[i] + (ui8) (count[i] = sorted_count[i].count);
		minimum_range[i] = CMP_RED_TOTAL_COUNTS_m13 / count[i];
		if (CMP_RED_TOTAL_COUNTS_m13 > (count[i] * minimum_range[i]))
			++minimum_range[i];
	}
	
	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		*init_val_p++ = cps->params.derivative_buffer[i];

	// write scaled counts & symbols into header
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + n_stats_entries);
	for (i = 0; i < n_stats_entries; ++i) {
		*bin_counts++ = (ui2) sorted_count[i].count;
		*symbols++ = sorted_count[i].value;
	}
	
	// fill header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	bh->model_region_bytes = (ui2) (symbols - cps->params.model_region);
	bh->total_header_bytes = (ui4) (symbols - (ui1 *) bh);
	RED_header->n_keysample_bytes = n_keysamp_bytes;

	// range encode
	key_p = (ui1 *) cps->params.keysample_buffer;
	comp_p = symbols;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	
	for (i = n_keysamp_bytes; i;) {
		for (; range >= minimum_range[bin = symbol_map[*key_p]]; key_p++) {
			high_bound = low_bound + ((range * cumulative_count[bin + 1]) >> 16);
			if (bin)
				low_bound += (range * cumulative_count[bin]) >> 16;
			range = high_bound - low_bound;
			if (!--i)
				break;
		}
		if ((*low_bound_high_byte_p != *high_bound_high_byte_p) || !i) {
			ui1_p = low_bound_high_byte_p;
			j = 6; do {
				*comp_p++ = *ui1_p--;
			} while (--j);
			range = CMP_RED_MAXIMUM_RANGE_m13;
			low_bound = 0;
		} else {
			do {
				*comp_p++ = *low_bound_high_byte_p;
				low_bound <<= 8;
				high_bound <<= 8;
				range <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
		}
	}
		
	// finish header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	RED_total_bytes = (si8) (comp_p - (ui1 *) bh);
	bh->total_block_bytes = (ui4) G_pad_m13((ui1 *) bh, RED_total_bytes, 8);
	
	// calculate fall through encoding bytes
	if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13) {
		fall_through_bytes = (ui4) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);  // exact MBE size; sets use_raw & bits_per_samp for the emit
		if (fall_through_bytes < bh->total_block_bytes) {
			bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
			bh->block_flags |= CMP_BF_MBE_ENCODING_m13;
			MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
			if (use_raw == TRUE_m13) {
				// cps->input_buffer = unchanged
				MBE_header->minimum_value = cps->params.minimum_sample_value;
				MBE_header->derivative_level = 0;
			} else {
				cps->input_buffer = cps->params.derivative_buffer;
				MBE_header->minimum_value = cps->params.minimum_difference_value;
				MBE_header->derivative_level = n_derivs;
			}
			MBE_header->bits_per_sample = bits_per_samp;
			cps->params.MBE_preprocessed = TRUE_m13;  // handoff via CPS, not the never-zeroed block buffer
			CMP_MBE_encode_m13(cps);
			return_m13(TRUE_m13);
		}
	}
		
	return_m13(TRUE_m13);
}


tern	CMP_RED2_decode_m13(CPS_m13 *cps)
{
	tern				pos_derivs, no_zero_counts, multiply_method;
	ui1				*comp_p, *low_bound_high_byte_p, *high_bound_high_byte_p, *goal_bound_high_byte_p;
	ui1				*ui1_p1, *ui1_p2, *symbol_map, n_derivs, overflow_bytes;
	ui1				*block_symbols, present[256], symbol_map_exp[256];
	si1				*si1_p1, *si1_p2, *key_p;
	ui2				*count, *block_count, count_exp[256];
	ui4				n_samps, n_keysample_bytes;
	si4				*si4_p, overflow_val, sign_bit, sign_bytes, *init_val_p;
	ui8				*minimum_range, *cumulative_count;
	ui8				low_bound, high_bound, prev_high_bound, goal_bound, range, target_cc;
	si8				i, j, n_stats_entries, n_stored;
	sf8				average_steps, multiply_time;
	CMP_FIXED_BH_m13		*bh;
	CMP_RED_MODEL_FIXED_HDR_m13	*RED_header;
	HW_PERFORMANCE_SPECS_m13	*perf_specs;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// CMP decompress from bh to decompressed_ptr
	bh = cps->block_header;
	n_samps = bh->number_of_samples;
	
	// zero or one or samples
	if (n_samps <= 1) {
		if (bh->number_of_samples == 1)
			cps->decompressed_ptr[0] = *((si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13));
		cps->params.derivative_level = 0;
		return_m13(TRUE_m13);
	}

	RED_header = (CMP_RED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_derivs = RED_header->derivative_level;
	n_keysample_bytes = RED_header->n_keysample_bytes;
	n_stored = (si8) RED_header->n_statistics_bins;  // bins physically stored in the block
	
	// set parameters for return
	cps->params.derivative_level = RED_header->derivative_level;
	
	// get block flags
	if (RED_header->flags & CMP_RED_FLAGS_NO_ZERO_COUNTS_m13)
		no_zero_counts = TRUE_m13;
	else
		no_zero_counts = FALSE_m13;
	if (RED_header->flags & CMP_RED_FLAGS_POSITIVE_DERIVATIVES_m13)
		pos_derivs = TRUE_m13;
	else
		pos_derivs = FALSE_m13;
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_DECOMPRESSION_MODE_m13, CMP_RED_COMPRESSION_m13);
	sign_bit = (ui4) 1 << ((overflow_bytes << 3) - 1);
	if (overflow_bytes == 4)
		sign_bytes = (ui4) 0;
	else  // Windows: shift of 32 bits is equated to shift of 0, so have to do this
		sign_bytes = (ui4) 0xFFFFFFFF << (overflow_bytes << 3);
	
	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		cps->decompressed_ptr[i] = *init_val_p++;

	// build model: symbol_map (rank -> byte value), counts, cumulative counts, minimum ranges
	// normal: the model is exactly the bins stored in the block (n_stored)
	// no_zero_counts: the block stores only nonzero bins; every byte value absent from the stored
	//   symbol list is an implicit count-1 bin, assigned ranks n_stored..255 in ascending byte order.
	//   Encoder & decoder derive this identical assignment from the stored symbol list alone, so no
	//   zero-count bins are stored (the point of the mode). Ranks are appended AFTER the stored bins,
	//   so present-symbol bounds are unchanged; this only adds coverage for symbols that were absent
	//   from the model but can still appear (e.g. a block encoded against a prior block's statistics).
	block_count = (ui2 *) init_val_p;
	block_symbols = (ui1 *) (block_count + n_stored);
	if (no_zero_counts == TRUE_m13) {
		memset(present, 0, sizeof(present));
		for (i = 0; i < n_stored; ++i) {
			count_exp[i] = block_count[i];
			symbol_map_exp[i] = block_symbols[i];
			present[block_symbols[i]] = 1;
		}
		for (j = n_stored, i = 0; i < 256; ++i) {  // absent byte values, ascending order, count 1
			if (present[i] == 0) {
				count_exp[j] = 1;
				symbol_map_exp[j++] = (ui1) i;
			}
		}
		count = count_exp;
		symbol_map = symbol_map_exp;
		n_stats_entries = 256;
	} else {
		count = block_count;
		symbol_map = block_symbols;
		n_stats_entries = n_stored;
	}
	cumulative_count = (ui8 *) cps->params.cumulative_count;
	minimum_range = (ui8 *) cps->params.minimum_range;
	for (cumulative_count[0] = i = 0; i < n_stats_entries; ++i) {
		cumulative_count[i + 1] = cumulative_count[i] + (ui8) count[i];
		minimum_range[i] = CMP_RED_TOTAL_COUNTS_m13 / count[i];
		if (CMP_RED_TOTAL_COUNTS_m13 > (count[i] * minimum_range[i]))
			++minimum_range[i];
	}

	// determine decompression method
	perf_specs = &globals_m13->tables->HW_params.performance_specs;  // gathered at G_init_medlib_m13()
	for (average_steps = (sf8) 0.0, i = 0; i < n_stats_entries; ++i)
		average_steps += (sf8) (i * (si8) count[i]);
	average_steps /= (sf8) CMP_RED_TOTAL_COUNTS_m13;
	multiply_time = average_steps * perf_specs->nsecs_per_integer_multiplication;
	if (multiply_time < perf_specs->nsecs_per_integer_division)
		multiply_method = TRUE_m13;
	else
		multiply_method = FALSE_m13;

	// range decode
	key_p = cps->params.keysample_buffer;
	prev_high_bound = goal_bound = low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	comp_p = block_symbols + n_stored;  // compressed stream starts after the STORED bins (not the expanded model)
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	goal_bound_high_byte_p = ((ui1 *) &goal_bound) + 5;
	ui1_p1 = goal_bound_high_byte_p;
	*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;
	*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;

	if (multiply_method == TRUE_m13) {
		for (j = 0, i = n_keysample_bytes; i;) {
			while (range >= minimum_range[j]) {
				high_bound = low_bound + ((range * cumulative_count[j + 1]) >> 16);
				if (high_bound > goal_bound) {
					*key_p++ = symbol_map[j];
					if (!--i)
						goto RED2_RANGE_DECODE_DONE_m13;
					range = high_bound - (low_bound = prev_high_bound);
					j = 0;
				} else {
					prev_high_bound = high_bound;
					++j;
				}
			}
			high_bound = low_bound + range;
			if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p) {
				ui1_p1 = goal_bound_high_byte_p;
				*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;
				*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;
				low_bound = 0;
				range = CMP_RED_MAXIMUM_RANGE_m13;
			} else {
				do {
					low_bound <<= 8;
					high_bound <<= 8;
					goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
				low_bound &= CMP_RED_RANGE_MASK_m13;
				high_bound &= CMP_RED_RANGE_MASK_m13;
				goal_bound &= CMP_RED_RANGE_MASK_m13;
				range = high_bound - low_bound;
			}
			prev_high_bound = low_bound;
			if (j)
				prev_high_bound += (range * cumulative_count[j]) >> 16;
		}
	} else {  // division method
		for (j = 0, i = n_keysample_bytes; i;) {
			while (range >= minimum_range[j]) {
				high_bound = low_bound + ((range * cumulative_count[j + 1]) >> 16);
				if (high_bound > goal_bound) {
					*key_p++ = symbol_map[j];
					if (!--i)
						goto RED2_RANGE_DECODE_DONE_m13;
					range = high_bound - (low_bound = prev_high_bound);
					target_cc = ((goal_bound - low_bound) << 16) / range;
					for (j = 1; j < n_stats_entries; ++j)
						if (target_cc <= cumulative_count[j])
							break;
					if (--j)
						prev_high_bound += (range * cumulative_count[j]) >> 16;
				} else {
					prev_high_bound = high_bound;
					++j;
				}
			}
			high_bound = low_bound + range;
			if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p) {
				ui1_p1 = goal_bound_high_byte_p;
				*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;
				*ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++; *ui1_p1-- = *comp_p++;
				low_bound = 0;
				range = CMP_RED_MAXIMUM_RANGE_m13;
			} else {
				do {
					low_bound <<= 8;
					high_bound <<= 8;
					goal_bound = (goal_bound << 8) | (ui8) *comp_p++;
				} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
				low_bound &= CMP_RED_RANGE_MASK_m13;
				high_bound &= CMP_RED_RANGE_MASK_m13;
				goal_bound &= CMP_RED_RANGE_MASK_m13;
				range = high_bound - low_bound;
			}
			prev_high_bound = low_bound;
			target_cc = ((goal_bound - low_bound) << 16) / range;
			for (j = 1; j < n_stats_entries; ++j)
				if (target_cc <= cumulative_count[j])
					break;
			if (--j)
				prev_high_bound += (range * cumulative_count[j]) >> 16;
		}
	}
	RED2_RANGE_DECODE_DONE_m13:
		
	// generate derivatives from keysample data
	si4_p = cps->decompressed_ptr + n_derivs;
	if (pos_derivs == TRUE_m13) {
		ui1_p1 = (ui1 *) cps->params.keysample_buffer;
		for (i = n_samps - n_derivs; i--;) {
			if (*ui1_p1 == CMP_POS_DERIV_KEYSAMPLE_FLAG_m13) {
				++ui1_p1;
				overflow_val = 0;
				ui1_p2 = (ui1 *) &overflow_val;
				j = overflow_bytes; do {
					*ui1_p2++ = *ui1_p1++;
				} while (--j);
				*si4_p++ = overflow_val;
			} else {
				*si4_p++ = (si4) *ui1_p1++;
			}
		}
	} else {
		si1_p1 = (si1 *) cps->params.keysample_buffer;
		for (i = n_samps - n_derivs; i--;) {
			if (*si1_p1 == CMP_SI1_KEYSAMPLE_FLAG_m13) {
				overflow_val = 0;
				++si1_p1;
				si1_p2 = (si1 *) &overflow_val;
				j = overflow_bytes; do {
					*si1_p2++ = *si1_p1++;
				} while (--j);
				if (overflow_val & sign_bit)
					overflow_val |= sign_bytes;
				*si4_p++ = overflow_val;
			} else {
				*si4_p++ = (si4) *si1_p1++;
			}
		}
	}
	
	// integrate derivatives
	if ((cps->block_header->block_flags & CMP_BF_SRRED_ENCODING_m13) == 0)  // skip only for SRRED sub-streams (SRRED_decode_m13() integrates once after adding residuals); a standalone RED/PRED/MBE block - including one SRRED redirected to - is flagged as itself & must integrate, even when decoded by an SRRED-configured CPS
		CMP_integrate_m13(cps);
	
	return_m13(TRUE_m13);
}


tern	CMP_RED2_encode_m13(CPS_m13 *cps)
{
	tern				pos_derivs, no_zero_counts, use_raw, force_mbe;
	ui1				*low_bound_high_byte_p, *high_bound_high_byte_p, *ui1_p, ks_flag;
	ui1				*key_p, n_derivs, *comp_p, *symbols, *symbol_map, overflow_bytes;
	ui1				present_enc[256];
	ui2				*bin_counts;
	ui4				*count, n_keysamp_bytes, RED_total_bytes, header_bytes;
	ui4				n_samps, n_deriv_samps, goal_total_counts, bin, fall_through_bytes;
	si4				*deriv_p, *init_val_p, diff, bits_per_samp;
	si4				low_d, high_d;
	ui8				*cumulative_count, *minimum_range;
	ui8				total_counts, range, high_bound, low_bound;
	si8				i, j, k, n_stats_entries, extra_counts, scaled_total_counts;
	CMP_STATISTICS_BIN_m13		*sorted_count, temp_sorted_count;
	CMP_FIXED_BH_m13		*bh;
	CMP_RED_MODEL_FIXED_HDR_m13	*RED_header;
	CMP_MBE_MODEL_FIXED_HDR_m13	*MBE_header;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// compress from input_buffer to bh

	// set algorithm block flag
	bh = cps->block_header;
	bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
	bh->block_flags |= CMP_BF_RED2_ENCODING_m13;

	RED_header = (CMP_RED_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
	n_samps = bh->number_of_samples;
	RED_header->flags = (ui2) 0;
	// pad is WRITTEN TO THE FILE, so it must be deterministic. model_region is a reused CPS buffer &
	// nothing anywhere assigns pad, so it otherwise carries bytes left by whatever block used the buffer
	// before: byte-identical re-encoding is impossible, & arbitrary heap contents land in a WORM archive.
	// (These are also the bytes a per-block derivative offset would live in - see the offset design.)
	memset(RED_header->pad, 0, sizeof(RED_header->pad));

	// zero or one or samples
	if (n_samps <= 1) {
		bh->model_region_bytes = (ui2) CMP_RED_MODEL_FIXED_HDR_BYTES_m13;
		if (bh->number_of_samples == 1) {
			*((si4 *) (cps->params.model_region + bh->model_region_bytes)) = cps->input_buffer[0];  // note: no statistics
			bh->model_region_bytes += sizeof(si4);
		}
		RED_header->n_keysample_bytes = 0;
		RED_header->derivative_level = 0;
		RED_header->n_statistics_bins = 0;
		bh->total_header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh) + bh->model_region_bytes;
		bh->total_block_bytes = G_pad_m13((ui1 *) bh, bh->total_header_bytes, 8);
		return_m13(TRUE_m13);
	}

	// calculate derivatives
	if (cps->direcs.flags & CPS_DF_SRRED_ALGORITHM_m13)  // derivatives already in derivative buffer
		n_derivs = cps->params.derivative_level;
	else
		n_derivs = CMP_differentiate_m13(cps);

	// set up RED arrays
	count = (ui4 *) cps->params.count;
	cumulative_count = (ui8 *) cps->params.cumulative_count;
	minimum_range = (ui8 *) cps->params.minimum_range;
	sorted_count = (CMP_STATISTICS_BIN_m13 *) cps->params.sorted_count;
	symbol_map = (ui1 *) cps->params.symbol_map;

	// set model parameters
	RED_header->derivative_level = n_derivs;
	// RETIRED 2026-08-06: the all-positive model is no longer emitted. The per-block derivative offset covers
	// the same ground (it places the 255-value window where the data is, instead of assuming 128) and covers
	// more of it, so its last caller - VDS times - now relies on the offset. DECODERS still honour the flag:
	// files in the wild may carry it, because before 2026-08-02 it was set by an auto-detect sniff that fired
	// on ordinary sample data. ⚠️ Do NOT reuse bit 1 (see CMP_RED_FLAGS_POSITIVE_DERIVATIVES_m13).
	pos_derivs = FALSE_m13;
	if (cps->direcs.flags & CPS_DF_NO_ZERO_COUNTS_m13) {
		no_zero_counts = TRUE_m13;
		RED_header->flags |= CMP_RED_FLAGS_NO_ZERO_COUNTS_m13;
	} else {
		no_zero_counts = FALSE_m13;
	}
	overflow_bytes = CMP_get_overflow_bytes_m13(cps, CMP_COMPRESSION_MODE_m13, CMP_RED_COMPRESSION_m13);

	// generate count & build keysample array
	
	CMP_derivative_window_m13(pos_derivs, &low_d, &high_d, &ks_flag);
	memset(count, 0, CMP_RED_MAX_STATS_BINS_m13 * sizeof(ui4));
	
	key_p = (ui1 *) cps->params.keysample_buffer;
	deriv_p = cps->params.derivative_buffer + n_derivs;
	n_deriv_samps = n_samps - n_derivs;
	for (i = n_deriv_samps; i--;) {
		diff = *deriv_p++;
		if (diff < low_d || diff > high_d) {
			ui1_p = (ui1 *) &diff;
			++count[*key_p++ = ks_flag];
			j = overflow_bytes; do {
				++count[*key_p++ = *ui1_p++];
			} while (--j);
		} else {
			++count[*key_p++ = (ui1) diff];
		}
	}
	n_keysamp_bytes = (ui4) (key_p - (ui1 *) cps->params.keysample_buffer);

	// early RED-vs-MBE decision, before running the range coder: estimate the RED stream from the count histogram
	// (entropy + 3 model bytes/nonzero symbol - the range coder gets ~entropy, so this is accurate) & compare to the
	// MBE size. If MBE is smaller, skip the range coder entirely & emit MBE. Both outcomes are lossless; the estimate
	// only risks a hair of size near the crossover. (MBE size mirrors the RED2_MBE_FALLBACK_m13 computation below, done
	// in locals so no encode state is mutated; force_mbe then forces the fallback to emit MBE.)
	// Gated on CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13 (default TRUE, so the default path is unchanged): with the
	// directive clear the caller is asking for pure RED (the way to force this encoder for testing), so the estimate
	// is skipped entirely rather than silently diverting - which also makes the clear case faster.
	if (cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13) {
		sf8	est_red_total, mbe_total;

		header_bytes = (ui4) (cps->params.model_region - (ui1 *) bh);
		est_red_total = (sf8) (header_bytes + CMP_RED_MODEL_FIXED_HDR_BYTES_m13 + (n_derivs << 2))  // common + RED model header + initial derivative values
			+ CMP_RED_estimate_bytes_m13(count, (si8) CMP_RED_MAX_STATS_BINS_m13);
		mbe_total = (sf8) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);
		est_red_total *= CMP_MBE_BIAS_m13;  // favour MBE near the crossover (faster encode & decode, for minimal to no cost))
		if (mbe_total < est_red_total) {
			force_mbe = TRUE_m13;
			goto RED2_MBE_FALLBACK_m13;
		}
	}

	// build sorted_count
	if (pos_derivs == TRUE_m13) {
		for (i = n_stats_entries = 0; i < 256; ++i) {
			if (count[i]) {
				sorted_count[n_stats_entries].count = count[i];
				sorted_count[n_stats_entries++].pos_value = (ui1) i;
			}
		}
	} else {  // pos_derivs == FALSE_m13: interleave (to speed up sort)
		for (i = n_stats_entries = 0, j = 255, k = 128; k--; ++i, --j) {
			if (count[i]) {
				sorted_count[n_stats_entries].count = count[i];
				sorted_count[n_stats_entries++].value = (si1) i;
			}
			if (count[j]) {
				sorted_count[n_stats_entries].count = count[j];
				sorted_count[n_stats_entries++].value = (si1) j;
			}
		}
	}
	RED_header->n_statistics_bins = (ui2) n_stats_entries;
	
	// build sorted_count: bubble sort
	i = n_stats_entries;
	do {
		for (j = 0, k = 1; k < i; ++k) {
			if (sorted_count[k - 1].count < sorted_count[k].count) {
				temp_sorted_count = sorted_count[k - 1];
				sorted_count[k - 1] = sorted_count[k];
				sorted_count[k] = temp_sorted_count;
				j = k;  // highest swap index
			}
		}
	} while ((i = j) > 1);
		
	// scale count so that total counts equals (RED_TOTAL_COUNTS - 1)
	goal_total_counts = CMP_RED_TOTAL_COUNTS_m13 - 1;
	if (no_zero_counts == TRUE_m13)
		goal_total_counts -= (256 - n_stats_entries); // reserve 1 count per absent byte value
	total_counts = (ui8) n_keysamp_bytes;
	for (scaled_total_counts = i = 0; i < n_stats_entries; ++i) {
		sorted_count[i].count = (ui4) (((((ui8) goal_total_counts << 1) * (ui8) sorted_count[i].count) + total_counts) / (total_counts << 1));
		if (sorted_count[i].count == 0)
			sorted_count[i].count = 1;
		scaled_total_counts += (si8) sorted_count[i].count;
	}
	extra_counts = ((si8) goal_total_counts - (si8) scaled_total_counts);
	if (extra_counts > 0) {
		do {
			for (i = 0; (i < n_stats_entries) && extra_counts; ++i) {
				++sorted_count[i].count;
				--extra_counts;
			}
		} while (extra_counts);
	} else if (extra_counts < 0) {
		extra_counts = -extra_counts;
		do {
			for (i = n_stats_entries - 1; (i >= 0) && extra_counts; --i) {
				if (sorted_count[i].count > 1) {
					--sorted_count[i].count;
					--extra_counts;
				}
			}
		} while (extra_counts);
	}
	
	// build symbol map, count array & minimum ranges
	for (cumulative_count[0] = i = 0; i < n_stats_entries; ++i) {
		symbol_map[sorted_count[i].pos_value] = (ui1) i;
		cumulative_count[i + 1] = cumulative_count[i] + (ui8) (count[i] = sorted_count[i].count);
		minimum_range[i] = CMP_RED_TOTAL_COUNTS_m13 / count[i];
		if (CMP_RED_TOTAL_COUNTS_m13 > (count[i] * minimum_range[i]))
			++minimum_range[i];
	}
	if (no_zero_counts == TRUE_m13) {
		// complete the model: every byte value absent from the stored bins gets a rank
		// (n_stats..255) in ascending byte order with count 1 - the identical assignment
		// CMP_RED2_decode_m13() reconstructs. Appended after the stored bins, so present-symbol
		// bounds are unchanged; this lets an absent symbol be encoded (e.g. against a prior
		// block's statistics). In same-block encoding no absent symbol occurs, so this is unused
		// here but keeps the encoder & decoder models identical.
		memset(present_enc, 0, sizeof(present_enc));
		for (i = 0; i < n_stats_entries; ++i)
			present_enc[sorted_count[i].pos_value] = 1;
		for (j = n_stats_entries, i = 0; i < 256; ++i) {
			if (present_enc[i] == 0) {
				symbol_map[i] = (ui1) j;
				count[j] = 1;
				cumulative_count[j + 1] = cumulative_count[j] + (ui8) 1;
				minimum_range[j] = CMP_RED_TOTAL_COUNTS_m13;  // 65536 / 1
				++j;
			}
		}
	}

	// copy initial derivative values to output buffer
	init_val_p = (si4 *) (cps->params.model_region + CMP_RED_MODEL_FIXED_HDR_BYTES_m13);
	for (i = 0; i < n_derivs; ++i)
		*init_val_p++ = cps->params.derivative_buffer[i];

	// write scaled counts & symbols into header
	bin_counts = (ui2 *) init_val_p;
	symbols = (ui1 *) (bin_counts + n_stats_entries);
	for (i = 0; i < n_stats_entries; ++i) {
		*bin_counts++ = (ui2) sorted_count[i].count;
		*symbols++ = sorted_count[i].value;
	}
	
	// fill header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	bh->model_region_bytes = (ui2) (symbols - cps->params.model_region);
	bh->total_header_bytes = (ui4) (symbols - (ui1 *) bh);
	RED_header->n_keysample_bytes = n_keysamp_bytes;

	// range encode
	key_p = (ui1 *) cps->params.keysample_buffer;
	comp_p = symbols;
	low_bound_high_byte_p = ((ui1 *) &low_bound) + 5;
	high_bound_high_byte_p = ((ui1 *) &high_bound) + 5;
	low_bound = 0;
	range = CMP_RED_MAXIMUM_RANGE_m13;
	// No bounds check in this loop. The compressed buffer is sized by CMP_max_compressed_bytes_m13(), which
	// covers whatever this encoder can produce under the current directives: with FALL_THROUGH set, the MBE
	// block plus CMP_ESTIMATE_CUSHION_BYTES_m13 - a ceiling FITTED to 3087 matched (estimate, actual) pairs from
	// real & adversarial data at 1k-100k sample blocks, whose residual is a constant, not a fraction of block
	// size; with FALL_THROUGH clear, the range coder's derived worst case, CMP_RED_CODER_WORST_CASE_MULT_m13 x
	// the keysample stream. CMP_allocate_CPS_m13() FLOORS any caller-supplied size at that bound, so the room is
	// there whether or not the caller asked for it - which is what makes dropping the per-dump test safe.
	force_mbe = FALSE_m13;

	for (i = n_keysamp_bytes; i;) {
		for (; range >= minimum_range[bin = symbol_map[*key_p]]; key_p++) {
			high_bound = low_bound + ((range * cumulative_count[bin + 1]) >> 16);
			if (bin)
				low_bound += (range * cumulative_count[bin]) >> 16;
			range = high_bound - low_bound;
			if (!--i)
				break;
		}
		// full dump
		if (low_bound == high_bound || *low_bound_high_byte_p != *high_bound_high_byte_p || !i) {
			--high_bound;  // ensure goal < high bound on decode
			ui1_p = high_bound_high_byte_p;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			*comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--; *comp_p++ = *ui1_p--;
			range = CMP_RED_MAXIMUM_RANGE_m13;
			low_bound = 0;
		} else {  // partial dump
			do {
				*comp_p++ = *high_bound_high_byte_p;
				low_bound <<= 8;
				high_bound <<= 8;
			} while (*low_bound_high_byte_p == *high_bound_high_byte_p);
			low_bound &= CMP_RED_RANGE_MASK_m13;
			high_bound &= CMP_RED_RANGE_MASK_m13;
			range = high_bound - low_bound;
		}
	}

	// finish header (compression algorithms are responsible for filling in: algorithm block flag, total_bytes, header_bytes, model_region_bytes, & model details)
	RED_total_bytes = (si8) (comp_p - (ui1 *) bh);
	bh->total_block_bytes = (ui4) G_pad_m13((ui1 *) bh, RED_total_bytes, 8);

	// fall through to MBE if it is smaller, or forced (RED overflowed the buffer, above)
	if (force_mbe == FALSE_m13 && !(cps->direcs.flags & CPS_DF_FALL_THROUGH_TO_BEST_ENCODING_m13))
		return_m13(TRUE_m13);

RED2_MBE_FALLBACK_m13:

	fall_through_bytes = (ui4) CMP_MBE_estimate_bytes_m13(cps, &use_raw, &bits_per_samp);  // exact MBE size; sets use_raw & bits_per_samp for the emit
	// forced (overflow) => always take MBE; otherwise only if smaller than the RED stream
	if (force_mbe == TRUE_m13 || fall_through_bytes < bh->total_block_bytes) {
		bh->block_flags &= ~CMP_BF_ALGORITHMS_MASK_m13;
		bh->block_flags |= CMP_BF_MBE_ENCODING_m13;
		MBE_header = (CMP_MBE_MODEL_FIXED_HDR_m13 *) cps->params.model_region;
		if (use_raw == TRUE_m13) {
			// cps->input_buffer = unchanged
			MBE_header->minimum_value = cps->params.minimum_sample_value;
			MBE_header->derivative_level = 0;
		} else {
			cps->input_buffer = cps->params.derivative_buffer;
			MBE_header->minimum_value = cps->params.minimum_difference_value;
			MBE_header->derivative_level = n_derivs;
		}
		MBE_header->bits_per_sample = bits_per_samp;
		cps->params.MBE_preprocessed = TRUE_m13;  // handoff via CPS, not the never-zeroed block buffer
		CMP_MBE_encode_m13(cps);
	}

	return_m13(TRUE_m13);
}


sf8	CMP_RED_estimate_bytes_m13(ui4 *cnts, si8 n_bins)
{
	// Estimated RED-encoded size in bytes for a histogram: entropy of the distribution / 8 (the range coder emits
	// ~1 byte per 8 bits of entropy) + 3 model bytes per non-empty symbol (RED's per-bin statistics cost). Empty bins
	// are skipped, so a caller may pass a raw CMP_RED_MAX_STATS_BINS_m13 histogram OR a compacted (nonzero) list.
	// Order-independent (no sort needed). Used to pick RED vs MBE without running the range coder, to score SRRED
	// scales in the count domain, and (summed per category) to estimate PRED.
	si8		i, n_nonzero, total;
	ui4		c;
	sf8		bits, log_total;
	const sf8	*LT;

	LT = globals_m13->tables->CMP_log_table;
	if (LT == NULL) {  // lazy table init (as in CMP_KS_score_m13() etc.)
		CMP_init_tables_m13();
		LT = globals_m13->tables->CMP_log_table;
	}
	for (total = 0, n_nonzero = 0, i = 0; i < n_bins; ++i) {
		if (cnts[i]) {
			total += (si8) cnts[i];
			++n_nonzero;
		}
	}
	if (n_nonzero == 0)
		return((sf8) 0.0);
	// entropy bits = SUM c*log2(total/c) = SUM c*(log2(total) - log2(c)); log2() via the LUT (fallback for counts >= table size)
	log_total = (total < CMP_LOG_TABLE_ENTRIES_m13) ? LT[total] : log2((sf8) total);
	for (bits = (sf8) 0.0, i = 0; i < n_bins; ++i) {
		c = cnts[i];
		if (c)
			bits += (sf8) c * (log_total - ((c < (ui4) CMP_LOG_TABLE_ENTRIES_m13) ? LT[c] : log2((sf8) c)));
	}
	// entropy/8 is the range coder's IDEAL output; scale it by the measured coder overhead (count-quantization + flush)
	// to predict its REAL output. The 3-byte/symbol model term is exact (bytes literally written), so it is not scaled.
	// entropy/8 is the range coder's IDEAL output; scale it by the measured coder overhead (count-quantization + flush)
	// to predict its REAL output. The 3-byte/symbol model term is exact (bytes literally written), so it is not scaled.
	return(((bits / (sf8) 8.0) * CMP_RED_CODER_OVERHEAD_m13) + (sf8) (3 * n_nonzero));
}


tern	CMP_retrend_2_sf8_m13(sf8 *in_x, sf8 *in_y, sf8 *out_y, si8 len, sf8 m, sf8 b)
{
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// retrend data from in_y to out_y at specific x locations
	// if input_buffer == output_buffer retrending data will be done in place
	
	while (len--)
		*out_y++ = CMP_round_si4_m13((sf8) *in_y++ + (m * (sf8) *in_x++) + b);
	
	return_m13(TRUE_m13);
}


tern	CMP_retrend_si4_m13(si4 *in_y, si4 *out_y, si8 len, sf8 m, sf8 b)
{
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	// retrend data from input_buffer to output_buffer
	// if input_buffer == output_buffer retrending data will be done in place
	
	while (len--)
		*out_y++ = CMP_round_si4_m13((sf8) *in_y++ + (b += m));
	
	return_m13(TRUE_m13);
}


tern	CMP_return_buffers_m13(CMP_BUFFERS_m13 *buffers)
{
	si8			i;
	CMP_BUFFER_DEPOT_m13	*depot;

#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	depot = globals_m13->CMP_buffer_depot;
	if (depot == NULL || buffers == NULL)
		return_m13(FALSE_m13);

	pthread_mutex_lock_m13(&depot->mutex);
	for (i = 0; i < depot->count; ++i) {
		if (depot->entries[i].buffers == buffers) {
			depot->entries[i].in_use = FALSE_m13;
			pthread_mutex_unlock_m13(&depot->mutex);
			return_m13(TRUE_m13);
		}
	}
	pthread_mutex_unlock_m13(&depot->mutex);

	return_m13(FALSE_m13);  // not a depot bundle
}


si2	CMP_round_si2_m13(sf8 val)
{
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (isnan(val))
		return_m13(NAN_SI2_m13);
	
	if (val >= (sf8) 0.0) {
		if ((val += (sf8) 0.5) > (sf8) POS_INF_SI2_m13)
			return_m13(POS_INF_SI2_m13);
	} else {
		if ((val -= (sf8) 0.5) < (sf8) NEG_INF_SI2_m13)
			return_m13(NEG_INF_SI2_m13);
	}
	
	return_m13((si2) val);
}


si4	CMP_round_si4_m13(sf8 val)
{
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (isnan(val))
		return_m13(NAN_SI4_m13);
	
	if (val >= (sf8) 0.0) {
		if ((val += (sf8) 0.5) > (sf8) POS_INF_SI4_m13)
			return_m13(POS_INF_SI4_m13);
	} else {
		if ((val -= (sf8) 0.5) < (sf8) NEG_INF_SI4_m13)
			return_m13(NEG_INF_SI4_m13);
	}
	
	return_m13((si4) val);
}


tern	CMP_set_variable_region_m13(CPS_m13 *cps)
{
	ui1			*var_reg_ptr;
	CMP_FIXED_BH_m13	*bh;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	bh = cps->block_header;
	
	// reset variable region parameters
	bh->number_of_records = cps->params.user_number_of_records;
	bh->record_region_bytes = cps->params.user_record_region_bytes;
	bh->parameter_flags = cps->params.user_parameter_flags;
	bh->protected_region_bytes = cps->params.protected_region_bytes;
	bh->discretionary_region_bytes = cps->params.user_discretionary_region_bytes;
	
	// records region
	var_reg_ptr = (ui1 *) bh + CMP_BLOCK_FIXED_HDR_BYTES_m13;  // pointer to start of variable region
	cps->block_records = var_reg_ptr;
	var_reg_ptr += bh->record_region_bytes;
	
	// parameter region
	cps->block_parameters = (ui4 *) var_reg_ptr;
	
	// set library parameter flags
	if (cps->direcs.flags & CPS_DF_DETREND_DATA_m13)
		bh->parameter_flags |= (CMP_PF_INTERCEPT_m13 | CMP_PF_GRADIENT_m13);
	else
		bh->parameter_flags &= ~(CMP_PF_INTERCEPT_m13 | CMP_PF_GRADIENT_m13);
	
	if (cps->direcs.flags & CPS_DF_ALL_NOISE_SCORES_m13)
		bh->parameter_flags |= CMP_PF_NOISE_SCORES_m13;
	else
		bh->parameter_flags &= ~CMP_PF_NOISE_SCORES_m13;
	
	CMP_generate_parameter_map_m13(cps);
	var_reg_ptr += bh->parameter_region_bytes;
	
	// protected region
	// cps->protected_region = var_reg_ptr;
	var_reg_ptr += bh->protected_region_bytes;
	
	// discretionary region
	cps->discretionary_region = var_reg_ptr;
	var_reg_ptr += bh->discretionary_region_bytes;
	
	// variable region bytes
	cps->params.variable_region_bytes = CMP_VARIABLE_REGION_BYTES_v1_m13(bh);
	
	// model region
	// NOTE: model region is NOT considered part of the variable region, but compression algorithms rely on this pointer being set
	// NOTE: model region bytes is set by compression function
	cps->params.model_region = var_reg_ptr;
	
	return_m13(TRUE_m13);
}


tern	CMP_sf8_to_sf4_m13(sf8 *sf8_arr, sf4 *sf4_arr, si8 len, tern round)
{
	sf8	val, pos_inf, neg_inf;
	
#ifdef FT_DEBUG_m13
	G_push_function_m13();
#endif

	if (round == FALSE_m13) {
		while (len--)
			*sf4_arr++ = (sf4) *sf8_arr++;
		
		return_m13(TRUE_m13);
	}

	pos_inf = (sf8) FLT_MAX;
	neg_inf = (sf8) -FLT_MAX;
	
	while (len--) {
		val = *sf8_arr++;
		if (isnan(val)) {
			*sf4_arr++ = NAN;
			continue;
		}
		if (val >= (sf8) 0.0) {
			if ((val += (sf8) 0.5) > pos_inf) {
				*sf4_arr++ = (sf4) pos_inf;
				continue;
			}
		} else if ((val -= (sf8) 0.5) < neg_inf) {
			*sf4_arr++ = (sf4) neg_inf;
			continue;
		}
		*sf4_arr++ = (sf4) val;
	}
	
	return_m13(TRUE_m13);
}


