tern	isem_tryinc_m13(isem_t_m13 *isem)
{
	tern			waited, r_val;
	pid_t_m13		tid;
	struct timespec		tv;


	// if unowned or owner: increments the count, returns TRUE_m13
	// if owned & not owner: returns FALSE_m13
	// if period > 0, it will try once more after a nap

	if (isem->period) {
		waited = FALSE_m13;
		tv.tv_sec = (si8) 0;
		tv.tv_nsec = (si8) isem->period;
	} else {
		waited = TRUE_m13;
	}
	
	isem_lazy_init_m13(isem, __FUNCTION__);
	tid = gettid_m13();
	
	pthread_mutex_lock_m13(&isem->mutex);
	
	r_val = FALSE_m13;
	while (1) {
		if (isem->owner == tid || isem->owner == 0) {
			++isem->count;
			r_val = TRUE_m13;
			break;
		}
		if (waited == TRUE_m13)
			break;
		
		pthread_mutex_unlock_m13(&isem->mutex);
		
		nanosleep_m13(&tv);
		waited = TRUE_m13;

		pthread_mutex_lock_m13(&isem->mutex);
	}

	pthread_mutex_unlock_m13(&isem->mutex);
	
	return(r_val);
}


tern	isem_tryown_m13(isem_t_m13 *isem)
{
	tern			waited, r_val;
	pid_t_m13		tid;
	struct timespec		tv;


	// if unowned or owner takes ownership & returns TRUE_m13
	// if owned not owner returns FALSE_m13
	// if period > 0, it will check once more after a nap
	// returns UNKNOWN_m13 on error

	if (isem->period) {
		waited = FALSE_m13;
		tv.tv_sec = (si8) 0;
		tv.tv_nsec = (si8) isem->period;
	} else {
		waited = TRUE_m13;
	}

	isem_lazy_init_m13(isem, __FUNCTION__);
	
	tid = gettid_m13();

	pthread_mutex_lock_m13(&isem->mutex);

	r_val = FALSE_m13;
	while (1) {
		if (isem->owner == 0) {
			isem->owner = tid;  // take ownership
			r_val = TRUE_m13;
			break;
		} else if (isem->owner == tid) {  // aleady owner
			r_val = TRUE_m13;
			break;
		} // else owned & not owner
		
		if (waited == TRUE_m13)
			break;
	
		pthread_mutex_unlock_m13(&isem->mutex);

		nanosleep_m13(&tv);
		waited = TRUE_m13;
		
		pthread_mutex_lock_m13(&isem->mutex);
	}

	pthread_mutex_unlock_m13(&isem->mutex);
	
	return(r_val);
}


