	res = GetThreadDescription(thread, &w_desc);  // OS allocates w_desc - LocalFree() when done
	if (SUCCEEDED(res)) {
		for (i = 0; i < ((si4) name_len - 1) && w_desc[i]; ++i)  // bounded copy into caller's buffer
			thread_name[i] = (si1) w_desc[i];
		thread_name[i] = 0;
		LocalFree(w_desc);
	}
# endif

	return(thread_name);
