		args[0] = "/bin/sh";
#endif
#ifdef LINUX_m13
		args[0] = "/usr/bin/sh";
#endif
		args[1] = "-c";
		args[2] = command_p;
		args[3] = (si1 *) NULL;
		tmp_command = NULL;
