		close(stdout_pipe[WRITE_END_m13]);  // stdout now on STDOUT_FILENO
		close(stderr_pipe[READ_END_m13]);
		close(stderr_pipe[WRITE_END_m13]);  // stderr now on STDERR_FILENO

